INSERT IGNORE INTO `data_sops` (`id`, `judul`, `isi`, `sop_bagian_id`, `global`, `created_at`, `updated_at`) VALUES
(5, 'Pertanyaan tentang Tuhan', '<p>Ada  seorang pemuda yang lama sekolah diluar negeri,kembali ke tanah  air.sesampainya dirumah ia meminta kepada orang tuanya untuk mencari  seorang guru agama,kiyai atau siapa saja yang bisa menjawab 3  pertanyaan.<br> <br> Akhirnya orang tuanya mendapatkan orang tersebut,seorang kiyai.<br> <br> PEMUDA : Anda siapa dan apakah bisa menjawab pertanyaan2 saya?<br> KIYAI  : Saya hamba Allah dan dengan izin-Nya saya akan menjawab      pertanyaan Anda.<br> PEMUDA : Anda yakin? sedangkan professor dan orang yang pintar saja  tidak mampu menjawab pertanyaan saya.<br> KIYAI  : saya akan mencoba menjawab sejauh kemampuan saya.<br> PEMUDA : saya ada 3 pertanyaan :<br> (1).Kalau memang Tuhan itu ada,tunjukkan wujud Tuhan kepada saya?<br> (2).Apakah yang dinamakan takdir?<br> (3).Kalau syaitan diciptakan dari api kenapa dimasukkan ke nerakayang  dibuat dari api juga,tentu tidak menyakitkan buat setan.sebab mereka  memiliki unsur yang sama.apakah Tuhan tidak berfikir sejauh itu?<br> <br> Tiba-tiba kiyai tersebut menampar pipi pemuda tersebut dengan keras.<br> <br> PEMUDA : (sambil menahan sakit) Kenapa? Anda marah kepada saya?<br> KIYAI  : Saya tidak marah...tamparan itu adalah jawaban saya atas 3 pertanyaan yang Anda ajukan kepada saya.<br> PEMUDA : Saya sungguh2 tidak mengerti!<br> KIYAI  : Bagaimana rasanya tamparan saya?<br> PEMUDA : Tentu saja saya merasakan sakit.<br> KIYAI  : Jadi Anda percaya sakit itu ada?<br> PEMUDA : Ya!<br> KIYAI  : Tunjukan pada saya waujud sakit itu?<br> PEMUDA : Saya tidak bisa.<br> KIYAI  : Itulah jawaban saya untuk pertanyaan pertama...kita semua merasakan kewujudan Tuhan tanpa mampu melihat wujud-Nya. <br> KIYAI  : Apakah tadi malam Anda bermimpi akan ditampar oleh saya?<br> PEMUDA : Tidak.<br> KIYAI  : Apakah terfikir oleh Anda akan menerima tamparan dari saya hari ini?<br> PEMUDA : Tidak.<br> KIYAI  : Itulah yang dinamakan takdir.<br> KIYAI  : Terbuat dari apa tangan yang saya gunakan untuk menampar Anda?<br> PEMUDA : Kulit.<br> KIYAI  : Terbuat dari apa pipi Anda?<br> PEMUDA : Kulit.<br> KIYAI  : Bagaimana rasanya tamparan saya?<br> PEMUDA : Tentu saja sakit.<br> KIYAI  : Itulah jawaban saya untuk pertanyaan ketiga...walaupun setan  dijadikan dari api dan neraka juga terbuat dari api,maka jika Tuhan  menghendaki maka neraka akan menjadi tempatnya menyakitkan untuk setan.<br> <br> HIKMAH : ilmu merupakan harta abstrak titipan Allah kepada seluruh  manusia yang akan bertambah bila diamalkan. salah satu pengamalannya  adalah dengan membagi2kan ilmu itu kepada yang membutuhkan. janganlah  sombong dengan ilmu yang sedikit,karena jika Allah SWT berkehendak maka  ilmu itu akan sirna sekejap. beritahulah orang yang tidak tahu.  tunjukilah orang yang meminta petunjuk. amalkan ilmu itu sebatas yang  mengaku mampu...Amin.</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:51:26'),
(7, 'Hadits 1: Ikhlas', '<p>Dari Amirul Mu’minin, Abi Hafs Umar bin Al Khottob radiallahuanhu, dia  berkata: Saya mendengar Rasulullah Shallallahu’alaihi wasallam bersabda :  Sesungguhnya setiap perbuatan tergantung niatnya. Dan sesungguhnya  setiap orang (akan dibalas) berdasarkan apa yang dia niatkan. Siapa yang  hijrahnya karena (ingin mendapatkan keridhaan) Allah dan Rasul-Nya,  maka hijrahnya kepada (keridhaan) Allah dan Rasul-Nya. Dan siapa yang  hijrahnya karena dunia yang dikehendakinya atau karena wanita yang ingin  dinikahinya maka hijrahnya (akan bernilai sebagaimana) yang dia  niatkan.<br> <br> (Riwayat dua imam hadits, Abu Abdullah Muhammad bin Isma’il bin Ibrahim  bin Al Mughirah bin Bardizbah Al Bukhori dan Abu Al Husain, Muslim bin  Al Hajjaj bin Muslim Al Qusyairi An Naishaburi dan kedua kitab Shahihnya  yang merupakan kitab yang paling shahih yang pernah dikarang) .</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:51:26'),
(8, 'Hadits 2: Iman, Islam, dan Ihsan', 'Dari Umar radhiallahuanhu juga dia berkata : Ketika kami duduk-duduk disisi Rasulullah Shallallahu’alaihi wasallam suatu hari tiba-tiba datanglah seorang laki-laki yang mengenakan baju yang sangat putih dan berambut sangat hitam, tidak tampak padanya bekas-bekas perjalanan jauh dan tidak ada seorangpun diantara kami yang mengenalnya. Hingga kemudian dia duduk dihadapan Nabi lalu menempelkan kedua lututnya kepada kepada lututnya (Rasulullah Shallallahu’alaihi wasallam) seraya berkata: “ Ya Muhammad, beritahukan aku tentang Islam ?”, maka bersabdalah Rasulullah Shallallahu’alaihi wasallam : “ Islam adalah engkau bersaksi bahwa tidak ada Ilah (Tuhan yang disembah) selain Allah, dan bahwa Nabi Muhammad adalah utusan Allah, engkau mendirikan shalat, menunaikan zakat, puasa Ramadhan dan pergi haji jika mampu “, kemudian dia berkata: “ anda benar “. Kami semua heran, dia yang bertanya dia pula yang membenarkan. Kemudian dia bertanya lagi: “ Beritahukan aku tentang Iman “. Lalu beliau bersabda: “ Engkau beriman kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya, rasul-rasul-Nya dan hari akhir dan engkau beriman kepada takdir yang baik maupun yang buruk “, kemudian dia berkata: “ anda benar“. Kemudian dia berkata lagi: “ Beritahukan aku tentang ihsan “. Lalu beliau bersabda: “ Ihsan adalah engkau beribadah kepada Allah seakan-akan engkau melihatnya, jika engkau tidak melihatnya maka Dia melihat engkau” . Kemudian dia berkata: “ Beritahukan aku tentang hari kiamat (kapan kejadiannya)”. Beliau bersabda: “ Yang ditanya tidak lebih tahu dari yang bertanya “. Dia berkata: “ Beritahukan aku tentang tanda-tandanya “, beliau bersabda: “ Jika seorang hamba melahirkan tuannya dan jika engkau melihat seorang bertelanjang kaki dan dada, miskin dan penggembala domba, (kemudian) berlomba-lomba meninggikan bangunannya “, kemudian orang itu berlalu dan aku berdiam sebentar. Kemudian beliau (Rasulullah) bertanya: “ Tahukah engkau siapa yang bertanya ?”. aku berkata: “ Allah dan Rasul-Nya lebih mengetahui “. Beliau bersabda: “ Dia adalah Jibril yang datang kepada kalian (bermaksud) mengajarkan agama kalian “.<br>\r\n(Riwayat Muslim) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(9, 'Hadits 3: Rukun Islam', 'Dari Abu Abdurrahman, Abdullah bin Umar bin Al-Khottob radiallahuanhuma dia berkata : Saya mendengar Rasulullah Shallallahu’alaihi wasallam bersabda : Islam dibangun diatas lima perkara; Bersaksi bahwa tiada Ilah yang berhak disembah selain Allah dan bahwa nabi Muhammad utusan Allah, menegakkan shalat, menunaikan zakat, melaksanakan haji dan puasa Ramadhan.<br>\r\n(Riwayat Turmuzi dan Muslim) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(10, 'Hadits 4: Nasib Manusia Telah Ditetapkan', '<p>Dari Abu Abdurrahman Abdullah bin Mas’ud radiallahuanhu beliau berkata : Rasulullah Shallallahu’alaihi wasallam menyampaikan kepada kami dan beliau adalah orang yang benar dan dibenarkan : Sesungguhnya setiap kalian dikumpulkan penciptaannya di perut ibunya sebagai setetes mani selama empat puluh hari, kemudian berubah menjadi setetes darah selama empat puluh hari, kemudian menjadi segumpal daging selama empat puluh hari. Kemudian diutus kepadanya seorang malaikat lalu ditiupkan padanya ruh dan dia diperintahkan untuk menetapkan empat perkara : menetapkan rizkinya, ajalnya, amalnya dan kecelakaan atau kebahagiaannya. Demi Allah yang tidak ada Ilah selain-Nya, sesungguhnya di antara kalian ada yang melakukan perbuatan ahli surga hingga jarak antara dirinya dan surga tinggal sehasta akan tetapi telah ditetapkan baginya ketentuan, dia melakukan perbuatan ahli neraka maka masuklah dia ke dalam neraka. sesungguhnya di antara kalian ada yang melakukan perbuatan ahli neraka hingga jarak antara dirinya dan neraka tinggal sehasta akan tetapi telah ditetapkan baginya ketentuan, dia melakukan perbuatan ahli surga maka masuklah dia ke dalam surga. (Riwayat Bukhori dan Muslim).</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:51:26'),
(11, 'Hadits 5: Perbuatan Bid’ah Tertolak', 'Dari Ummul Mu’minin; Ummu Abdillah; Aisyah radhiallahuanha dia berkata : Rasulullah Shallallahu’alaihi wasallam bersabda : Siapa yang mengada-ada dalam urusan (agama) kami ini yang bukan (berasal) darinya), maka dia tertolak. (Riwayat Bukhori dan Muslim), dalam riwayat Muslim disebutkan: siapa yang melakukan suatu perbuatan (ibadah) yang bukan urusan (agama) kami, maka dia tertolak. ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:37:09'),
(12, 'Hadits 6: Dalil Haram dan Halal Telah Jelas', 'Dari Abu Abdillah Nu’man bin Basyir radhiallahuanhu dia berkata: Saya mendengar Rasulullah Shallallahu’alaihi wasallam bersabda: Sesungguhnya yang halal itu jelas dan yang haram itu jelas. Di antara keduanya terdapat perkara-perkara yang syubhat (samar-samar) yang tidak diketahui oleh orang banyak. Maka siapa yang takut terhadap syubhat berarti dia telah menyelamatkan agama dan kehormatannya. Dan siapa yang terjerumus dalam perkara syubhat, maka akan terjerumus dalam perkara yang diharamkan. Sebagaimana penggembala yang menggembalakan hewan gembalaannya disekitar (ladang) yang dilarang untuk memasukinya, maka lambat laun dia akan memasukinya. Ketahuilah bahwa setiap raja memiliki larangan dan larangan Allah adalah apa yang Dia haramkan. Ketahuilah bahwa dalam diri ini terdapat segumpal daging, jika dia baik maka baiklah seluruh tubuh ini dan jika dia buruk, maka buruklah seluruh tubuh; ketahuilah bahwa dia adalah hati “.<br>\r\n(Riwayat Bukhori dan Muslim) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(13, 'Hadits 7: Agama Adalah Nasihat', 'Dari Abu Ruqoyah Tamim Ad Daari radhiallahuanhu, sesungguhnya Rasulullah Shallallahu’alaihi wasallam bersabda : Agama adalah nasehat, kami berkata : Kepada siapa ? beliau bersabda : Kepada Allah, kitab-Nya, Rasul-Nya dan kepada pemimpan kaum muslimin dan rakyatnya.<br>\r\n(Riwayat Bukhori dan Muslim) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(14, 'Hadits 8: Perintah Memerangi Manusia Yang Tidak Sholat dan Tidak Mengeluarkan Zakat', 'Dari Ibnu Umar radhiallahuanhuma sesungguhnya Rasulullah Shallallahu’alaihi wasallam bersabda : Aku diperintahkan untuk memerangi manusia hingga mereka bersaksi bahwa tidak ada Ilah selain Allah dan bahwa Muhammad adalah Rasulullah, menegakkan shalat, menunaikan zakat. Jika mereka melakukan hal itu maka darah dan harta mereka akan dilindungi kecuali dengan hak Islam dan perhitungan mereka ada pada Allah Subhanahu wata\'ala.<br>\r\n(Riwayat Bukhori dan Muslim) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(15, 'Hadits 9: Melaksanakan Perintah Sesuai Kemampuan', '<p>Dari Abu Hurairah Abdurrahman bin Sakhr radhiallahuanhu dia berkata : Saya mendengar Rasulullah Shallallahu’alaihi wasallam bersabda : Apa yang aku larang hendaklah kalian menghindarinya dan apa yang aku perintahkan maka hendaklah kalian laksanakan semampu kalian. Sesungguhnya kehancuran orang-orang sebelum kalian adalah karena banyaknya pertanyaan mereka (yang tidak berguna) dan penentangan mereka terhadap nabi-nabi mereka. (Bukhori dan Muslim)</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(16, 'Hadits 10: Makanlah Dari Rizki Yang Halal', 'Dari Abu Hurairah radhiallahuanhu dia berkata : Rasulullah Shallallahu’alaihi wasallam bersabda : Sesungguhnya Allah ta’ala itu baik, tidak menerima kecuali yang baik. Dan sesungguhnya Allah memerintahkan orang beriman sebagaimana dia memerintahkan para rasul-Nya dengan firmannya : Wahai Para Rasul makanlah yang baik-baik dan beramal shalihlah. Dan Dia berfirman : Wahai orang-orang yang beriman makanlah yang baik-baik dari apa yang Kami rizkikan kepada kalian. Kemudian beliau menyebutkan ada seseorang melakukan perjalan jauh dalam keadaan kumal dan berdebu. Dia memanjatkan kedua tangannya ke langit seraya berkata : Yaa Robbku, Ya Robbku, padahal makanannya haram, minumannya haram, pakaiannya haram dan kebutuhannya dipenuhi dari sesuatu yang haram, maka (jika begitu keadaannya) bagaimana doanya akan dikabulkan.<br>\r\n(Riwayat Muslim). ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(17, 'Hadits 11: Tinggalkanlah Keragu-Raguan', 'Dari Abu Muhammad Al Hasan bin Ali bin Abi Thalib, cucu Rasulullah Shallallahu’alaihi wasallam dan kesayangannya dia berkata : Saya menghafal dari Rasulullah Shallallahu\'alaihi wasallam (sabdanya): Tinggalkanlah apa yang meragukanmu kepada apa yang tidak meragukanmu.<br>\r\n(Riwayat Turmuzi dan dia berkata: Haditsnya hasan shoheh) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(18, 'Hadits 12: Meninggalkan Yang Tidak Bermanfaat', 'Dari Abu Hurairah radhiallahunhu dia berkata : Rasulullah Shallallahu’alaihi wasallam bersabda : Merupakan tanda baiknya Islam seseorang, dia meninggalkan sesuatu yang tidak berguna baginya .<br>\r\n(Hadits Hasan riwayat Turmuzi dan lainnya) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(19, 'Hadits 13: Mencintai Milik Saudaranya Seperti Ia Mencintai Milik Sendiri', 'Dari Abu Hamzah, Anas bin Malik radiallahuanhu, pembantu Rasulullah Shallallahu’alaihi wasallam dari Rasulullah Shallallahu’alaihi wasallam, beliau bersabda: Tidak beriman salah seorang diantara kamu hingga dia mencintai saudaranya sebagaimana dia mencintai dirinya sendiri.<br>\r\n(Riwayat Bukhori dan Muslim) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(20, 'Hadits 14: Larangan Berzina, Membunuh, dan Murtad', 'Dari Ibnu Mas’ud radiallahuanhu dia berkata : Rasulullah Shallallahu’alaihi wasallam bersabda : Tidak halal darah seorang muslim yang bersaksi bahwa tidak ada Ilah selain Allah dan bahwa saya (Rasulullah Shallallahu’alaihi wasallam) adalah utusan Allah kecuali dengan tiga sebab : Orang tua yang berzina, membunuh orang lain (dengan sengaja), dan meninggalkan agamanya berpisah dari jamaahnya.<br>\r\n(Riwayat Bukhori dan Muslim) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(21, 'Hadits 15: Berkata Yang Baik atau Diam', 'Dari Abu Hurairah radhiallahuanhu, sesungguhnya Rasulullah Shallallahu’alaihi wasallam bersabda: Siapa yang beriman kepada Allah dan hari akhir hendaklah dia berkata baik atau diam, siapa yang beriman kepada Allah dan hari akhir hendaklah dia menghormati tetangganya dan barangsiapa yang beriman kepada Allah dan hari akhir maka hendaklah dia memuliakan tamunya (Riwayat Bukhori dan Muslim) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:37:09'),
(22, 'Hadits 16: Jangan Marah', 'Dari Abu Hurairah radhiallahuanhu sesungguhnya seseorang bertanya kepada Rasulullah sholallohu ‘alaihi wa sallam : (Ya Rasulullah) nasihatilah saya. Beliau bersabda : Jangan kamu marah. Beliau menanyakan hal itu berkali-kali. Maka beliau bersabda : Jangan engkau marah.<br>\r\n(Riwayat Bukhori ) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(23, 'Hadits 17: Berbuat Baik Dalam Segala Urusan', 'Dari Abu Ya’la Syaddad bin Aus radhiallahuanhu dari Rasulullah shollallohu ‘alaihi wa sallam bersabda : Sesungguhnya Allah telah menetapkan perbuatan baik (ihsan) atas segala sesuatu . Jika kalian membunuh maka berlakulah baik dalam hal tersebut. Jika kalian menyembelih berlakulah baik dalam hal itu,hendaklah kalian mengasah pisaunya dan menyenangkan hewan sembelihannya. (Riwayat Muslim) <br>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(24, 'Hadits 18: Kebaikan Menghapus Kesalahan', 'Dari Abu Zar, Jundub bin Junadah dan Abu Abdurrahman, Mu’az bin Jabal radhiallahuanhuma dari Rasulullah Shallallahu’alaihi wasallam beliau bersabda : Bertakwalah kepada Allah dimana saja kamu berada, iringilah keburukan dengan kebaikan niscaya menghapusnya dan pergauilah manusia dengan akhlak yang baik “<br>\r\n(Riwayat Turmuzi, dia berkata haditsnya hasan, pada sebagian cetakan<br>\r\ndikatakan hasan shahih). ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(25, 'Hadits 20: Milikilah Sifat Malu', 'Dari Abu Mas’ud Uqbah bin Amr Al Anshary Al Badry radhiallahuanhu dia berkata: Rasulullah shollallohu ‘alaihi wa sallam bersabda : Sesungguhnya ungkapan yang telah dikenal orang-orang dari ucapan nabi-nabi terdahulu adalah : Jika engkau tidak malu perbuatlah apa yang engkau suka<br>\r\n(Riwayat Bukhori) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32');
INSERT IGNORE INTO `data_sops` (`id`, `judul`, `isi`, `sop_bagian_id`, `global`, `created_at`, `updated_at`) VALUES
(26, 'Hadits 21: Istiqomah', 'Dari Abu Amr, -ada juga yang mengatakan- Abu ‘Amrah, Sufyan bin Abdillah Ats Tsaqofi radhiallahuanhu dia berkata, saya berkata : Wahai Rasulullah shollallohu ‘alaihi wa sallam, katakan kepada saya tentang Islam sebuah perkataan yang tidak saya tanyakan kepada seorangpun selainmu. Beliau bersabda: Katakanlah: saya beriman kepada Allah, kemudian berpegang teguhlah.<br>\r\n(Riwayat Muslim). ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(27, 'Hadits 22: Melaksanakan Syariat Islam', '<p>Dari Abu Abdullah, Jabir bin Abdullah Al Anshary radhiallahuanhuma :<br> Seseorang bertanya kepada Rasulullah shollallohu ‘alaihi wa sallam, seraya<br> berkata : Bagaimana pendapatmu jika saya melaksanakan shalat yang wajib,<br> berpuasa Ramadhan, Menghalalkan yang halal dan mengharamkan yang haram<br> dan saya tidak tambah sedikitpun, apakah saya akan masuk surga ?. Beliau<br> bersabda : Ya.<br> (Riwayat Muslim)</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(28, 'Hadits 23: Suci Adalah Bagian Dari Iman', 'Dari Abu Malik Al Haritsy bin ‘Ashim Al ‘Asy’ary radhiallahuanhu dia berkata : Rasulullah shollallohu ‘alaihi wa sallam bersabda : Bersuci adalah bagian dari iman, Al Hamdulillah dapat memenuhi timbangan, Subhanallah dan Al Hamdulillah dapat memenuhi antara langit dan bumi, Sholat adalah cahaya, shadaqah adalah bukti, Al Quran dapat menjadi saksi yang meringankanmu atau yang memberatkanmu. Semua manusia berangkat menjual dirinya, ada yang membebaskan dirinya (dari kehinaan dan azab) ada juga yang menghancurkan dirinya.<br>\r\n(Riwayat Muslim). ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(29, 'Hadits 24: Larangan Berbuat Zalim', 'Dari Abu Dzar Al Ghifari radhiallahuanhu dari Rasulullah shollallohu ‘alaihi wa sallam sebagaimana beliau riwayatkan dari Rabbnya Azza Wajalla bahwa Dia berfirman: Wahai hambaku, sesungguhya aku telah mengharamkan kezaliman atas diri-Ku dan Aku telah menetapkan haramnya (kezaliman itu) diantara kalian, maka janganlah kalian saling berlaku zalim. Wahai hambaku semua kalian adalah sesat kecuali siapa yang Aku beri hidayah, maka mintalah hidayah kepada-Ku niscaya Aku akan memberikan kalian hidayah. Wahai hambaku, kalian semuanya kelaparan kecuali siapa yang aku berikan kepadanya makanan, maka mintalah makan kepada-Ku niscaya Aku berikan kalian makanan. Wahai hamba-Ku, kalian semuanya telanjang kecuali siapa yang aku berikan kepadanya pakaian, maka mintalah pakaian kepada-Ku niscaya Aku berikan kalian pakaian. Wahai hamba-Ku kalian semuanya melakukan kesalahan pada malam dan siang hari dan Aku mengampuni dosa semuanya, maka mintalah ampun kepada-Ku niscaya akan Aku ampuni. Wahai hamba-Ku sesungguhnya tidak ada kemudharatan yang dapat kalian lakukan kepada-Ku sebagaimana tidak ada kemanfaatan yang kalian berikan kepada- Ku. Wahai hambaku seandainya sejak orang pertama di antara kalian sampai orang terakhir, dari kalangan manusia dan jin semuanya berada dalam keadaan paling bertakwa di antara kamu, niscaya hal tersebut tidak menambah kerajaan-Ku sedikitpun. Wahai hamba-Ku seandainya sejak orang pertama di antara kalian sampai orang terakhir, dari golongan manusia dan jin di antara kalian, semuanya seperti orang yang paling durhaka di antara kalian, niscaya hal itu mengurangi kerajaan-Ku sedikitpun juga. Wahai hamba-Ku, seandainya sejak orang pertama di antara kalian sampai orang terakhir semuanya berdiri di sebuah bukit lalu kalian meminta kepada-Ku, lalu setiap orang yang meminta Aku penuhi, niscaya hal itu tidak mengurangi apa yang ada pada-Ku kecuali bagaikan sebuah jarum yang dicelupkan di tengah lautan. Wahai hamba-Ku, sesungguhnya semua perbuatan kalian akan diperhitungkan untuk kalian kemudian diberikan balasannya, siapa yang banyak mendapatkan kebaikaan maka hendaklah dia bersyukur kepada Allah dan siapa yang menemukan selain (kebaikan) itu janganlah ada yang dicela kecuali dirinya.<br>\r\n(Riwayat Muslim) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(30, 'Hadits 25: Shadaqah', 'Dari Abu Dzar radhiallahuanhu : Sesungguhnya sejumlah orang dari shahabat Rasulullah shollallohu ‘alaihi wa sallam berkata kepada Rasulullah shollallohu ‘alaihi wa sallam: “ Wahai Rasululullah, orang-orang kaya telah pergi dengan membawa pahala yang banyak, mereka shalat sebagaimana kami shalat, mereka puasa sebagaimana kami puasa dan mereka bersedekah dengan kelebihan harta mereka (sedang kami tidak dapat melakukannya). (Rasulullah shollallohu ‘alaihi wa sallam) bersabda : Bukankah Allah telah menjadikan bagi kalian jalan untuk bersedekah ? : Sesungguhnya setiap tashbih merupakan sedekah, setiap takbir merupakan sedekah, setiap tahmid merupakan sedekah, setiap tahlil merupakan sedekah, amar ma’ruf nahi munkar merupakan sedekah dan setiap kemaluan kalian merupakan sedekah. Mereka bertanya : Ya Rasulullah masakah dikatakan berpahala seseorang diantara kami yang menyalurkan syahwatnya ?, beliau bersabda : Bagaimana pendapat kalian seandainya hal tersebut disalurkan dijalan yang haram, bukankah baginya dosa ?, demikianlah halnya jika hal tersebut diletakkan pada jalan yang halal, maka baginya mendapatkan pahala.<br>\r\n(Riwayat Muslim) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(31, 'Hadits 26: Perbuatan Baik Adalah Shadaqah', 'Dari Abu Hurairah radhiallahuanhu dia berkata : Rasulullah shollallohu ‘alaihi wa sallam bersabda : Setiap anggota tubuh manusia wajib disedekahi, setiap hari dimana matahari terbit lalu engkau berlaku adil terhadap dua orang (yang bertikai) adalah sedekah, engkau menolong seseorang yang berkendaraan lalu engkau bantu dia untuk naik kendaraanya atau mengangkatkan barangnya adalah sedekah, ucapan yang baik adalah sedekah, setiap langkah ketika engkau berjalan menuju shalat adalah sedekah dan menghilangkan gangguan dari jalan adalah sedekah.<br>\r\n(Riwayat Bukhori dan Muslim) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(32, 'Hadits 27: jauhilah Perbuatan yang Meresahkan', '<p>Dari Nawwas bin Sam’an radhiallahuanhu, dari Rasulullah shollallohu  ‘alaihi wa sallam beliau bersabda : “Kebaikan adalah akhlak yang baik,  dan dosa adalah apa yang terasa mengaggu jiwamu dan engkau tidak suka  jika diketahui manusia “<br> (Riwayat Muslim)<br> <br> Dan dari Wabishah bin Ma’bad radhiallahuanhu dia berkata : Saya  mendatangi Rasulullah Shallallahu\'alaihi wasallam, lalu beliau bersabda :  Engkau datang untuk menanyakan kebaikan ?, saya menjwab : Ya. Beliau  bersabda : Mintalah pendapat dari hatimu, kebaikan adalah apa yang jiwa  dan hati tenang karenanya, dan dosa adalah apa yang terasa mengganggu  jiwa dan menimbulkan keragu-raguan dalam dada, meskipun orang-orang  memberi fatwa kepadamu dan mereka membenarkannya.<br> (Hadits hasan kami riwayatkan dari dua musnad Imam Ahmad bin Hanbal dan<br> Ad Darimi dengan sanad yang hasan)</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(33, 'Hadits 28: Berpegang Teguh Kepada Sunnah', 'Dari Abu Najih Al Irbadh bin Sariah radhiallahuanhu dia berkata : Rasulullah shollallohu ‘alaihi wa sallam memberikan kami nasehat yang membuat hati kami bergetar dan air mata kami bercucuran. Maka kami berkata : Ya Rasulullah, seakan-akan ini merupakan nasehat perpisahan, maka berilah kami wasiat. Rasulullah shollallohu ‘alaihi wa sallam bersabda : “ Saya wasiatkan kalian untuk bertakwa kepada Allah ta’ala, tunduk dan patuh kepada pemimpin kalian meskipun yang memimpin kalian adalah seorang budak. Karena di antara kalian yang hidup (setelah ini) akan menyaksikan banyaknya perselisihan. Hendaklah kalian berpegang teguh terhadap ajaranku dan ajaran Khulafaurrasyidin yang mendapatkan petunjuk, gigitlah (genggamlah dengan kuat) dengan geraham. Hendaklah kalian menghindari perkara yang diada- adakan, karena semua perkara bid’ah adalah sesat “<br>\r\n(Riwayat Abu Daud dan Turmuzi, dia berkata : hasan shahih) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(34, 'Hadits 29: Menjaga Lisan', 'Dari Mu’az bin Jabal radhiallahuanhu dia berkata : Saya berkata : Ya Rasulullah, beritahukan saya tentang perbuatan yang dapat memasukkan saya ke dalam surga dan menjauhkan saya dari neraka, beliau bersabda: Engkau telah bertanya tentang sesuatu yang besar, dan perkara tersebut mudah bagi mereka yang dimudahkan Allah ta’ala, : Beribadah kepada Allah dan tidak menyekutukannya sedikitpun, menegakkan shalat, menunaikan zakat, puasa Ramadhan dan pergi haji. Kemudian beliau (Rasulullah shollallohu ‘alaihi wa sallam) bersabda: Maukah engkau aku beritahukan tentang pintu-pintu surga ?; Puasa adalah benteng, Sodaqoh akan mematikan (menghapus) kesalahan sebagaimana air mematikan api, dan shalatnya seseorang di tengah malam (qiyamullail), kemudian beliau membacakan ayat (yang artinya) : “ Lambung mereka jauh dari tempat tidurnya….”. Kemudian beliau bersabda: Maukah kalian aku beritahukan pokok dari segala perkara, tiangnya dan puncaknya ?, aku menjawab : Mau ya Nabi Allah. Pokok perkara adalah Islam, tiangnya adalah shalat dan puncaknya adalah Jihad. Kemudian beliau bersabda : Maukah kalian aku beritahukan sesuatu (yang jika kalian laksanakan) kalian dapat memiliki semua itu ?, saya berkata : Mau ya Rasulullah. Maka Rasulullah memegang lisannya lalu bersabda: Jagalah ini (dari perkataan kotor/buruk). Saya berkata: Ya Nabi Allah, apakah kita akan dihukum juga atas apa yang kita bicarakan ?, beliau bersabda: Ah kamu ini, adakah yang menyebabkan seseorang terjungkel wajahnya di neraka –atau sabda beliau : diatas hidungnya- selain buah dari yang diucapkan oleh lisan-lisan mereka .<br>\r\n(Riwayat Turmuzi dan dia berkata: Haditsnya hasan shahih) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(36, 'Hadits 31: Zuhud', 'Dari Abu Abbas Sahl bin Sa’ad Assa’idi radhiallahuanhu dia berkata : Seseorang mendatangi Rasulullah shollallohu ‘alaihi wa sallam, maka beliau berkata : Wahai Rasulullah, tunjukkan kepadaku sebuah amalan yang jika aku kerjakan, Allah dan manusia akan mencintaiku, maka beliau bersabda: Zuhudlah terhadap dunia maka engkau akan dicintai Allah dan zuhudlah terhadap apa yang ada pada manusia maka engkau akan dicintai manusia.<br>\r\n(Hadits hasan riwayat Ibnu Majah dan lainnya dengan sanad hasan) . ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(37, 'Hadits 32: Tidak Boleh Berbuat Kerusakan', '<p><br> Dari Abu  Sa’id, Sa’ad bin Sinan Al Khudri radhiallahuanhu, sesungguhnya  Rasulullah Shallallahu’alaihi wasallam bersabda : “Tidak boleh melakukan  perbuatan (mudharat) yang mencelakakan diri sendiri dan orang lain“<br> <br> (Hadits hasan diriwayatkan oleh Ibnu Majah dan Daruqutni serta selainnya  dengan sanad yang bersambung, juga diriwayatkan oleh Imam Malik dalam  Muwattho’ secara mursal dari Amr bin Yahya dari bapaknya dari Rasulullah  Shallallahu\'alaihi wasallam, dia tidak menyebutkan Abu Sa’id. Akan  tetapi dia memiliki jalan-jalan yang menguatkan sebagiannya atas  sebagian yang lain)</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(38, 'Hadits 33: Wajib Menunjukkan Bukti', 'Dari Ibnu Abbas radhiallahuanhuma, sesungguhnya Rasulullah Shallallahu’alaihi wasallam bersabda : Seandainya setiap pengaduan manusia diterima, niscaya setiap orang akan mengadukan harta suatu kaum dan darah mereka, karena itu (agar tidak terjadi hal tersebut) maka bagi pendakwa agar mendatangkan bukti dan sumpah bagi yang mengingkarinya<br>\r\n(Hadits hasan riwayat Baihaqi dan lainnya yang sebagiannya terdapat dalam As<br>\r\nShahihain) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(39, 'Hadits 34: Amar Ma’ruf Nahi Munkar', 'Dari Abu Sa’id Al Khudri radiallahuanhu berkata : Saya mendengar Rasulullah shollallohu ‘alaihi wa sallam bersabda : Siapa yang melihat kemunkaran maka rubahlah dengan tangannya, jika tidak mampu maka rubahlah dengan lisannya, jika tidak mampu maka (tolaklah) dengan hatinya dan hal tersebut adalah selemah-lemahnya iman.<br>\r\n(Riwayat Muslim) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(40, 'Hadits 35: Jangan Saling Mendengki', 'Dari Abu Hurairah radhiallahuanhu dia berkata : Rasulullah shollallohu ‘alaihi wa sallam bersabda : Janganlah kalian saling dengki, saling menipu, saling marah dan saling memutuskan hubungan. Dan janganlah kalian menjual sesuatu yang telah dijual kepada orang lain. Jadilah kalian hamba-hamba Allah yang bersaudara. Seorang muslim adalah saudara bagi muslim yang lainnya, (dia) tidak menzaliminya dan mengabaikannya, tidak mendustakannya dan tidak menghinanya. Taqwa itu disini (seraya menunjuk dadanya sebanyak tiga kali). Cukuplah seorang muslim dikatakan buruk jika dia menghina saudaranya yang muslim. Setiap muslim atas muslim yang lain; haram darahnya, hartanya, dan kehormatannya.<br>\r\n(Riwayat Muslim) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(41, 'Hadits 36: Membantu Sesama Muslim', 'Dari Abu Hurairah radhiallahuanhu, dari Rasulullah Shallallahu’alaihi wasallam bersabda : Siapa yang menyelesaikan kesulitan seorang mu’min dari berbagai kesulitan-kesulitan dunia, niscaya Allah akan memudahkan kesulitan- kesulitannya hari kiamat. Dan siapa yang memudahkan orang yang sedang kesulitan niscaya akan Allah mudahkan baginya di dunia dan akhirat dan siapa yang menutupi (aib) seorang muslim Allah akan tutupkan aibnya di dunia dan akhirat. Allah selalu menolong hambanya selama hambanya menolong saudaranya. Siapa yang menempuh jalan untuk mendapatkan ilmu, akan Allah mudahkan baginya jalan ke syurga. Sebuah kaum yang berkumpul di salah satu rumah Allah membaca kitab-kitab Allah dan mempelajarinya di antara mereka, niscaya akan diturunkan kepada mereka ketenangan dan dilimpahkan kepada mereka rahmat, dan mereka dikelilingi malaikat serta Allah sebut-sebut mereka kepada makhluk disisi-Nya. Dan siapa yang lambat amalnya, hal itu tidak akan dipercepat oleh nasabnya.<br>\r\n(Riwayat Muslim) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(42, 'Hadits 37: Pahala Kebaikan Berlipat Ganda', 'Dari Ibnu Abbas radhiallahuanhuma, dari Rasulullah Shallallahu\'alaihi wasallam sebagaimana dia riwayatkan dari Rabbnya Yang Maha Suci dan Maha Tinggi : Sesungguhnya Allah telah menetapkan kebaikan dan keburukan, kemudian menjelaskan hal tersebut : Siapa yang ingin melaksanakan kebaikan kemudian dia tidak mengamalkannya, maka dicatat disisi-Nya sebagai satu kebaikan penuh. Dan jika dia berniat melakukannya dan kemudian melaksanakannya maka Allah akan mencatatnya sebagai sepuluh kebaikan hingga tujuh ratus kali lipat bahkan hingga kelipatan yang banyak. Dan jika dia berniat melaksanakan keburukan kemudian dia tidak melaksanakannya maka baginya satu kebaikan penuh, sedangkan jika dia berniat kemudian dia melaksanakannya Allah<br>\r\nmencatatnya sebagai satu keburukan.<br>\r\n(Riwayat Bukhori dan Muslim dalam kedua shahihnya dengan redaksi ini). ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(43, 'Hadits 39: Perilaku Yang Diampuni', '<p>Dari Ibnu Abbas radiallahuanhuma : Sesungguhnya Rasulullah  Shallallahu’alaihi wasallam bersabda : \"Sesungguhnya Allah ta’ala  memafkan umatku karena aku (disebabkan beberapa hal) : Kesalahan, lupa  dan segala sesuatu yang dipaksa“<br> (Hadits hasan diriwayatkan oleh Ibnu Majah dan Baihaqi dan lainnya)</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(44, 'Hadits 40: Hiduplah Laksana Pengembara', 'Dari Ibnu Umar radhiallahuanhuma berkata : Rasulullah Shallallahu’alaihi wasallam memegang pundak kedua pundak saya seraya bersabda : Jadilah engkau di dunia seakan-akan orang asing atau pengembara “, Ibnu Umar berkata : Jika kamu berada di sore hari jangan tunggu pagi hari, dan jika kamu berada di pagi hari jangan tunggu sore hari, gunakanlah kesehatanmu untuk (persiapan saat) sakitmu dan kehidupanmu untuk kematianmu “<br>\r\n(Riwayat Bukhori) ', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(46, 'Hadits 42: Allah Mengampuni Segala Dosa Orang Yang Tidak Berbuat Syirik', '<p>Dari Anas Radhiallahuanhu dia berkata: Saya mendengar Rasulullah  Shallallahu’alaihi wasallam bersabda: Allah Ta’ala berfirman: \"Wahai  anak Adam, sesungguhnya Engkau berdoa kepada-Ku dan memohon kepada-Ku,  maka akan aku ampuni engkau, Aku tidak peduli (berapapun banyaknya dan  besarnya dosamu). Wahai anak Adam seandainya dosa-dosamu (sebanyak) awan  di langit kemudian engkau minta ampun kepada-Ku niscaya akan Aku ampuni  engkau. Wahai anak Adam sesungguhnya jika engkau datang kepadaku dengan  kesalahan sepenuh bumi kemudian engkau menemuiku dengan tidak  menyekutukan Aku sedikitpun maka akan Aku temui engkau dengan sepenuh  itu pula ampunan “<br> (Riwayat Turmuzi dan dia berkata : haditsnya hasan shahih).</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(47, 'Hadits 19: Mintalah Pertolongan Kepada Allah', '<p><br> Dari Abu Al  Abbas Abdullah bin Abbas radhiallahuanhuma, beliau berkata : Suatu saat  saya berada dibelakang nabi shollallohu ‘alaihi wa sallam, maka beliau  bersabda : Wahai ananda, saya akan mengajarkan kepadamu beberapa  perkara: Jagalah Allah, niscaya dia akan menjagamu, Jagalah Allah  niscaya Dia akan selalu berada dihadapanmu. Jika kamu meminta, mintalah  kepada Allah, jika kamu memohon pertolongan, mohonlah pertolongan kepada  Allah. Ketahuilah sesungguhnya jika sebuah umat berkumpul untuk  mendatangkan manfaat kepadamu atas sesuatu, mereka tidak akan dapat  memberikan manfaat sedikitpun kecuali apa yang telah Allah tetapkan  bagimu, dan jika mereka berkumpul untuk mencelakakanmu atas sesuatu ,  niscaya mereka tidak akan mencelakakanmu kecuali kecelakaan yang telah  Allah tetapkan bagimu. Pena telah diangkat dan lembaran telah kering.<br> <br> (Riwayat Turmuzi dan dia berkata : Haditsnya hasan shahih).</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:51:27');
INSERT IGNORE INTO `data_sops` (`id`, `judul`, `isi`, `sop_bagian_id`, `global`, `created_at`, `updated_at`) VALUES
(48, 'Hadits 38: Wali Allah', 'Dari Abu Hurairah radhiallahuanhu berkata : Rasulullah Shallallahu’alaihi wasallam bersabda : Sesungguhya Allah ta’ala berfirman : Siapa yang memusuhi waliku maka Aku telah mengumumkan perang dengannya. Tidak ada taqarrubnya seorang hamba kepada-Ku yang lebih aku cintai kecuali dengan  beribadah dengan apa yang telah Aku wajibkan kepadanya. Dan hambaku yang selalu mendekatkan diri kepada-Ku dengan nawafil (perkara-perkara sunnah di luar yang fardhu) maka Aku akan mencintainya dan jika Aku telah mencintainya maka Aku adalah pendengarannya yang dia gunakan untuk mendengar, penglihatannya yang dia gunakan untuk melihat, tangannya yang digunakannya untuk memukul dan kakinya yang digunakan untuk berjalan. Jika dia meminta kepadaku niscaya akan aku berikan dan jika dia minta perlindungan dari-Ku niscaya akan Aku lindungi “ Riwayat Bukhori.', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:37:09'),
(49, '5 Kualitas Pensil', '<p>Melihat Neneknya sedang asyik menulis Adi bertanya, \"Nenek sedang menulis apa?\"<br> <br> Mendengar pertanyaan cucunya, sang Nenek berhenti menulis lalu berkata,  \"Adi cucuku, sebenarnya nenek sedang menulis tentang Adi. Namun ada yang  lebih penting dari isi tulisan Nenek ini, yaitu pensil yang sedang  Nenek pakai. Nenek berharap Adi dapat menjadi seperti pensil ini ketika  besar nanti.\"<br> <br> \"Apa maksud Nenek bahwa Adi harus dapat menjadi seperti sebuah pensil?  Lagipula sepertinya pensil itu biasa saja, sama seperti pensil lainnya,\"  jawab Adi dengan bingung.<br> <br> Nenek tersenyum bijak dan menjawab, \"Itu semua tergantung bagaimana Adi  melihat pensil ini. Tahukah kau, Adi, bahwa sebenarnya pensil ini  mempunyai 5 kualitas yang bisa membuatmu selalu tenang dalam menjalani  hidup.\"<br> <br> \"Apakah Nenek bisa menjelaskan lebih detil lagi padaku?\" pinta Adi<br> <br> \"Tentu saja Adi,\" jawab Nenek dengan penuh kasih<br> <br> \"Kualitas pertama, pensil dapat mengingatkanmu bahwa kau bisa melakukan  hal yang hebat dalam hidup ini. Layaknya sebuah pensil ketika menulis,  kau jangan pernah lupa kalau ada tangan yang selalu membimbing langkahmu  dalam hidup ini. Kita menyebutnya tangan Tuhan, Dia akan selalu  membimbing kita menurut kehendakNya\".<br> <br> \"Kualitas kedua, dalam proses menulis, kita kadang beberapa kali harus  berhenti dan menggunakan rautan untuk menajamkan kembali pensil yang  kita pakai. Rautan itu pasti akan membuat pensil menderita. Tapi setelah  proses meraut selesai, pensil itu akan mendapatkan ketajamannya  kembali. Begitu juga denganmu, dalam hidup ini kau harus berani menerima  penderitaan dan kesusahan, karena merekalah yang akan membuatmu menjadi  orang yang lebih baik\".<br> <br> \"Kualitas ketiga, pensil selalu memberikan kita kesempatan untuk  mempergunakan penghapus, untuk memperbaiki kata-kata yang salah. Oleh  karena itu memperbaiki kesalahan kita dalam hidup ini, bukanlah hal yang  jelek. Itu bisa membantu kita untuk tetap berada pada jalan yang  benar\".<br> <br> \"Kualitas keempat, bagian yang paling penting dari sebuah pensil  bukanlah bagian luarnya, melainkan arang yang ada di dalam sebuah  pensil. Oleh sebab itu, selalulah hati-hati dan menyadari hal-hal di  dalam dirimu\".<br> <br> \"Kualitas kelima, adalah sebuah pensil selalu meninggalkan  tanda/goresan. Seperti juga Adi, kau harus sadar kalau apapun yang kau  perbuat dalam hidup ini akan meninggalkan kesan. Oleh karena itu  selalulah hati-hati dan sadar terhadap semua tindakan\".<br> <br> \"Nah, bagaimana Adi? Apakah kau mengerti apa yang Nenek sampaikan?\"<br> <br> \"Mengerti Nek, Adi bangga punya Nenek hebat dan bijak sepertimu.\"<br> <br> Begitu banyak hal dalam kehidupan kita yang ternyata mengandung filosofi  kehidupan dan menyimpan nilai-nilai yang berguna bagi kita. Semoga  memberikan manfaat.<br> <br> source:http://another-reni.blogspot.com</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(50, 'Rizki sudah diatur sama Allah', 'Janganlah kamu merasa, bahwa rezekimu terlambat datangnya, karena sesungguhnya tidaklah seorang hamba akan mati, hingga telah datang kepadanya rezeki terakhir (yang telah ditentukan) untuknya, maka tempuhlah jalan yang baik dalam mencari rezeki, yaitu dengan mengambil yang halal dan meninggalkan yang haram.&amp;quot; (HR. Ibnu Majah, Abdurrazzaq, Ibnu Hibban, dan al-Hakim, dishahihkan oleh al-Albani).', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(51, 'tidak peduli halal haram', '&amp;quot;Akan datang pada manusia suatu saat dimana seseorang tidak peduli dari mana hartanya didapat, apakah dari yang halal atau yang haram.&amp;quot; (HR Ahmad dan Bukhari)', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(52, 'Berita gembira buat orang yang sabar', 'Dan berikanlah berita gembira kepada orang-orang yang sabar, (yaitu) orang-orang yang apabila ditimpa musibah, mereka mengucapkan:”Innaa lillahi wa innaa ilaihi raaji’uun”. Mereka itulah yang mendapatkan keberkatan yang sempurna dan rahmat dari Rabbnya, dan mereka itulah orang-orang yang mendapat petunjuk” (Qs. Al Baqarah: 155-157).', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:37:09'),
(53, 'QS. Ali Imran: 200', ' Hai orang-orang yang beriman, bersabarlah kamu dan kuatkanlah kesabaranmu dan tetaplah bersiap siaga (di perbatasan negerimu) dan bertaqwalah kepada Allah supaya kamu beruntung.', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:37:09'),
(54, 'sabar dalam menghadapi kesulitan', 'Ibnul Qayyim menyatakan: “Apabila seorang mengetahui kebaikan yang ada pada amalan yang diperintahkan dan akibat buruk dan kejelekan yang ada pada amalan yang dilarang sebagaimana mestinya, kemudian ditambah dengan tekad kuat dan motivasi tinggi serta harga diri maka insya Allah akan dapat bersabar dan semua kesulitan dan kesusahan menjadi mudah baginya.<br>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(55, '10 Kepribadian Luar Biasa', '<p>Penulis : Tim AndrieWongso.com<br> <br> <br> Untuk teman-teman di sini, berikut adalah kepribadian-kepribadian yang  Luar Biasa! Kepribadian mana yang sudah/belum Anda miliki?<br> <br> 1. Ketulusan<br> Ketulusan membuat orang lain merasa aman dan dihargai karena yakin tidak  akan dibodohi atau dibohongi. Orang yang tulus selalu mengatakan  kebenaran, tidak suka mengada-ada, pura- pura, mencari-cari alasan atau  memutarbalikkan fakta.<br> <br> 2. Kerendahan Hati<br> Sikap rendah hati mengungkapkan kekuatan. Hanya orang yang kuat jiwanya  yang bisa bersikap rendah hati. Ia seperti padi yang semakin berisi  semakin menunduk. Orang yang rendah hati bisa mengakui dan menghargai  keunggulan orang lain.<br> <br> 3. Kesetiaan<br> Kesetiaan sudah menjadi barang langka &amp; sangat tinggi harganya.  Orang yang setia selalu bisa dipercaya dan diandalkan. Dia selalu  menepati janji, punya komitmen yang kuat, rela berkorban dan tidak suka  berkhianat.<br> <br> 4. Positive Thinking<br> Orang yang bersikap positif (positive thinking) selalu berusaha melihat  segala sesuatu dari kacamata positif, bahkan dalam situasi yang buruk  sekalipun. Dia lebih suka membicarakan kebaikan daripada keburukan orang  lain, lebih suka bicara mengenai harapan daripada keputusasaan, lebih  suka mencari solusi daripada frustasi, lebih suka memuji daripada  mengecam, dan sebagainya.<br> <br> 5. Keceriaan<br> Orang yang ceria adalah orang yang bisa menikmati hidup, tidak suka  mengeluh dan selalu berusaha meraih kegembiraan. Dia bisa mentertawakan  situasi, orang lain, juga dirinya sendiri. Dia punya potensi untuk  menghibur dan mendorong semangat orang lain.<br> <br> 6. Bertanggung jawab<br> Orang yang bertanggung jawab akan melaksanakan kewajibannya dengan  sungguh-sungguh. Kalau melakukan kesalahan, dia berani mengakuinya.  Ketika mengalami kegagalan, dia tidak akan mencari kambing hitam untuk  disalahkan. Bahkan kalau dia merasa kecewa dan sakit hati, dia tidak  akan menyalahkan siapapun. Dia menyadari bahwa dirinya sendirilah yang  bertanggung jawab atas apapun yang dialami dan dirasakannya.<br> <br> 7. Percaya Diri<br> Rasa percaya diri memungkinkan seseorang menerima dirinya sebagaimana  adanya, menghargai dirinya dan menghargai orang lain. Orang yang percaya  diri mudah menyesuaikan diri dengan lingkungan dan situasi yang baru.  Dia tahu apa yang harus dilakukannya dan melakukannya dengan baik.<br> <br> 8. Kebesaran Jiwa<br> Kebesaran jiwa dapat dilihat dari kemampuan seseorang memaafkan orang  lain. Orang yang berjiwa besar tidak membiarkan dirinya dikuasai oleh  rasa benci dan permusuhan. Ketika menghadapi masa-masa sukar dia tetap  tegar, tidak membiarkan dirinya hanyut dalam kesedihan dan keputusasaan.<br> <br> 9. Easy Going<br> Orang yang easy going menganggap hidup ini \'ringan\'. Dia tidak suka  membesar-besarkan masalah kecil atau berusaha mengecilkan  masalah-masalah besar. Dia tidak suka mengungkit masa lalu dan tidak mau  khawatir dengan masa depan. Dia tidak mau pusing dan stres dengan  masalah-masalah yang berada di luar kontrolnya.<br> <br> 10. Empati<br> Empati adalah sifat yang sangat mengagumkan. Orang yang berempati bukan  saja pendengar yang baik tapi juga bisa menempatkan diri pada posisi  orang lain. Ketika terjadi konflik dia selalu mencari jalan keluar  terbaik bagi kedua belah pihak, tidak suka memaksakan pendapat dan  kehendaknya sendiri. Dia selalu berusaha memahami dan mengerti orang  lain.<br> <br> Salam sukses, Luar Biasa!!</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(56, 'Menjadikan Nabi Muhammad sebagai suri tauladan', '<p>Oleh: Aidil Heryana, S.Sosi<br> <br> 1) Kalau ada pakaian yang koyak, Nabi saw menambalnya sendiri tanpa  perlu menyuruh isterinya. Beliau juga memerah susu kambing untuk  keperluan keluarga maupun untuk dijual.<br> <br> 2) Setiap kali pulang ke rumah, bila belum tersaji makanan karena masih  dimasak, sambil tersenyum beliau menyingsingkan lengan bajunya untuk  membantu isterinya di dapur. Aisyah menceritakan bahwa kalau Nabi berada  di rumah, beliau selalu membantu urusan rumahtangga.<br> <br> 3) Jika mendengar azan, beliau cepat-cepat berangkat ke masjid, dan cepat-cepat pula kembali sesudahnya.<br> <br> 4) Pernah beliau pulang menjelang pagi hari. Tentulah beliau teramat  lapar waktu itu. Namun dilihatnya tiada apa pun yang tersedia untuk  sarapan. Bahkan bahan mentah pun tidak ada karena ‘Aisyah belum ke  pasar. Maka Nabi bertanya, “Belum ada sarapan ya Khumaira?’  Aisyah  menjawab dengan agak serba salah, ‘Belum ada apa-apa wahai Rasulullah.’  Rasulullah lantas berkata, ‘Jika begitu aku puasa saja hari ini.’ tanpa  sedikit tergambar rasa kesal di raut wajah beliau.<br> <br> 5) Sebaliknya Nabi saw sangat marah tatkala melihat seorang suami sedang  memukul isterinya. Rasulullah menegur, ‘Mengapa engkau memukul  isterimu?’ Lantas lelaki itu menjawab dengan gementar, “Isteriku sangat  keras kepala! Sudah diberi nasihat dia tetap membangkang juga, jadi aku  pukul dia.” Jelas lelaki itu.<br> “Aku tidak bertanya alasanmu,” sahut Nabi saw.<br> “Aku menanyakan mengapa engkau memukul teman tidurmu dan ibu dari anak-anakmu?”<br> <br> 6) Kemudian Nabi saw bersabda,”Sebaik-baik suami adalah yang paling  baik, kasih dan lemah-lembut terhadap isterinya.’ Prihatin, sabar dan  tawadlu’nya beliau dalam posisinya sebagai kepala keluarga langsung  tidak sedikitpun merubah kedudukannya sebagai pemimpin umat.<br> <br> 7) Pada suatu ketika Nabi saw menjadi imam shalat. Mereka mendengar  bunyi gemeretak seakan sendi-sendi di tubuh Nabi mulia itu bergeser  antara satu dengan yang lain. Akhirnya Rasulullah mengangkat jubahnya.  Para sahabat amat terkejut. Ternyata perut beliau yang kempis, kelihatan  dililit sehelai kain yang berisi batu kerikil, untuk menahan rasa lapar  beliau. Batu-batu kecil itulah yang menimbulkan bunyi gemeretak setiap  kali bergeraknya tubuh beliau.<br> <br> “Ya Rasulullah! Apakah saat engkau menyatakan lapar dan tidak punya  makanan, kemudian kami tidak akan mengusahakannya buat engkau?’<br> <br> Lalu Nabi saw menjawab dengan lembut, “Tidak para sahabatku. Aku tahu,  apa pun akan engkau korbankan demi Rasulmu. Tetapi apakah akan aku jawab  di hadapan ALLAH nanti, apabila aku sebagai pemimpin, menjadi beban  kepada umatnya?’ ‘Biarlah kelaparan ini<br> sebagai hadiah ALLAH buatku, agar umatku kelak tidak ada yang kelaparan  di dunia ini lebih-lebih lagi tiada yang kelaparan di Akhirat kelak.”<br> <br> 8) Nabi saw pernah tanpa rasa canggung sedikitpun makan di sebelah seorang tua yang dipenuhi kudis, miskin dan kotor.<br> <br> 9) Beliaupun hanya diam dan bersabar ketika kain sorbannya ditarik  dengan kasar oleh seorang Arab Badawi hingga berbekas merah di lehernya.  Begitupun dengan penuh rasa kehambaan beliau membersihkan tempat yang  dikencingi seorang arab Badawi di dalam masjid sebelum beliau tegur  dengan lembut perbuatan itu.<br> <br> 10) Kecintaannya yang tinggi terhadap ALLAH swt dan rasa penghambaan  yang sudah menghunjam dalam diri Rasulullah saw menolak sama sekali rasa  ingin diistimewakan (dipertuan).<br> <br> 11) Seolah-olah anugerah kemuliaan dari ALLAH langsung tidak dijadikan  sebab untuknya merasa lebih dari yang lain, ketika di depan keramaian  (publik) maupun saat seorang diri.<br> <br> 12) Pintu Syurga terbuka seluas-luasnya untuk Nabi, namun beliau masih  tetap berdiri di sepinya malam, terus-menerus beribadah hingga pernah  beliau terjatuh lantaran kakinya bengkak-bengkak.<br> <br> 13) Fisiknya sudah tidak mampu menanggung kemauan jiwanya yang tinggi.  Bila ditanya oleh ‘Aisyah, ‘Ya Rasulullah, bukankah engaku telah dijamin  Syurga? Mengapa engkau masih bersusah payah begini?’ Jawab baginda  dengan lembut, ‘Ya ‘Aisyah, bukankah aku ini hanyalah seorang hamba?  Sesungguhnya aku ingin menjadi hamba-Nya yang bersyukur.’</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(57, 'Jangan Bersedih', '<p>“Janganlah kamu bersedih, sesungguhnya Allah beserta kita.” (QS.At-Taubah:40)<br> “Janganlah kamu bersikap lemah, dan janganlah (pula) kamu bersedih hati,  padahal kamulah orang-orang yang paling tinggi (derajatnya), jika kamu  orang-orang yang beriman.” (QS.Ali ‘Imran:139)<br> “Ingatlah, hanya dengan mengingat Allah-lah hati menjadi tenteram.” (QS Ar Ra’d:28)</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(58, 'Kita selalu bertanya dan Al Qur\'an sudah menjawabnya', '<p>1. KITA BERTANYA:  MENGAPA AKU DIUJI?<br> <br> QURAN MENJAWAB:<br> \"Apakah manusia itu mengira bahwa mereka dibiarkan saja mengatakan,\"Kami telah beriman\", sedangkan mereka tidak diuji?<br> Dan sesungguhnya Kami telah menguji orang-orang yang sebelum mereka,  maka sesungguhnya Allah mengetahui orang-orang yg benar dan sesungguhnya  Dia mengetahui orang-orang yang dusta.\"<br> [Surah Al-Ankabut ayat 2-3]<br> <br> 2. KITA BERTANYA: MENGAPA UJIAN SEBERAT INI?<br> <br> QURAN MENJAWAB:<br> \"Allah tidak membebani seseorang itu melainkan sesuai dengan kesanggupannya,\"<br> [Surah Al-Baqarah ayat 286]<br> <br> 3. KITA BERTANYA: MENGAPA AKU TAK DAPAT APA YG AKU IDAM-IDAMKAN?<br> <br> QURAN MENJAWAB:<br> \"Boleh jadi kamu membenci sesuatu padahal ia amat baik bagimu, dan boleh  jadi pula kamu menyukai sesuatu, padahal ia amat buruk bagimu, Allah  mengetahui sedang kamu tidak mengetahui.\"<br> [Surah Al-Baqarah ayat 216]<br> <br> 4. KITA BERTANYA: MENGAPA AKU MERASA FRUSTRASI?<br> <br> QURAN MENJAWAB:<br> \"Janganlah  kamu bersikap lemah. dan janganlah pula kamu bersedih hati,  padahal kamulah orang-orang yang paling tinggi derajatnya, jika kamu  orang-orang yang beriman.\"<br> [Surah Al-Imran ayat 139]<br> <br> 5. KITA BERTANYA: BAGAIMANA AKU HARUS MENGHADAPINYA?<br> <br> QURAN MENJAWAB:<br> \"Dan mintalah pertolongan (kepada Allah)  dengan jalan sabar dan  mengerjakan sholat; dan sesungguhnya shalat itu amatlah berat kecuali  kepada orang-orang yang khusyu\"<br> [Surah Al-Baqarah ayat 45]<br> <br> <br> 6. KITA BERTANYA: APA YANG AKU DAPAT DARIPADA SEMUA INI?<br> <br> QURAN MENJAWAB:<br> \"Sesungguhnya Allah telah membeli dari orang-orang  mu\'min, diri, harta mereka dengan memberikan syurga untuk mereka.<br> [Surah At-Taubat ayat 111]<br> <br> 7. KITA BERTANYA: KEPADA SIAPA AKU BERHARAP?<br> <br> QURAN MENJAWAB:<br> \'Cukuplah Allah bagiku,tidak ada Tuhan selain dariNya. Hanya kepadaNya aku bertawakkal.\"<br> [Surah At-Taubat ayat 129]<br> <br> 8. KITA BERKATA: AKU TAK TAHAN!!!!!!<br> <br> QURAN MENJAWAB:<br> \"......dan janganlah kamu berputus asa dari  rahmat Allah. Sesungguhnya  tiada berputus asa dari rahmat Allah melainkan kaum yang kafir.\"<br> [Surah Yusuf ayat 12] <br> <br> 9. KITA BERTANYA: MENGAPA HATI INI TIDAK TENANG ?<br> <br> QURAN MENJAWAB:<br> (yaitu) orang-orang yang beriman dan hati mereka manjadi tenteram dengan  mengingat Allah. Ingatlah, hanya dengan mengingati Allah-lah hati  menjadi tenteram.<br> [Ar Ra\'d ayat 28]</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'umum' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(65, 'SOP MARKETING', '<p>\r\n	Calon konsumen masuk ( bisa via email, YM, telpon, datang langsung ke kantor,bagian marketing datang langsung ke kantor calon konsumen )</p>\r\n<ol></ol>\r\n<ol></ol>\r\n<ol></ol>\r\n<ol></ol>\r\n<ol></ol>\r\n<ol></ol>\r\n<p>\r\n	1.  Konfirmasi nama dan nama instansi /perusahaan</p>\r\n<p>\r\n	2.  Konfirmasi spec order yang diiinginkan</p>\r\n<p>\r\n	      -   Jenis order</p>\r\n<p>\r\n	      -   Jumlah order</p>\r\n<p>\r\n	      -   Ukuran</p>\r\n<p>\r\n	      -   Bahan yang digunakan</p>\r\n<p>\r\n	      -   Cetakan (full colour/tidak dan 1 muka/ 2 muka)</p>\r\n<p>\r\n	      -   Jenis finishing</p>\r\n<p>\r\n	      -   Dll.(sesuai kebutuhan ordernya)</p>\r\n<p>\r\n	3.  Check harga sesuai dengan spec order yang diinginkan</p>\r\n<p>\r\n	     --- Check harga bisa dilihat di aplikasi Tafio Project-price list atau bisa hitung manual</p>\r\n<p>\r\n	4.  Konfirmasi harga ke calon konsumen (harga belum termasuk ongkos kirim ke luar Bandung)</p>\r\n<p>\r\n	     --- Jika calon konsumen minta penawaran harga, maka dibuatkan form penawaran harga kemudian dikirimkan ke calon konsumen via email/fax/marketing</p>\r\n<p>\r\n	     --- File penawaran harga bisa dilihat di Administrasi/Data/Order/Penawaran</p>\r\n<p>\r\n	5.  Catat data calon konsumen di Form Data Calon Konsumen</p>\r\n<p>\r\n	     --- Form Data Calon Konsumen bisa dilihat diaplikasi tafio project/SOP/marketing/form data calon konsumen</p>\r\n<p>\r\n	6.  Jika calon konsumen sudah setuju dengan harganya, catat data order dengan lengkap</p>\r\n<p>\r\n	     --- Pastikan file yang diberikan sudah layak untuk dicetak (file berupa corel/psd/illustrator, jika file berupa jpeg/pdf pastikan file dengan resolusi tinggi/tidak pecah-300dpi)</p>\r\n<p>\r\n	     --- Buat folder di file project/rutin untuk menyimpan file desain </p>\r\n<p>\r\n	7.  Jika ordernya harus didesain dulu maka konfirmasi ke calon konsumen hal-hal yang berkaitan dengan kebutuhan desain, sbb:</p>\r\n<p>\r\n	      -  Jika calon konsumen datang langsung ke kantor maka diminta untuk mengisi Form Desain</p>\r\n<p>\r\n	      -  Jika calon konsumen via email/YM/tlp maka tanyakan langsung hal-hal yang ada di Form Desain</p>\r\n<p>\r\n	      -  Informasikan ada tambahan biaya desain</p>\r\n<p>\r\n	8.  Untuk konsumen baru pastikan untuk membayar uang DP sesuai dengan ketentuan :</p>\r\n<ol></ol>\r\n<ol></ol>\r\n<ol></ol>\r\n<ol></ol>\r\n<ol></ol>\r\n<p>\r\n	      1. DP 50% Harus ditawarkan diawal (mutlak bagi calon konsumen perusahaan tapi ordernya via marketing luar)</p>\r\n<p>\r\n	      2. DP &lt; 50%, bisa jika :</p>\r\n<p>\r\n	         -   Data calon konsumen lengkap</p>\r\n<p>\r\n	         -   Calon konsumen datang langsung ke kantor tafio</p>\r\n<p>\r\n	         -   Order langsung dari konsumen asli (bukan marketing luar/untuk dijual lagi</p>\r\n<p>\r\n	      3. Tidak pakai DP, bisa jika:</p>\r\n<p>\r\n	         -   Calon konsumen dari perusahaan/instansi (pastikan Data calon konsumen lengkap )</p>\r\n<p>\r\n	         -   Kredibilitas perusahaan/instansi baik</p>\r\n<p>\r\n	         -   Order harus dilengkapi dengan PO langsung dari perusahaan/instansi tersebut</p>\r\n<p>\r\n	     --- Pastikan DP sudah masuk sebelum order di proses</p>\r\n<p>\r\n	9.  Konfirmasikan data ke konsumen</p>\r\n<p>\r\n	      -  Deathline order</p>\r\n<p>\r\n	      -  Jenis pembayaran order (transfer/cash/kontra bon</p>\r\n<p>\r\n	      -  Alamat pengiriman dan jenis pengiriman (diambil/dianter/paket)</p>\r\n<p>\r\n	      -  Nomor kontak (tlp kantor dan hp pribadi) dan alamat email</p>\r\n<p>\r\n	10. Konfirmasikan order ke manager order secara detail dan jelas untuk  diproses</p>\r\n<p>\r\n	11. Berkoordinasi selalu dengan manager order untuk mengetahui progress ordernya</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'marketing' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(71, 'DIVISI SETTING, Tanggung Jawab, Tugas Pokok, Wewenang', '<p>	<strong>DIVISI SETTING</strong></p><p>	 </p><p>	<strong>Tanggung Jawab</strong></p><p>	                Setting adalah salah satu Divisi dari proses percetakan yang memiliki tanggung jawab untuk menyiapkan materi untuk mencapai efektifitas dan efisiensi produksi. Dalam hal ini memuat beberapa poin diantaranya:</p><p>	1. Kecepatan waktu setting</p><p>	2. Ketepatan pemilihan bahan</p><p>	3. Ketepatan pemilihan mesin</p><p>	4. Ketepatan layout desain</p><p>	5. Ketepatan spesifikasi produk dengan keinginan klien</p><p>	6. Kualitas produk yang baik</p><p>	7. Kemudahan proses finishing</p><p>	 </p><p>	<strong>Tugas Pokok</strong></p><p>	                Tugas secara umum adalah menyiapkan materi / bahan untuk dilanjutkan ke proses produksi. Secara garis besar urutan tugas pokok Divisi Setting adalah sebagai berikut:</p><p>	1.  Mempelajari spesifkasi produk yang tercantum dalam Detail Order di Project Manager. Spesifikasi produk meliputi:</p><p>	a.  Nama produk</p><p>	b. Jumlah order</p><p>	c.  Ukuran produk</p><p>	d. Warna</p><p>	e. Mesin yang digunakan</p><p>	f.   Bahan yang digunakan</p><p>	g.  Pelengkap produk</p><p>	h.  Proses finishing</p><p>	i.    Deadline kirim</p><p>	j.    Dan keterangan lainnya yang ada di notes/revisi</p><p>	2.  Cek kembali apakah termasuk produk baru/repeat order</p><p>	3.  Cek kembali ketersediaan kelengkapan proses produksi, seperti:</p><p>	a.   Cek Stok bahan di gudang</p><p>	b.   Cek Stok pisau / rel di gudang finishing</p><p>	c.   Cek Stok pelengkap produk (tali, mika, ring, linen, mata itik, tiang x banner, lem, double tape, matres foil/emboss, kuping map dll)</p><p>	d.   Cek produk sebelumnya</p><p>	e.   Cek dummy produk &amp; dummy warna</p><p>	4.  Melakukan proses setting sesuai dengan jenis produk yang tercantum dalam Standar Operating Procedure, diantaranya adalah sebagai berikut:</p><p>	a.      Standar Setting Produk LJK</p><p>	b.      Standar Setting Produk Kop Surat</p><p>	c.      Standar Setting Produk Amplop</p><p>	d.      Standar Setting Produk Map</p><p>	e.      Standar Setting Produk Notes</p><p>	f.        Standar Setting Produk Kwitansi</p><p>	g.      Standar Setting Produk Paperbag</p><p>	h.      Standar Setting Produk Brosur/Poster</p><p>	i.        Standar Setting Produk Goodiebag</p><p>	j.        Standar Setting Produk Buku/majalah/booklet/proposal</p><p>	          i.      Buku Hekter Tengah</p><p>	          ii.      Buku blok lem</p><p>	          iii.      Buku ring kiri</p><p>	k.       Standar setting buku DSE</p><p>	l.         Standar Setting Produk Stiker</p><p>	m.    Standar Setting Produk Voucher</p><p>	n.      Standar Setting Produk Hangtag</p><p>	o.      Standar Setting Produk Ballpen</p><p>	p.      Standar Setting Produk Box</p><p>	q.      Standar Setting Produk Agenda</p><p>	r.        Standar Setting Produk CD/DVD</p><p>	s.       Standar Setting Produk flashdisk</p><p>	t.        Standar Setting Produk kipas</p><p>	u.      Standar Setting Produk jam dinding</p><p>	v.       Standar Setting Produk sign holder</p><p>	w.     Standar Setting Produk banner, x banner, baligho, beckdrop</p><p>	x.       Standar Setting Produk ID Card</p><p>	y.       Standar Setting Produk sertifikat</p><p>	z.       Standar Setting Produk Undangan</p><p>	aa.   Standar Setting Produk Kartu nama</p><p>	bb.  Standar Setting Produk Kalender</p><p>	cc.    Standar Setting Produk Tas</p><p>	dd.  Prosedur Repeat Order</p><p>	ee.  Prosedur membuat pisau</p><p>	ff.     Prosedur Setting Numerator menggunakan Printer Laser</p><p>	gg.   Prosedur mengisi Job Order/data order</p><p>	hh.  Prosedur melakukan Checklist Hasil Setting</p><p>	ii.       Prosedur pengiriman file produksi ke Divisi Produksi</p><p>	jj.      Prosedur evaluasi kenerja staff Divisi Setting</p><p>	kk.   Prosedur dokumentasi Job Order</p><p>	ll.       Prosedur penyimpanan file</p><p>	mm.   Prosedur Revisi konten/desain</p><p>	nn.  Prosedur Scan photo image</p><p>	oo.  Prosedur cetak photocopy</p><p>	pp.  Standar lipat mesin di Jakarta</p><p>	5.  Melakukan pertemuan rutin sekali dalam sepekan, untuk membahas teknis atau permasalah di Divisi Setting dengan staff.</p><p>	6.  Melakukan checklist menggunakan form checklist setelah proses setting selesai.</p><p>	7.  Mengisi form Job Order untuk proses produksi di Bandung</p><p>	8.  Mengisi /membuat data order untuk proses produksi di Jakarta.</p><p>	9.  Mengirim file produksi ke rekanan (POLA, Zentech, dll), dan mengirim file produksi ke Divisi Produksi di Jakarta (udin@percetakanbandung.com )</p><p>	10. Memback-up file produksi ke CD/DVD blank untuk file dengan ukuran &gt;25 MB (file yang tidak bisa diemail.</p><p>	11. Menyiapkan back up DVD/CD, dummy warna, format cetakan, urutan halaman, format bolak balik cetakan, ke dalam amplop yang akan dikirim ke Divisi Produksi di Jakarta.</p><p>	12. Melakukan revisi file produksi atas saran baik dari Divisi Produksi, Marketing, Finishing, General manajer, atau Direktur.</p><p>	13. Menentukan mesin yang sesuai untuk proses produksi</p><p>	14. Menentukan ukuran bahan yang sesuai untuk proses produksi</p><p>	15. Menyimpan file yg sudah siap cetak ke dalam folder Setting/Hari_ini. Dalam folder Hari_ini terdiri beberapa bagian lagi diantaranya :</p><p>	a. Setting/Hari_ini /Raja print</p><p>	    Adalah untuk proses produksi di Jakarta dan Mengelompokkannya di setiap tanggal dan dikelompokknya ke dalam 3 folder yg berbeda, yaitu folder offet, folder indigo, dan folder spanduk.</p><p>	b. Setting/Hari_ini/pola</p><p>	    Adalah untuk proses produksi di Bandung. Dikelompokkan di setiap tanggal dan memberikan keterangan lengkap tentang detail ordernya.</p><p>	    Contohnya : Box Jeva, bikin CTP full colour, mesin 58. Atau misalnya Spanduk ITB, ukuran 3x1 meter, bahan flexy cina, tanpa laminasi, finishing mata itik., dll</p><p>	c.  Setting/Hari_ini /Ideal pisau</p><p>	d.  Adalah untuk menyimpan file pisau yang akan di buat. Ideal adalah tempat untuk print out pisau di kertas HVS, yang akan ditempel di papan pisau.</p><p>	e.       </p><p>	16.    </p><p>	 </p><p>	 </p><p>	<strong>Wewenang</strong></p><p>	1.  Koordinasi dengan beberapa Divisi</p><p>	       a.  Koordinasi dengan Divisi Marketing terkait dengan spesifikasi produk, kelengkapan bahan/file dari klien.</p><p>	       b. Koordinasi dengan Divisi Produksi, terkait dengan pemilihan bahan &amp; mesin yg sesuai, dan estimasi waktu proses produksi.</p><p>	       c.  Koordinasi dengan Divisi Desain, terkait dengan isi materi desain.</p><p>	       d.  Koordinasi dengan Divisi Finishing, terkait dengan kesesuaian/ketepatan &amp; efisiensi proses finishing terhadap produk.</p><p>	2.  Divisi Setting berhak meminta kelengkapan data, file, spesifikasi produk kepada Divisi Marketing. Seperti contohnya meminta font, file mentah/file asli, sampel /dummy produk yang sudah jadi, sampel warna, sampel ukuran, dll.</p><p>	3.  Divisi Setting mempunyai wewenang untuk memberikan saran/usulan kepada Divisi Marketing (yg akan diteruskan kepada klien) terkait dengan spesifikasi produk (ukuran, warna, bahan, kualitas file, dll).</p><p>	4.  Memberikan usulan konfirmasi terhadap perubahan spesifikasi produk, revisi desain, revisi teks, dll kepada Divisi Marketing.</p><p>	5.  Mengisi form Job Order/Detail Order, sebagai panduan bagi Divisi Produksi.</p><p>	 </p><p>	<strong>Form yang digunakan Divisi Setting</strong></p><p>	1.  Form Checklist Setting</p><p>	2.  Form Job Order Cetak Besar</p><p>	3.  Form Job Order Cetak Toko</p><p>	 </p><p>	<strong>Inventaris yang ada di Divisi Setting</strong></p><p>	1.  Seperangkat PC dengan Spesifikasi minimal Intel Core i3 Dual Core, atau selevel dengannya.</p><p>	2.  Printer laser</p><p>	3.  Printer warna Epson R230</p><p>	4.  Kertas HVS 80 gr/70 gr ukuran A4</p><p>	5.  Kertas inkjet 140 gr double matte ukuran A4</p><p>	6.  Mistar logam 30 cm/40 cm</p><p>	7.  Ball pen</p><p>	8.   Cutter kecil joyko, beserta isi refill</p><p>	9.   Hekter kecil, beserta isi refill</p><p>	10. Gunting kecil</p><p>	11. DVD Room portable (bisa bergantian/meminjam ke Divisi lain)</p><p>	12. Double tape secukupnya</p><p>	13. Lakban secukupnya</p><p>	14. Lem kertas secukupnya</p><p>	 </p><p>	SOP Bagian Setting secara Umum</p><div>	1. Check order yang harus disetting di aplikasi Tafio Project-order-setting.</div><div>	2. Pelajari spec order secara seksama, jika ada yang kurang jelas koordinasikan dengan Bagian Marketing.</div><div>	3. Check file desain, pastikan sudah layak untuk diproses.</div><div>	a. Ukuran desain harus sesuai dengan ukuran order yang diminta. Jika ada ketidak sesuaian, konfirmasikan dengan Bagian Marketing.</div><div>	b. File berupa corel/psd/illustrator, jika file berupa jpeg/pdf pastikan file dengan resolusi tinggi/tidak pecah.</div><div>	c. Font sudah sesuai/tidak missing font.</div><div>	d. Untuk produk yang memerlukan proses pond, cek kembali ketersediaan pisau di Bagian Finishing. Jika pisau belum ada maka buat pisau pond yg baru.</div><div>	4. Setting layout</div><div>	a. Untuk menentukan layout setting, pelajari gambar di bawah ini:</div><div>	<img alt=\"\" src=\"/project/pb/gambar/images/Untitled-2.jpg\"></div><div>	a. Film   </div><div>	        Harus mengacu ke rumus baku setting :  </div><div>	        - Jumlah minimal desain layout dlm 1 film = jumlah order / 2000  </div><div>	        - Ukuran layout film tidak boleh kurang dari ukuran minimal cetak.  </div><div>	        - Ukuran layout film tidak boleh lebih dari ukuran maksimal cetak.  </div><div>	        Pastikan untuk mendapatkan layout film yang optimal untuk penghematan film dan kertas.</div><div>	b. Print   </div><div>	        - Layout print menggunakan ukuran A3 (maks 31,5 x 47 cm), kecuali spanduk, x-banner dan yang sejenisnya disesuaikan dengan ukuran yang diminta konsumen .  </div><div>	        - Atur penataan file yang akan di-print sampai mendapatkan layout print yang optimal.   </div><div>	        - Untuk kartu nama , id card dan  pin layout disesuaikan dengan format yang sudah baku.    </div><div>	      (lihat di file project/setting/format/kartu nama,id card, pin).</div><div>	5. Setting layout harus mengacu pada aturan-aturan setting dari tiap jenis produk.   </div><div>	    File bisa dicek aplikasi tafio project/sop/setting/pilih jenis produk yang akan disetting.</div><div>	6. Dummy</div><div>	a. Dummy adalah contoh desain jadi yang menjadi acuan untuk proses cetak produksi.</div><div>	b. Dummy ada beberapa macam:</div><div>	         i. Dummy warna, desain jadi full colour.</div><div>	         ii. Dummy BW (black white), fit to A4, untuk mengetahui kepastian set lay out.</div><div>	         iii. Dummy BW (black white) ukuran sebenarnya, untuk mengetahui kelayakan teks / gambar.</div><div>	7. Jadikan file CDR menjadi format curve.</div><div>	    Hal ini untuk menghindari missing font (font hilang) ketika akan di cetak.</div><div>	8. Save as file ke folder Post Set (Setting Final), kemudian copy file ke folder project-setting-hari ini</div><ol></ol>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(72, 'JO Setting & Checklist Setting', '<p>	<img alt=\"\" src=\"/project/pb/gambar/images/JO%20%26%20Checklist.jpg\"></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/JO%20Buku%20%26%20Checklist.jpg\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(73, 'KOP SURAT', '<p>	1. Pastikan ukuran KOP surat. A4 atau Folio.</p><p>	2. Cek jumlah warna, full colour / 1, 2, 3 warna.</p><p>	3. Jarak konten (khususnya teks &amp; logo) dengan pisau potong minimal 3 mm.</p><p>	4. Buat satu desain, lalu tata biasanya 2 mata.</p><p>	5. Buat cross potong. Buat cross warna untuk yg full colour, cross potong 2 warna utk yg 2 warna.</p><p>	6. Print dummy ukuran sebenarnya, cek kelayakan teks dan gambar. Print juga dummy cetakan.</p><p>	7. Jika OK, jadikan curve. </p><p>	8. Cek separation.</p><p>	9. Save as kop surat (file CRD) ke folder Post Set.</p><p>	10. Selesai.</p><p>	 </p><p>	Poin-poin penting:</p><p>	 </p><h3>	 - Bahan KOP surat telah distandarkan menggunakan bahan Double Folio merk BOLA DUNIA</h3><p>	- Kop surat 3 warna &amp; full colour selalu cetak di JKT, kop surat 2 warna &amp; 1 warna, cetrak di bandung</p><p>	- Ukuran bahan biasanya pake HVS A3 43x30, atau Double Folio 43x33 cm. Jadi settingan disesuaikan dengan bahan tersebut.</p><p>	- Bahan plano dipake bila order minimal 8 rim kop surat.</p><p>	<strong>- kop surat full color &amp; 3 warna memakai komposisi CMYK. </strong></p><p>	<strong>- Kop surat 2 warna, settingnya memakai komposisi 2 warna, misalnya C &amp; K. Begitu juga dgn 1 warna. Cetaknya menggunakan campuran warna khusus.</strong></p><p>	<strong>- warna khusus adalah warna campuran yg di buat secara manual (campuran dari warna-warna C, M, Y atau K) oleh operator cetak.</strong></p><p>	<strong>- Di JKT menggunakan mesin SM 52, di BDG menggunakan mesin GTO 52. </strong></p><p>	 </p><p>	 </p><p>	 (updated 1 Okt 2014)</p><p>	 </p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/kop%20surat%20Q%20Green%20442x303%20mm%2C%201%20muka.png\"></p><p>	 </p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(74, 'MAP', '<p>	1. Pastikan ukuran map (untuk isi A4, F4, atau custom). Cek di project.</p><p>	2. Cek pisau map &amp; kuping map yg ada di sanggar. Jika belum ada maka buatkan pisau baru.</p><p>	3. Lebarin (bleeding) background tiap sisi, minimal 3 mm. Jarak konten (khususnya konten teks &amp; logo) dengan pisau potong, minimal 5 mm.</p><p>	4. Cek area cetak harus sama dengan JO setting.</p><p>	5. Cek warna, full colour / 1, 2, 3 warna.</p><p>	6. Buat cross warna, sesuaikan dengan wana full colour, 3 warna - 1 warna.</p><p>	8. Cantumkan keterangan <u>nomor pisau map</u> &amp; <u>nomor </u><u>pisau kuping map</u> yg digunakan &amp; keterangan <u>arah tarikan</u>.</p><p>	9. print dummy untuk cetak.</p><p>	10. Print ukuran sebenarnya, cek kelayakan teks, image, dll.</p><p>	11. Jika OK, buat curve.  </p><p>	12. Lakukan Checklist </p><p>	13. Save as hasil settingan map di folder Post Set.</p><p>	14. Selesai.</p><p>	 </p><p>	Poin-poin penting:</p><p>	- Map standar ada 2 macam ukuran:</p><p>	- ukuran map untuk isi A4 (450x310 mm), pisau yg dipake M5.</p><p>	- ukuran map untuk isi folio (480x338 mm), pisau yg dipake M8.</p><p>	- Bahan map menggunakan ukuran <strong>108x79</strong> cm. potong jadi 4 ukuran potong 52x36 cm (utk mesin SM 52), ukuran potong 50x36 cm (utk mesin GTO 52)</p><p>	- BIla jumlah orderan kecil maka cetak indigo, area cetak disesuaikan menjadi 450x310 mm.</p><p>	- Map 3 warna / full colour cetak di JKT (SM52), map 2 warna/1 warna cetak di BDG (GTO52)</p><p>	- Karena ukuran map lebih dari seukuran A3, maka layout map hanya 1 mata.</p><p>	 </p><p>	 (updated 1 Okt 2014)</p><p>	 </p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/map%20aquasains%20x5%2C%20500x355%20mm%2C%201%20muka.png\"></p><p>	 </p><p>	 </p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(75, 'NAME TAG', '<p>	1. Pastikan ukuran Name tag. Standarnya adalah 98x140 mm.</p><p>	    Pastikan ukuran sampul plastik Name tag. Ukuran Name tag menyesuaikan dengan sampul plastik yg telah ada.</p><p>	2. Lebarin (bleeding) background tiap sisi 3 mm.</p><p>	3. Jarak konten (teks &amp; logo) dengan potongan minimal = 5 mm. </p><p>	4. Jika bolak balik, sesuaikan dengan format. Misalnya jadi format BBS.</p><p>	5. Buat satu mata desain, </p><p>	6. Buat &amp; cek pisau potong, lalu ditata jadi 8 mata.</p><p>	7. Sesuaikan area cetak dengan JO setting. 426x292 mm</p><p>	8. Jika OK, jadikan curve.</p><p>	9. Print dummy ukuran sebenarnya, cek kelayakan teks &amp; gambar.</p><p>	10. Print dummy utk cetak.</p><p>	11. Save as settingan nametag di folder post set.</p><p>	12. Selesai.</p><p>	 </p><p>	Poin-poin penting:</p><p>	- Ukuran name tag A6 tepatnya = 98x140 mm. Hal ini menyesuaikan dengan plastik wadah nametag.</p><p>	- Jumlah Order nametag cenderung sedikit (&lt;200 pcs), maka dari itu sering cetaknya pake indigo.</p><p>	- jika desain nametag seragam (misalnya 1 macam), dan namanya banyak, maka setting dengan cara <u>Data Merge di Indesign.</u></p><p>	 </p><p>	 </p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/nametag%20summer%20program%2C%20416x292mm.png\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(76, 'PAPER BAG', '<p>	1. Pastikan ukuran paper bag (Front, back, left right). Cek pisau yang ada, cek bila ada pisau yg cocok. cek pisau ada disini : server/setting/pisau</p><p>	2. Lipatan dalam = 4 cm. Area ini (2) merupakan perpanjangan gambar pada area 1. </p><p>	3. Lipatan bawah = 1/2a+2 cm. a = samping kanan/kiri </p><p>	4. Area lem samping 1cm. Area lem bawah 4cm.</p><p>	5. Lebihan (bleeding) 3mm untuk. Area ini (5) merupakan perpanjangan gambar pada area 1. </p><p>	6. Pastikan warna paperbag, full colour / 1, 2, 3 warna. </p><p>	7. Buat cross rel. </p><p>	8. Buat pisau. Pisau harus sudah di-mirror.</p><p>	9. Buat cross sudut. buat colour bar (cross warna) utk yg FC.</p><p>	10. Jadikan curve.</p><p>	11.  Save as settingan paperbag Post Set.</p><p>	12. Tulis ukuran area cetak pada nama file. Contoh <strong>paperbag_final420x290mm.cdr</strong></p><div>	13. Selesai.  </div><p>	 </p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/paperbag%20K%20Lathif%20pisau%2C%202%20set%2C%20480x355%20mm.jpg\"></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/paperbag%20K%20Lathif1%2C%202%20set%2C%20480x355%20mm.jpg\"></p><p>	 </p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(77, 'NOTA FOLIO ( MESIN TOKO )', '<p>	1. Tentukan ukuran cetak :</p><p>	<strong>    1/4 Folio (165mm x 105mm), </strong></p><p>	<strong>    1/3 Folio (108mm x 210mm), </strong></p><p>	<strong>    1/2 Folio (162mm x 210mm).</strong></p><p>	2. Tentukan warna cetak : Pastikan 1, 2, atau &gt;2 warna. </p><p>	    Pisahkan warna menjadi C/M/Y/K saja.</p><p>	3. Ukuran - ukuran yg diperlukan :</p><p>	    Area cetak : maksimal <strong>315x210mm</strong>, </p><p>	    Konten desain dari tepi kertas : minimal 7mm (Tarikan minimal mesin toko)</p><p>	    konten dgn garis potong : minimal 5mm</p><p>	5. Tentukan sisi blok lem &amp; porporasi : kiri / atas / kanan</p><p>	    Jarak konten desain dari sisi blok lem : minimal 13mm - 15mm.</p><p>	6. Warna background : minimal <strong>7% - 20%</strong> C/M/Y/K</p><p>	7. Buat cross potong dan cross sudut.</p><p>	8. Print dummy di kertas <strong>A4</strong> (<em>fit to page</em>).</p><p>	9. Jika OK, save as ke folder post set. </p><p>	10. Pastikan semua teks telah diperiksa dan di <em><strong>curve </strong></em>agar tidak terjadi <em>missing font</em>.</p><p>	11. Tulis nama file sesuai project. Contoh : nota (jenis nota) (nama pemesan).cdr</p><p>	12. Selesai  </p><p>	 </p><p>	<strong>NOTA 1/4 FOLIO</strong></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/Nota%201%20per%204.jpg\"></p><p>	 </p><p>	<strong>NOTA 1/3 FOLIO</strong></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/Nota%201%20per%203.jpg\"></p><p>	 </p><p>	<strong>NOTA 1/2 FOLIO</strong></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/Nota%201%20per%202.jpg\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(78, 'NOTES', '<p>	COVER</p><p>	1. Tentukan ukuran cover note </p><p>	2. Tentukan jarak ring (atas / kiri) /lipatan cover. </p><p>	     Misalnya 8 mm untuk ring, 25 mm untuk lipatan cover (tergantung ketebalan isi notes). </p><p>	3. Tentukan jarak konten teks dengan pisau, minimal 7 mm.  </p><p>	4. tetukan tebal punggung utk yg blok lem. tebal punggung harus diukur sesuai tebal isi.</p><p>	4. Buat repeat, sesuaikan dengan kertas set. </p><p>	5. Buat cross potong. </p><p>	6. Buat cross sudut. Jika full colour masukkan cross warna. </p><p>	7. Print dummy BW </p><p>	8. Jika OK buat curve, save as di folder post set.</p><p>	9. selesai  </p><p>	 </p><p>	ISI NOTES</p><p>	 </p><p>	Ketentuan umum: </p><p>	- cetak isi notes hampir selalu di cetak di BDG. kecuali isi notes yg FC cetak di JKT</p><p>	- bahan yg digunakan hampir selalu HVS A3 (43x30 cm) atau HVS Double Folio (43x33), tergantung desain cetakan.</p><p>	- bahan plano biasanya digunakan bila jumlah cetakan setidaknya 8000 lembar A5, jika 1 buku isi 50 lembar makan jadinya 160 pcs notes. </p><p>	- Atau dengan kata lain, minimal order notes 160 pcs ukuran A5.</p><p>	- bahan HVS tidak bisa dibeli secara eceran, tapi hanya bisa dibeli per rim.</p><p>	 </p><p>	1. Tentukan ukuran isi  notes (A5/A6, dll)</p><p>	2. Jika menggunakan ring, samakan jarak ring dengan konten desain cover, misalnya 8 mm. </p><p>	3. Tentukan jarak konten teks dengan pisau, minimal 7 mm.  </p><p>	4. Buat repeat, sesuaikan dengan kertas set. </p><p>	5. Buat cross potong dan atau cross sudut seperlunya.</p><p>	6. Print dummy BW / FC.</p><p>	7. Jika OK buat curve, save as di folder post set. </p><p>	8. Tulis ukuran area cetak pada nama file, untuk cetakan di JKT. Contoh : isi_notes, 300x430 mm.cdr</p><div>	    Tulis spek buat CTP, utk cetakan di BDG, Contoh: isi_notes, bikin CTP 1 war</div><p>	9. selesai  </p><p>	 </p><p>	Catt:</p><p>	1. Blok lem selalu berada di sisi (atas, bawah atau kanan, kiri)</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/isi%20notes(1).jpg\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27');
INSERT IGNORE INTO `data_sops` (`id`, `judul`, `isi`, `sop_bagian_id`, `global`, `created_at`, `updated_at`) VALUES
(79, 'BROSUR / POSTER', '<p>	1. Pastikan ukuran brosur. </p><p>	2. Jarak konten teks/logo dengan potongan jadi, minimal = 5mm. </p><p>	3. Tambahkan luas background di tiap sisi, minimal = 3 mm. </p><p>	4. Buat cross potong.</p><p>	5. Buat cross sudut.</p><p>	6. Buat satu desain, lalu repeat/copy desain sesuai banyaknya order.  </p><p>	7. Setting BBS/BBB (jika bolak balik). atau 1 muka</p><p>	8. Buat cross warna di luar konten (jika full colour).</p><p>	9. Save as di folder Post Set. </p><p>	10. Print ukuran sebenarnya, cek kelayakan teks dan gambar. </p><p>	11. Print dummy BW (black white) atau FC (full colour), fit to A4. </p><p>	12. Jika OK, jadikan curve. Atau copy font.</p><p>	13. Tulis area cetak pada nama file. Contoh <strong>poster, 420x290 mm.cdr</strong>   </p><p>	14. Selesai  </p><p>	 </p><p>	Catatan: </p><p>	poster / brosur, untuk mempercepat poses setting, tidak selamanya area cetak harus diperlebar +3 mm tiap sisi.</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/brosur-4.jpg\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(80, 'BUKU / MAJALAH', '<p>	<strong><img alt=\"\"><img alt=\"\">Isi Buku</strong></p><p>	 </p><p>	1. Pastikan ukuran buku. </p><p>	2. Pastikan jumlah halaman buku. </p><p>	3. Pastikan urutan halaman. Sesuaikan dengan Daftar Isi. </p><p>	4. Pastikan isi buku, full colour / BW. Lalu sesuaikan. </p><p>	5. Tambahkan kelebihan background, <strong>khusus buku minimal 5 mm</strong> pada tiap sisi.  </p><p>	6. Tentukan lay out cetak. </p><p>	7. Jadikan PDF, sesuai dengan urutan halaman. </p><p>	8. Setting menggunakan In Design. </p><p>	9. Save as buku_set.indd ke folder Post Set. </p><p>	10. Print ukuran sebenarnya, cek kelayakan teks dan gambar. </p><p>	11. Print dummy BW (black white), fit to A4. </p><p>	12. Cek urutan halaman setelah set layout. </p><p>	13. Tulis ukuran film pada sudut kanan atas dummy. Misalnya ukuran film post set menjadi 305 x 430 mm.</p><p>	     Tulis juga ukuran film pada nama file. Contoh <strong>buku_film420x290mm.cdr</strong> </p><p>	14. Selesai.  </p><p>	 </p><p>	Aturan baku setting buku/majalah</p><p>	1. Halaman ganjil selalu ada di sebelah kanan.</p><p>	2. Halaman genap selalu ada di sebelah kiri.</p><p>	 </p><p>	Catatan:</p><p>	-  jika ada image (file.cdr), untuk mempertajam contrast bisa menggunakan <strong>auto adjust</strong>, di menu <strong>bitmaps</strong></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(81, 'LJK', '<div>\r\n	<p>\r\n		1. Pastikan ukuran LJK.</p>\r\n	<p>\r\n		2. Unlock all object.<br>\r\n		3. Jarak konten cetak dengan pisau potong minimal 5 mm.<br>\r\n		4. Outline minimal 0,4 point. (<em>hairline</em> = 0,0762 mm = 0,216 pt). 0,4 point = 0,141 mm<br>\r\n		5. Ubah warna konten menjadi CMYK. (misalnya mjd 1 warna dasar C = 100%)<br>\r\n		6. Pastikan turunan warna konten (shading) 20%. Misalnya konten C = 100%, maka shading C = 20%) <br>\r\n		7. Cek konten hitam, pastkan menjadi CMYK (K= 100%)<br>\r\n		8. Ubah bitmap logo menjadi <em>duotone</em>, sesuaikan dengan warna konten.<br>\r\n		9. Buat cross 2 warna, misalnya C = 100%, dan K = 100%.<br>\r\n		10. Cek separasi warna, melalui <em>preview</em>.<br>\r\n		11. Jika sudah OK, set repeat sesuai dengan banyaknya order.<br>\r\n		12. Buat cross potong.<br>\r\n		13. membuat cross sudut, sesuaikan dengan potongan jadi (A4, B5, dll)<br>\r\n		14.<em> </em>Cek trace/settingan dengan cara : <strong>timpa file settingan dengan file jpeg/pdf aslinya</strong>. Pastikan hasil trace presisi/sesuai posisinya.</p>\r\n	<p>\r\n		15<em>. Save as</em> menjadi<strong> ljk_set.cdr</strong> ke folder <strong>Post Set</strong>.<br>\r\n		16.<em> Print dummy</em> ukuran sebenarnya, cek kelayakan teks &amp; gambar.<br>\r\n		17.<em> Print dummy</em> BW (black white), <em>fit to A4</em>.<br>\r\n		18. Jika OK, Jadikan <em>curve</em>.<br>\r\n		19. Tulis ukuran film pada nama file. Contoh<strong> ljk_film420x290mm.cdr</strong></p>\r\n	<div>\r\n		      Juga Tulis ukuran film pada dummy. Contoh ukuran film 420x290mm.</div>\r\n	<p>\r\n		20. Bandingkan dummy_set dengan file asal.</p>\r\n	<p>\r\n		21. Selesai.  </p>\r\n	<p>\r\n		 </p>\r\n	<p>\r\n		<strong>Jika Order ukuran B5 (18,2x25,7 cm), maka bahan harus menggunakan HVS plano 108 x 79 cm (jadi 16 bagian).</strong></p>\r\n	<p>\r\n		<strong>1 plano jadi 8, 1 area cetak jadi 2.</strong></p>\r\n	<p>\r\n		<img alt=\"\" src=\"/project/pb/gambar/images/aplikom%20cetak%20film.jpg\"></p>\r\n	<p>\r\n		 </p>\r\n	<p>\r\n		 </p>\r\n</div>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(82, 'Administrasi', '<div>\r\n	<table><tbody><tr><td><ol><li>\r\n							Login <a href=\"mailto:tafioproject\">tafioproject</a> , e-mail <u>admin@percetakanbandung.com</u> setiap awal jam kerja dan logout diakhir jam kerja.</li><li>\r\n							Memenuhi kebutuhan surat menyurat / administrasi kantor.</li><li>\r\n							Cek absensi karyawan perminggu dan buat rekap absensi perbulan</li><li>\r\n							Buat rekap tunjangan kehadiran karyawan berdasarkan absensi yang ada </li><li>\r\n							Cek dan input lembur karyawan ke project (sdm-aktif-lihat nama sdm-pilih lembur-input)</li><li>\r\n							Simpan nota pengiriman barang untuk setiap barang pesanan yang sudah dikirim.</li><li>\r\n							Periksa dan rapihkan seluruh data administrasi secara berkala. </li><li>\r\n							Print out lembaran form kerja bila stok di rak penyimpanan form mulai habis.</li><li>\r\n							Buat dan print invoice order </li><li>\r\n							10  Memperbaharui data rekanan, harga kertas, pengiriman, nomor penting di <a href=\"mailto:tafioproject\">project</a> sesuai perkembangan dan keperluan.</li><li>\r\n							Buat catatan singkat apapun untuk setiap instruksi/pesan agar terhindar dari lupa.</li></ol></td></tr><tr><td>\r\n					 </td></tr></tbody></table>\r\n</div>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'administrasi' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(83, 'Jadwal', '<div>\r\n	\r\n					<ol><li>\r\n							Senin s.d. kamis pagi jam kerja diawali tahsin/tilawah al Qur’an jam 08.00 WIB dilanjutkan rapat project dan pengumuman2</li><li>\r\n							Setiap hari jumat diadakan jumat bersih di kantor dan lingkunga sekitar kantor, siapkan konsumsi (budget 40rb)</li><li>\r\n							Setiap hari Selasa jam 16.00 s.d. 17.00 WIB futsal rutin karyawan ikhwan.</li><li>\r\n							Rabu jam 16.30 WIB mengisi form belanja stok mingguan, untuk keperluan kantor </li><li>\r\n							Sabtu pekan pertama setiap bulan jam 13.00 pengajian rutin gabungan bulanan.</li><li>\r\n							Meminta bagian umum untuk cek harwat (pemeliharaan dan perawatan) kendaraan ops. sesuai kondisi masing<sup>2</sup> kendaraan.</li><li>\r\n							 Tanggal 1-3 setiap bulan bayar iuran keamanan RT 01/07 Kembar Timur.</li><li>\r\n							Cek berkala kebutuhan alat tulis kantor, bila barang mulai habis lakukan pemesanan ke bagian purchasing.</li><li>\r\n							Bayar PPh 21/26 sebelum tgl 10 dan bayar Final sebelum tgl 15 serta lapor paling lambat sebelum tanggal 20. Lapor PPN paling lambat sebelum tanggal 28.</li></ol>\r\n				\r\n</div>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'administrasi' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(84, 'Teller Keuangan', '<div>\r\n	<p>\r\n		1.     uang kas</p>\r\n	<p>\r\n		-       pastikan uang kas tersedia (jika habis koordinasi dengan manajer)</p>\r\n	<p>\r\n		-       pastikan uang kas yang ada sama dengan yang tertera di project  (cek di akhir hari sebelum pulang kerja)</p>\r\n	<p>\r\n		-       disimpan ditempat yang aman</p>\r\n	<p>\r\n		2.    uang belanja</p>\r\n	<p>\r\n		-       Memberikan uang belanja produksi/operasional</p>\r\n	<p>\r\n		-       Melakukan pembayaran hal-hal yg berhubungan dengan opersional kantor</p>\r\n	<p>\r\n		-       input di laporan kas harian (excel)</p>\r\n	<p>\r\n		-       yang meminta uang belanja harus menyertakan rincian keperluan belanjanya</p>\r\n	<p>\r\n		-       uang belanja tidak diberikan jika belum memberikan laporan belanja hari sebelumnya</p>\r\n	<p>\r\n		3.    laporan belanja</p>\r\n	<p>\r\n		-        Cek-kroscek setiap laporan belanja per orang beserta bon-bon transaksi pembeliannya.</p>\r\n	<p>\r\n		-       pemasukan dan pengeluaran harian diinputkan terlebih dahulu ke laporan harian excel</p>\r\n	<p>\r\n		-       input laporan keuangan ke tiap kas yg ada di project pada esok hari</p>\r\n	<p>\r\n		a.    kas jakarta</p>\r\n	<p>\r\n		b.    kas bandung</p>\r\n	<p>\r\n		c.    kas sanggar</p>\r\n	<p>\r\n		d.    kas pusat</p>\r\n	<p>\r\n		e.    kas pengiriman</p>\r\n	<p>\r\n		cat : pastikan input laporan dilakukan diawal hari (smp sebelum waktu istirahat)</p>\r\n	<p>\r\n		-       Simpan bon-bon transaksi pembelian dan dipisahkan perbulannya.</p>\r\n	<p>\r\n		-       Pastikan semua saldo akhir tiap kas di project sesuai dengan laporan masing-masing kas</p>\r\n	<p>\r\n		4.    pembayaran tagihan</p>\r\n	<p>\r\n		-       terima uang cash pembayaran order (pastikan jumlah uang yang diterima sesuai)</p>\r\n	<p>\r\n		-       Cek pembayaran yang masuk via rek bank (pengecekaan dilakukan awal hari, setelah jam istirahat dan ba’da ashar). kemudian input di wa grup keuangan untuk mendapatkan konfirmasi dari marketing pembayaran dari konsumen yang mana</p>\r\n	<p>\r\n		a.    jika data pembayaran yang masuk sudah jelas (nama konsumen dan nilai pembayaran sama) bisa langsung di input pembayarannya</p>\r\n	<p>\r\n		b.    cek history pembayaran untuk membantu mengindentifikasi  konsumennya</p>\r\n	<p>\r\n		c.    cari persamaan jumlah pembayarannya (jumlah sama, dp 50%, lebih dari 1 invoice)</p>\r\n	<p>\r\n		-       input pembayaran yang masuk ke project input data  pembayaran tunai dan  pembayaran melalui rek (setelah ada konfirmasi bahwa dana sudah masuk ke rekening)</p>\r\n	<p>\r\n		-       pastikan input data yang sesuai (konsumen, nilai pembayaran, tgl pembayaran,keterangan pembayaran, dll)</p>\r\n	<p>\r\n		-       pastikan agar sampai akhir jam kerja semua data pembayaran yang masuk sudah terkonfirmasi dan sudah diinput</p>\r\n	<p>\r\n		-       jika sampai akhir hari tidak ada konfirmasi tentang kepemilikan dana yang masuk maka ditunggu sampai esok hari. klo tetep tidak terkonfirmasi maka input dana yang masuk tersebut ke eksternal skudetto (konfirmasi ke pj skudetto)</p>\r\n	<p>\r\n		5.    gaji karyawan</p>\r\n	<p>\r\n		-       Membayarkan gaji sesuai dengan tanggal gajian masing-masing karyawan</p>\r\n	<p>\r\n		-       pembayaran gaji melalui transfer ke rekening karyawan yang bersangkutan atau pakai uang cash (jika karyawan belum memiliki rekening)</p>\r\n	<p>\r\n		-       jika tanggal gajian jatuh pada hari minggu/libur maka gajian bisa dimajukan pembayarannya (koordinasi dl dengan manajer)</p>\r\n	<p>\r\n		-       pastikan semua karyawan memiliki rekening untuk keperluan penggajian (bank harus sama dengan bank yang dimiliki perusahaan)</p>\r\n	<p>\r\n		-       input gaji yang sudah dibayarkan ke project</p>\r\n	<p>\r\n		-       cek lembur dan tunjangan kehadiran karyawan</p>\r\n	<p>\r\n		-       jika catatan lembur karyawan baru diberikan pas hari gajian maka ongkos lembur dibayarkan di penggajian bulan berikutnya</p>\r\n	<p>\r\n		-       bila ada kasbon maka harus dipotong terlebih dahulu sesuai jadwal gajian per karyawan.</p>\r\n	<p>\r\n		6.    kasbon</p>\r\n	<p>\r\n		-       jika ada karyawan yang mengajukan kasbon maka koordinasikan dl dengan manajer</p>\r\n	<p>\r\n		-       cairkan kasbon sesuai dengan nilai yang disetujui oleh manajer</p>\r\n	<p>\r\n		-       input kasbon ke form kasbon dan project</p>\r\n	<p>\r\n		-       kasbon akan memotong gaji perbulannya</p>\r\n	<p>\r\n		7.    Evaluasi tentang system pembayaran order (minimalisasi yg tidak terbayarkan)</p>\r\n	<p>\r\n		-       dp order untuk klien baru harus 50%</p>\r\n	<p>\r\n		-       semua barang yang sudah beres itu bisa dikirim jika sudah dilakukan peluanasan pembayaran / ada kejelasan pembayarannnya ( kecuali klien khusus-yg sistem bayarnya pake kontra bon, klien yg ada perjanjian khusus)</p>\r\n	<p>\r\n		-       order berikutnya tidak bisa langsung di proses sebelum ada kejelasan untuk pembayaran order sebelumnya ( bagian keuangan harus memastikan order yg bisa di proses tdk ada tunggakan pembayaran)</p>\r\n	<p>\r\n		-       untuk klien yang masih ada maks 3 tagihan / 3 bulan (mana dl yang terpenuhi) yg blm dibayarkan maka sebelum diproses order berikutnya harus lakukan pelunasan untuk order sebelumnya</p>\r\n	<p>\r\n		8.  Arsip Bank</p>\r\n	<p>\r\n		     - data2 transaksi di rekening perusahaan harus di buat arsip banknya </p>\r\n	<p>\r\n		     - arsip bank di buat perbulan transaksi</p>\r\n	<p>\r\n		     - cara perarsipan data rekening bank bisa dilihat di SOP arsip data bank tiap rekening</p>\r\n	<p>\r\n		     - pengarsipan dilakukan tiap awal bulan (tanggal 1) agar semua transaksi bisa terinput</p>\r\n	<p>\r\n		9. Mencairkan lembar cheque dan atau mengisi slip titipan kliring dari lembar giro sebagai pembayaran berjangka dengan norek bank perusahaan (memindahkan dana via giro dari rek. bank klien/konsumen ke rek. bank perusahaan) sesuai tanggal  jatuh temponya.</p>\r\n	<p>\r\n		10.  -  Memastikan balance untuk kas - kas eksternal (skudetto, idcard bandung, stationery bandung dan desain bandung)</p>\r\n	<p>\r\n		     -  Selalu koordinasi dengan PJ nya setiap akan input data ke kas - kas eksternal tersebut</p>\r\n	<p>\r\n		11. Menjaga kerahasiaan data – data keuangan</p>\r\n	<p>\r\n		 </p>\r\n	\r\n					 \r\n</div>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'keuangan' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(86, 'ALUR ORDER TAFIO', '<p><img src=\"https://mail.google.com/mail/?ui=2&amp;ik=9ac8c10190&amp;view=att&amp;th=1318e7ff55651083&amp;attid=0.1&amp;disp=inline&amp;realattid=f_gqvyo40t0&amp;zw\" alt=\"alur order\" width=\"600\" height=\"857\"></p>\r\n<p> </p>\r\n<p> </p>\r\n<p><strong>Penjelasan :</strong></p>\r\n<p> </p>\r\n<p>1. a. Order masuk dari konsumen langsung ke bagian order.</p>\r\n<p>    b. Order masuk dari konsumen via marketing lalu diteruskan ke bagian order.</p>\r\n<p>2. a. Bagian order meneruskan order tersebut ke bagian setting untuk dilakukan penyettingan sesuai dengan spec order dari konsumen.</p>\r\n<p>    b. Jika order dari konsumen perlu didesain dulu maka bagian order meneruskan ordernya ke bagian desain. </p>\r\n<p>        Jika desain sudah fix (sudah disetujui oleh konsumen) maka order diteruskan ke bagian setting.</p>\r\n<p>    c. Bagian order juga meneruskan order tersebut ke bagian keuangan untuk dibuatkan invoice ordernya.</p>\r\n<p>3. a. Hasil setting order diteruskan ke bagian produksi untuk diproses.</p>\r\n<p>    b. Bagian order dan produksi berkoordinasi untuk mengontrol proses produksi agar hasilnya sesuai dengan spec order dari konsumen.</p>\r\n<p>4.     Hasil cetakan dari bagian produksi diteruskan ke bagian finishing.</p>\r\n<p>5. a. Bagian produksi dan finishing melakukan proses QC terhadap hasil cetakan dan finishingnya </p>\r\n<p>       (hasil cetakan yang sesuai dengan spec order dari konsumen saja yang bisa dipacking untuk dikirim),  </p>\r\n<p>        packing sesuai dengan standar packing yang sudah ditentukan.</p>\r\n<p>    b. Cetakan yang sudah dipacking diteruskan ke bagian pengiriman.</p>\r\n<p>    c. Bagian order berkoordinasi dengan bagian pengiriman untuk memastikan waktu dan tujuan pengiriman serta metode pembayaran </p>\r\n<p>        order dari konsumen.</p>\r\n<p>6. a. Bagian pengiriman melakukan pengiriman barang sesuai dengan waktu dan tujuan pengiriman sesuai kesepakatan konsumen.</p>\r\n<p>    b. Bagian order konfirmasi ke konsumen untuk memastikan barang sudah terkirim dan konfirmasi pembayaran ordernya.</p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'order' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(87, 'AMPLOP', '<p>	 </p><p>	1. Pastikan ukuran amplop, lalu cek pisau yg ada di sanggar (jika pisau belum ada maka buat pisau dahulu). </p><p>	2. Jarak konten (teks/logo) dengan pisau potong, minimal 5 mm. </p><p>	3. Cek warna, full colour / 1, 2, 3 warna. </p><p>	4. Buat cross potong pond, cross sudut, colour bar.</p><p>	5. Cantumkan arah tarikan dan nomor pisau amplop.</p><p>	6. Print dummy warna A4 &amp; dummy ukuran sebenarnya.</p><p>	7. Jadikan curve semua font</p><p>	8. Lakukan checklist.</p><p>	9. Save as settingan Amplop di forlder Post Set. </p><p>	10. Selesai.</p><p>	 </p><p>	Contoh Amplop Besar, depan cetak, belakang tempel</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/amplop2.jpg\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(88, 'STIKER BALLPEN', '<p>	1. Pastikan jenis ball pen yang digunakan. </p><p>	2. Pastikan ukuran stiker, sesuaikan dengan jenis ball pen. </p><p>	3. Jarak pisau potong sisi kiri, kanan, bawah dengan konten teks/logo minimal 5 mm. </p><p>	4. Jarak pisau potong sisi atas dengan konten teks/logo minimal 12 mm. </p><p>	5. Perluas background, lalu Buat satu desain, lalu repeat sesuai dengan format setting. </p><p>	6. Buat cross potong. </p><p>	7. Print dummy ukuran sebenarnya, cek kelayakan teks &amp; gambar.</p><p>	8. Print dummy BW (black white), fit to A4. </p><p>	9. Jika OK, save as stiker_set.cdr ke folder Post Set. </p><p>	10. Produksi </p><p>	11. Selesai.</p><p>	 </p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/sticker%20ball%20pen(1).jpg\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(89, 'AGENDA KERJA 2', '<p>\r\n	 </p>\r\n<p>\r\n	1. Cek order yang harus di desain di aplikasi Tafio Project/order/desain.</p>\r\n<p>\r\n	2. Pelajari spec order (kreatif brief form.) dengan seksama, jika ada yang kurang jelas koordinasikan dengan order manager/marketing.</p>\r\n<p>\r\n	3. CeK file order, pastikan bahan desain sudah lengkap:</p>\r\n<p>\r\n	a. Body text (ms.word).</p>\r\n<p>\r\n	b. Logo (vector/jpeg resolusi tinggi, minimal 300 dpi).</p>\r\n<p>\r\n	c. Foto/Gambar (resolusi tinggi, minimal 300 dpi).</p>\r\n<p>\r\n	4. Beri jarak 1x1 cm (atau kelipatannya tergantung ukuran item/area) pada tepian area   yang akan di desain.</p>\r\n<p>\r\n	5. Save kerjaan desain setiap 5 Menit sekali.</p>\r\n<p>\r\n	6. Lama waktu pengerjaan koordinasikan dengan order manager.</p>\r\n<p>\r\n	7. Lihat kembali hasil desain yang sudah jadi (cek keseimbangan layout, harmonisasi warna, foto, text, logo, dll.).</p>\r\n<p>\r\n	8. Save as desain yang sudah jadi ke format jpeg/pdf</p>\r\n<p>\r\n	9. Convert desain yang sudah ber-format jpeg menggunakan adobe photoshop untuk di email (dengan cara mengecilkan resolusi antara 72-150 dpi, tergantung jenis media desain, kemudian save for web &amp; devices)</p>\r\n<p>\r\n	10. Simpan hasil desain yang sudah di convert di folder \"siap kirim\" kemudian konfirmasi ke order manager untuk acc.</p>\r\n<p>\r\n	11. Jika ada revisi tanya detail revisi ke order manager, kemudian ulangi poin 9 &amp; 10.</p>\r\n<p>\r\n	12. Jika desain sudah final buat folder final, kemudian save as desain dengan menambah kata \"final\" di belakang nama file desain di folder finaltersebut, copy font yang digunakan, kemudian print dummy untuk:</p>\r\n<p>\r\n	a. Pastikan body text benar dan pada tempatnya (tidak loncat/bergeser), cek setiap ejaan kalimat/kata (pastikan tidak salah ejaan ataukurang huruf)</p>\r\n<p>\r\n	b. Cek ukuran font (tidak terlalu kecil &amp; tidak terlalu besar)</p>\r\n<p>\r\n	c. Cek foto/gambar (pastikan tidak pecah)</p>\r\n<p>\r\n	Cek elemen-elemen desain lainnya.</p>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'desain' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(90, 'Syarat PO bisa diproses', '<p>\r\n	1. Untuk konsumen baru pastikan untuk membayar uang DP sesuai dengan ketentuan :</p>\r\n<p>\r\n	      1. DP 50% Harus ditawarkan diawal (mutlak bagi calon konsumen perusahaan tapi ordernya via marketing luar)</p>\r\n<p>\r\n	      2. DP &lt; 50%, bisa jika :</p>\r\n<p>\r\n	         -   Data calon konsumen lengkap</p>\r\n<p>\r\n	         -   Calon konsumen datang langsung ke kantor tafio</p>\r\n<p>\r\n	         -   Order langsung dari konsumen asli (bukan marketing luar/untuk dijual lagi</p>\r\n<p>\r\n	      3. Tidak pakai DP, bisa jika:</p>\r\n<p>\r\n	         -   Calon konsumen dari perusahaan/instansi (pastikan Data calon konsumen lengkap )</p>\r\n<p>\r\n	         -   Kredibilitas perusahaan/instansi baik</p>\r\n<p>\r\n	         -   Order harus dilengkapi dengan PO langsung dari perusahaan/instansi tersebut</p>\r\n<p>\r\n	     --- Pastikan DP sudah masuk sebelum order di proses</p>\r\n<p>\r\n	2. Spesifikasi order harus sudah jelas dan file desain dari konsumen harus sudah layak produksi (cek ukuran desain,resolusi,font,dll-bisa koordinasi dengan bagian  setting)</p>\r\n<p>\r\n	3. Permintaan waktu produksi dari konsumen harus memungkinkan, jika terlalu mepet koordinasi dengan bagian produksi untuk memastikan bisa diproses/tidak</p>\r\n<p>\r\n	4. Produk yang akan dibuat sudah pernah buat sebelumnya/tidak, jika belum lakukan dulu studi produk untuk memastikan kelayakannya (kualitas, kekuatan) dan juga     </p>\r\n<p>\r\n	    kemudahan dalam proses produksinya nanti</p>\r\n<p>\r\n	5. Catat semua detil order ke aplikasi tafio-project</p>\r\n<p>\r\n	6. Pastikan jenis pengiriman barang yang diinginkan konsumen :</p>\r\n<p>\r\n	    -  diambil</p>\r\n<p>\r\n	    -  diantar (untuk area bandung saja dengan order min rp.100.000,- (kecuali konsumen lama),  jika dibawah itu ada tambahan ongkos kirim rp.15.000,-)</p>\r\n<p>\r\n	    -  paket (ongkos kirim dibebankan kepada konsumen)</p>\r\n<p>\r\n	7. Pastikan jenis pembayaran yang diinginkan</p>\r\n<p>\r\n	    -  COD (Cash On Delivery)</p>\r\n<p>\r\n	    -  transfer (untuk konsumen baru yang luar kota, sisa pembayaran dilakukan sebelum barang dikirim)</p>\r\n<p>\r\n	    -  kontra bon</p>\r\n<p>\r\n	8. Pastikan bentuk invoice yang diinginkan</p>\r\n<p>\r\n	    -  print</p>\r\n<p>\r\n	    - email</p>\r\n<p>\r\n	    - tanpa invoice</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'order' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(91, 'NUMERATOR VOUCHER / SERTIFIKAT INDESIGN', '<p>\r\n	1. Buat daftar nama (utk sertifikat) /urutan angka (untuk numerator) di excel.</p>\r\n<p>\r\n	2. Beri judul kolom diatasnya, misalnya \"Nomor\" (untuk numerator), \"nama\" (untuk setifikat)</p>\r\n<p>\r\n	3. Save dgn nama file, NamaFile.csv (extension *.csv (tab delimited)). lalu wajib close file .csv!!</p>\r\n<p>\r\n	5. Buat satu file master, misalnya desain voucher.pdf. Ketik \"Nomor\" pada bagian penomoran. </p>\r\n<p>\r\n	Atau desain_sertifikat.pdf, lalu buat kolom \"nama\" untuk memasukkan nama.</p>\r\n<p>\r\n	Jika dalam satu halaman ada lebih dari 1 desain repeat, maka master tetap di buat 1 saja. </p>\r\n<p>\r\n	6. Klik Windows - Automation - Data Merge. Lalu akan muncul dialogue box Data Merge.</p>\r\n<p>\r\n	7. Klik select data source, dan cari data excel <strong>NamaFile.txt.</strong></p>\r\n<p>\r\n	8. Klik teks \"nomor\" atau \"nama\" yg ada di layout master indesign, lalu klik juga judul \"Nomor\" atau \"nama\" pada dialog box Data Merge.</p>\r\n<p>\r\n	9. Klik icon segitiga terbalik di pojok kanan atas pada dialogue box Data Merge, lalu pilih Create Merge Document.</p>\r\n<p>\r\n	10. Muncul  dialogue box Create Merged Document.</p>\r\n<p>\r\n	11. Pada menu Records</p>\r\n<p>\r\n	       Ceklist pada: Range: 1-100</p>\r\n<p>\r\n	       Pilih: Multiple Records</p>\r\n<p>\r\n	     Jika setelah mltiple record ada error (tanda merah), maka cek margin, margin harus NOL</p>\r\n<p>\r\n	12. Pada Menu Multiple Record Layout</p>\r\n<p>\r\n	       Pilih Multiple record, lalu OK.  </p>\r\n<p>\r\n	Link :</p>\r\n<p>\r\n	http://gcostudios.com/how-to-data-merge-in-indesign-cs6-tutorial/</p>\r\n<p>\r\n	http://zulbmohd.blogspot.com/2012/11/print-merge-menggunakan-coreldraw.html</p>\r\n<p>\r\n	http://creativepro.com/indesign-how-designing-data/</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
