(98, 'KARTU NAMA (indigo)', '<p>	1. Pastikan jumlah order Name Card.<br>	2. Tentukan format lay out name card (potong kotak/potong rounded).<br>	3. Cek ukuran jadi name card. Misalnya 90x50 mm.<br>	4. Lebarkan background, misalnya menjadi 93x58 mm. Setting name card di program CorelDraw.</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/bleed%20kartu%20nama.jpg\"></p><p>	<br>	5. Pastikan jarak konten (khususnya teks &amp; logo) dengan pisau minimal 5mm.<br>	6. Buat satu desain Name Card yg sudah dilebarin (93x58 mm), dan canvas corel tetap ukuran 90x55 mm. <br>	7. Repeat desain dgn cara: Ctrl + P ---&gt; (sesuaikan dialogue box spt berikut):</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/preferance%20kartu%20nama.jpg\"></p><p>	<br>	8. Lalu Klik \"Print Preview\", dan akan muncul spt ini:</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/duplikasi%20kartu%20nama.jpg\"></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/preview%20kartu%20nama(1).jpg\"></p><p>	 </p><p>	9. Jika sudah seperti tampilan di atas (21 mata), klik toolbar \"print\", sampai selesai muncul file PDF nya.<br>	10. Print dummy ukuran sebenarnya, cek kelayakan teks dan gambar.<br>	11. Print dummy fit to A4.<br>	12. Selesai</p><p>	Tampilan Settingan Kartu nama yg sudah jadi (PDF)</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/kartu%20nama%20Fani%20Jayanti%20%26%20Melissa%20Juwono.jpg\"></p><p>	Potong bulat  86 x 54 cm</p><p>	potong kotak 90 x 55 cm</p><p>	 </p><p>	 </p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(99, 'JUMLAH PRODUKSI (ORDER + INSHEET)', '<p>	Perhitungan jumlah Produksi (Jumlah order + insheet)</p><p>	Alur Proses Panjang (misalnya: Cetak - dof - pond - finishing)</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/Proses%20panjang.jpg\"></p><p>	Alur Proses Pendek (misalnya: Cetak - dof - pond)</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/Proses%20pendek.jpg\"></p><p>	 </p><p>	 </p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(100, 'KOMPOSISI CETAK BLACK', '<p>\r\n	Bandung, Black (hitam) ketika nanti di cetak harus memenuhi komposisi:</p>\r\n<p>\r\n	C  =  60 %</p>\r\n<p>\r\n	M  =  0 %</p>\r\n<p>\r\n	Y  =  30 %</p>\r\n<p>\r\n	K  =  100 %</p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	Jakarta, Black (hitam) ketika nanti di cetak harus memenuhi komposisi:</p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	C  =  50%</p>\r\n<p>\r\n	M  =  50%</p>\r\n<p>\r\n	Y  =  50%</p>\r\n<p>\r\n	K  =  100 %</p>\r\n<p>\r\n	update : 20 Nov 2013</p>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27');
INSERT IGNORE INTO `data_sops` (`id`, `judul`, `isi`, `sop_bagian_id`, `global`, `created_at`, `updated_at`) VALUES
(101, 'ISTILAH CETAK', '<p>	Ada 4</p><p>	1.  1 Muka</p><p>	      Cetak dengan satu sisi, menggunakan 1 film (1 plat) untuk 1 warna, 4 film untuk full colour.</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/1%20film.jpg\"></p><p>	2.  BBS</p><p>	     Cetak dengan dua sisi, menggunakan 1 film (1 plat) untuk 1 warna, 4 film untuk full colour.</p><p>	     Balik kertas (portrait) dengan poros horizontal.</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/BBS.jpg\"></p><p>	3.  BBB</p><p>	     Cetak dengan dua sisi, menggunakan 1 film (1 plat) untuk 1 warna, 4 film untuk full colour.</p><p>	     Balik kertas (portrait) dengan poros vertikal.</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/BBB.jpg\"></p><p>	4.  8 Plat (Bolak balik ganti plat).</p><p>	     Cetak dengan 2 sisi (bolak balik), menggunakan 2 film (2 plat)</p><p>	<img alt=\"\" src=\"/project/pb//images/2%20film.jpg\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(102, 'FOOD BOX, UNDANGAN, DLL KONDISIONAL PRODUK', '<p>	 </p><p>	1. Pastikan bentuk &amp; ukuran produk (box/undangan)</p><p>	2. Jarak konten teks dengan pisau minimal = 5mm.</p><p>	3. Tambahkan luas background di tiap sisi, minimal = 3 mm.</p><p>	4. Buat satu desain, lalu repeat desain sesuai banyaknya order. </p><p>	5. <strong>Optimalkan posisi setting dengan plano.</strong> </p><p>	     Misalnya produk berbentuk + akan lebih efisien dengan setting bentuk x. </p><p>	     Atau bentuk memanjang tak beraturan akan lebih efisien dengan setting miring 30 derajat.</p><p>	6. Setting BBS (jika bolak balik).</p><p>	7. Buat cross potong.</p><p>	8. Buat cross sudut.</p><p>	9. Buat cross warna di luar konten (jika full colour).</p><p>	10. Save as menjadi undangan_set.cdr di folder Post Set.</p><p>	11. Print ukuran sebenarnya, cek kelayakan teks dan gambar.</p><p>	12. Print dummy BW (black white)/ FC (full colour), fit to A4.</p><p>	13. Jika OK, jadikan curve. Atau copy font.</p><p>	14. Tulis ukuran film pada sudut kanan atas dummy. Misalnya ukuran film menjadi 305 x 430 mm.</p><p>	      Tulis juga ukuran film pada nama file. Contoh <strong>undangan_film420x290mm.cdr</strong>   </p><p>	15. Selesai  </p><p>	 </p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/kemasan%20final.jpg\"></p><p>	 </p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/undangan%20final%202.jpg\"></p><p>	 </p><p>	 </p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(103, 'BUKU TABUNGAN', '<p>\r\n	Tambahkan desain masing2 sisi 5mm.</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:37:09'),
(105, 'JO Brataco (ETIKET STIKER)', '<p>\r\n	<strong>ETIKET STIKER</strong></p>\r\n<p>\r\n	Order Etiket Stiker Brataco merupakan order tetap, sehingga desain dan bahan pun akan selalu sama.</p>\r\n<p>\r\n	Perhitungan yg ada berdasarkan jumlah order saja. Contoh File:<strong> \\rutin\\brataco\\etiket\\final 4 sept 09.cdr</strong></p>\r\n<p>\r\n	Film file ukuran <strong>36x31 cm</strong>.</p>\r\n<p>\r\n	Ada dua macam bahan yg selalu digunakan</p>\r\n<p>\r\n	<strong>1. Stiker Lintek HVS 70x109 cm</strong></p>\r\n<p>\r\n	    1 plano jadi 6 bagian, potong 35x36 cm. 1 area cetak (31x35.5) jadi 2 lembar etiket</p>\r\n<p>\r\n	      Project : ukuran 31 x 36 cm, bahan stiker lintek hvs, cetak 3 warna (hitam,biru dan merah), pond 1/2 tembus pisau L5</p>\r\n<p>\r\n	<strong>2. HVS Double Folio HVS100 gr, 42x33 cm</strong></p>\r\n<p>\r\n	    Untuk bahan ini tidak perlu potong. 1 double folio = 1 cetakan. Sesuaikan dengan jumlah settingan.</p>\r\n<p>\r\n	     Projec t: area cetak 31 x 36 cm, kertas hvs 100gr, cetak 3 warna (hitam,biru dan merah), porporasi , pisau L4</p>\r\n<p>\r\n	Contoh:</p>\r\n<p>\r\n	Order: masing-masing 2500 pcs</p>\r\n<p>\r\n	jadi:</p>\r\n<p>\r\n	<strong>Stiker Lintek HVS</strong>, bahan = <strong>240</strong> plano, insheet 380</p>\r\n<p>\r\n	<strong>HVS Double Folio HVS, </strong>bahan = <strong>3 rim</strong> double folio, insheet 500</p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	<strong>Catatan:</strong></p>\r\n<p>\r\n	untuk cetak berikutnya, lihat sisa produksi sebelumnya. Jika ada sisa (misalnya 200 pcs),</p>\r\n<p>\r\n	maka untuk insheet dikurangi sisa tersebut (380-200= 180 pcs = 90 cetak = 15 plano)</p>\r\n<p>\r\n	Begitu seterusnya..</p>\r\n<p>\r\n	_______________________________________________________________________________</p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	STIKER PENANDAAN (update 12 Juli 2013)</p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	Project:</p>\r\n<table><tbody><tr><td>\r\n				stiker penandaan</td><td>\r\n				bahan korosif      </td><td>\r\n				2.000</td><td>\r\n				900</td><td>\r\n				lainnya:ukuran 17 x 35 cm, stiker chromo, cetak 2 warna, pond 1/2 tembus  </td></tr></tbody></table>\r\n<table><tbody><tr><td>\r\n				stiker penandaan</td><td>\r\n				bahan berbahaya</td><td>\r\n				1.000</td><td>\r\n				900</td><td>\r\n				lainnya::ukuran 17 x 35 cm, stiker chromo, cetak 2 warna, pond 1/2 tembus  </td></tr></tbody></table>\r\n<p>\r\n	Stiker chromo 108x70 cm, potong jadi 10, ukuran potong 21,6x35 cm, area cetak 17x30 cm.</p>\r\n<p>\r\n	file terakhir di sini W:\\brataco\\penandaan\\post set</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(106, 'CARA CEK KELAYAKAN IMAGE, UTK FILE COREL EXPORT PDF', '<p>\r\n	1. Buka file asli Corel, dan file yg sudah di export PDF.</p>\r\n<p>\r\n	2. zoom 1 image tertentu yg ada di corel</p>\r\n<p>\r\n	3. Klik Menu Bitmap, pilih Convert to Bitmap. </p>\r\n<p>\r\n	    Pada menu pilih DPI = 300</p>\r\n<p>\r\n	4. Bandingkan image bitmap (Corel) dengan image di file PDF.</p>\r\n<p>\r\n	5. Jika image sama maka, file image PDF layak untuk cetak.</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(107, 'JO CD LABEL & COVER DVD', '<p>\r\n	<strong>Stiker label CD/DVD</strong></p>\r\n<p>\r\n	1. Ukuran Label 130x251 mm.</p>\r\n<p>\r\n	2. diameter luar (besar) 117 mm, diameter dalam (kecil) 17 mm.</p>\r\n<p>\r\n	3. jarak antara dua diameter luar = 5 mm.</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(108, 'JO BOX BEBEK GARANG', '<p>\r\n	ATAS</p>\r\n<p>\r\n	Ukuran file                  = 494x244 mm, 1 file, 2 tutup box</p>\r\n<p>\r\n	Bahan                          = duplex 310 108x79 cm</p>\r\n<p>\r\n	potong jadi 6, ukuran = 50x26 cm</p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	BAWAH</p>\r\n<p>\r\n	Ukuran file                  = 342x342 mm, 1 file, 1 box</p>\r\n<p>\r\n	Bahan                                   = duplex 310, 108x79 cm</p>\r\n<p>\r\n	potong jadi 6, ukuran  = 36x39,5 cm</p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	Biasanya Order selalu 8000 pcs</p>\r\n<p>\r\n	ATAS: bahan 720 plano, 1 plano dapat 12 tutup box. Total dapat 8640 tutup box</p>\r\n<p>\r\n	BAWAH: bahan 1440 plano, 1 plano dapat 6 box bawah. Total dapat 8640 bawah box</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(109, 'JO KHUSUS BOX VASSMEDICA', '<p>\r\n	Rumus Produksi:</p>\r\n<p>\r\n	105% jumlah order + 150</p>\r\n<p>\r\n	plano duplex 90x120 cm</p>\r\n<p>\r\n	1 plano jadi 6 potong</p>\r\n<p>\r\n	mesin oliver 58</p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	JO 3M (last 23-07-12)</p>\r\n<p>\r\n	Duplex 400 gr, 90x120 cm. Potong 35x60 cm (area 573x336 mm), mesin oliver 66. insheet 300.</p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	Update 08-07-13</p>\r\n<p>\r\n	 </p>\r\n<div>\r\n	teguh\r\n	<div>\r\n		(11:47:48 AM) emang pisau tieon sama earloop sama utk semuanya</div>\r\n</div>\r\n<div>\r\n	(11:47:53 AM) yg beda cmn 2, tolong diingat</div>\r\n<div>\r\n	(11:47:58 AM) cmn jeva sama mdmask</div>\r\n<div>\r\n	(11:48:01 AM) lainnya sama semua</div>\r\n<div>\r\n	(11:48:18 AM) jeva ada bolongnya, md mask ada panah, jd digeser</div>\r\n<div>\r\n	(11:48:21 AM) cmn itu</div>\r\n<div>\r\n	(11:48:28 AM) makanya pisau gak akan dinamai per dus</div>\r\n<div>\r\n	(11:48:30 AM) karena sama semua</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	- tinggi box tie on semua akan distandarkan jadi 143 mm (update tgl 09-07-13)</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	contoh:</div>\r\n<div>\r\n	Maxicare tie on, settingan tingginya 148 mm, tapi yg sudah-sudah pisaunya pake yg 143 mm.</div>\r\n<div>\r\n	_________________________________________________________________________</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	FACEMASK</div>\r\n<div>\r\n	Ear Loop 18,5 x 10,5 x 9,5 cm (kait lancip lurus)</div>\r\n<div>\r\n	Tie ON 18 x 14,3 x 10 cm (kait lengkung)</div>\r\n<div>\r\n	Produksi terbaru, face mask ear loop 2 mata, pisau BX 4.</div>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(110, 'JO ISI MAP BANK MEGA', '<p>	Bahan : Manila merk Tjiwi</p><p>	Misal:</p><p>	Order 1000</p><p>	Beli bahan 900 plano ukuran plano 86x61 cm</p><p>	Potong jadi 5, ukuran 25x34 cm</p><p>	 </p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/JO%20isi%20Map%20BANK%20MEGA%2021%20jan%202014.jpg\"></p><p>	____________________________________________________________________________________________________</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/jo%20isi%20map%20bank%20Mega.jpg\"></p><p>	____________________________________________________________________________________________________</p><p>	Dummy cetakan Bank Mega</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/dummy%20cetakan%20bank%20mega.jpg\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(111, 'JO MAP KREDIT PENSIUN', '<p>	<strong>Map 47x35 cm (terbuka)</strong></p><p>	Bahan </p><p>	  - Buffalo krem tekstur jeruk, </p><p>	  - plano 108x79 cm, 1 plano jadi 4, ukuran potong 50x36 cm.</p><p>	  - potong plano 50x36 cm, kalo order 1000, planonya 285, + kuping 72 plano</p><p>	  - cetak 2 muka, 1 warna hitam.</p><p>	  - kuping potong plano jadi 16 ukuran potong 27x19 cm.</p><p>	  - kebutuhan bahan kuping kihat stok di mujib.</p><p>	Area cetakan lihat gambar di bawah.</p><p>	Atau lihat D:\\koperasi aliansi sejahtera\\2012\\map\\kredit pensiun\\post set\\aturan cetak map kredit pensiun.jpg</p><p>	 </p><p>	Bahan untuk <strong>Kuping</strong></p><p>	1 plano jadi 16, ukuran potong 27x19 cm</p><p>	 </p><p>	Aturan cetak Map</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/aturan%20cetak%20map%20kredit%20pensiun.jpg\"></p><p>	 </p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/JO%20Map%20Kredit%20pensiun.jpg\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(112, 'JO DSE (Tempat Kartu & Katalog DSE)', '<p>	<strong><u>JO tempat Kartu DSE</u></strong></p><p>	Order = 10.000, bahan plano 100x65 = 295 pcs potong jadi 6</p><p>	ukuran 10,4 x 14,5 cm, kertas AP 210 gr, offset 1 muka, 1 warna</p><p>	Potong = 32,5 x 33 cm</p><p>	area cetak = 32 x 30 cm</p><p>	pond L 29</p><p>	 </p><p>	<strong><u>Amplop DSE &amp; Cover Katalog</u></strong></p><p>	Amplop DSE dicetak bareng dengan cover katalog (buat stok)</p><p>	File yg dipake terakhir yg 2 mata, untuk optimasi bahan.</p><p>	Macam macam plano Art Carton yg dipake (109x79, 61x92, 65x90, 65x100 cm)</p><p>	posisi file: rutin\\dse\\2013\\amplop+cover katalog</p><p>	 </p><p>	<strong><u>Layout setting katalog DSE</u></strong></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/seting%20katalog%20DSE(1).jpg\"><img alt=\"\" src=\"/project/pb/gambar/images/format%20layout%20buku%20katalog%20DSE.jpg\"></p><p>	<strong>Format Lipat Isi Katalog DSE di mesin lipat:</strong></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/1_%202013-03-08%2014_56_39.jpg\"></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/2_%202013-03-08%2014_57_01.jpg\"></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/3_%202013-03-08%2014_58_30.jpg\"></p><p>	 </p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(113, 'JO OFFSET (tidak berlaku indigo) UNDANGAN RSHS', '<p>\r\n	ISI</p>\r\n<ul><li>\r\n		ukuran Jadi\r\n		<ul><li>\r\n				isi            = A5</li><li>\r\n				amplop  = 215x150 mm</li></ul></li><li>\r\n		Order <strong>300 pcs</strong></li><li>\r\n		area cetak 31 x 45 cm. 1 area jadi 4</li><li>\r\n		Plano 108x79 cm, <strong>19 pcs</strong></li><li>\r\n		potong jadi 5, ukuran 33 x 45 cm</li></ul>\r\n<p>\r\n	AMPLOP</p>\r\n<ul><li>\r\n		ukuran jadi 215x150 mm</li><li><strong>order 300</strong></li><li>\r\n		area cetak 245x326 mm. 1 area jadi 1</li><li>\r\n		Plano 108x79 cm, <strong>49 pcs</strong></li><li>\r\n		potong jadi 8, ukuran 27 x 39,5 cm</li></ul>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(114, 'JO BOX SI KRITING', '<p>\r\n	 </p>\r\n<ul><li>\r\n		Bahan\r\n		<ul><li>\r\n				               duplex 310 gr, 108 x 79 cm</li><li>\r\n				               potong jadi 6, ukuran = 36 x 39,5 cm</li></ul></li><li>\r\n		Cetakan\r\n		<ul><li>\r\n				               area cetak = 34 x 39,5 cm</li><li>\r\n				               1 muka, 1 warna orange</li></ul></li><li>\r\n		Finish\r\n		<ul><li>\r\n				               tanpa laminasi</li><li>\r\n				               pond</li></ul></li></ul>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(115, 'JO PAPER BAG PUPUK KUJANG', '<p>\r\n	order 500 pcs, ukuran 22 x 10,5 x 34 cm, kertas samsons, cetak 1 warna (hitam), tali kur emas</p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	Bahan: Samsons 120 x 90 cm 130 gr (bahan 200 pcs), potong jadi 6, ukuran 45 x36 cm</p>\r\n<p>\r\n	film 45x36 cm. </p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	mesin harus 52</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(116, 'Cara Instalasi Photocopy Canon IR 3570/4570 PCL5e', '<p>\r\n	 </p>\r\n<div>\r\n	Cara Install Photocopy</div>\r\n<div>\r\n	1. Start - Device and Printer - Add Printer</div>\r\n<div>\r\n	2. Pilih Canon IR 3570/4570 PCL5e - Next</div>\r\n<div>\r\n	3. lalu muncul Browse - Pilih File di </div>\r\n<div>\r\n	\\\\SERVER\\installer\\Driver\\photocopy\\driver iR series\\driver iR series\\AutoPlay\\Docs\\Printer\\win2k_vista\\pcl5e_5c</div>\r\n<div>\r\n	4. Next - Tunggu sampai instalasi Selesai</div>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'administrasi' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(117, 'Banner, X Banner, roll banner, spanduk', '<p>\r\n	1. Save as file desain menjadi jpeg.</p>\r\n<p>\r\n	2. buka file jpeg di Photoshop.</p>\r\n<p>\r\n	3. Cross cek ukuran file dengan ukuran di project.</p>\r\n<p>\r\n	4. Tekan <strong>Ctrl+Alt+i </strong>, lalu perhatikan kotak dialog:</p>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/pixel%20dimention.jpg\"></p>\r\n<p>\r\n	Keterangan (lihat yg di blok ungu): </p>\r\n<p>\r\n	a. <strong>Pixel Dimention</strong> = maksimal adalah 150 MB, cara adjustment-nya adalah dgn cara:</p>\r\n<p>\r\n	-  <strong>Width &amp; High</strong> sesuaikan dengan ukuran banner sebenarnya (sesuai project)</p>\r\n<p>\r\n	- ubah naikkan / turunkan <strong>Resolution</strong> hingga angka Pixel Dimention mendekati 150 MB.</p>\r\n<p>\r\n	5. save as ke jpg lagi, samakan data ini: Quality 8, Format Progressive.</p>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/save%20as%20jpeg%20progressive.jpg\"></p>\r\n<p>\r\n	6. klik OK, selesai<br>\r\n	<br>\r\n	<br>\r\n	 </p>\r\n<table><thead><tr><th>\r\n				x(cm)</th><th>\r\n				y(cm)</th><th><p>\r\n					Resolusi (dpi)</p></th></tr></thead><tbody><tr><td>\r\n				50</td><td>\r\n				100</td><td><strong>260</strong></td></tr><tr><td>\r\n				60</td><td>\r\n				160</td><td>\r\n				187</td></tr><tr><td>\r\n				100</td><td>\r\n				100</td><td><strong>183</strong></td></tr><tr><td>\r\n				150</td><td>\r\n				100</td><td><strong>150</strong></td></tr><tr><td>\r\n				250</td><td>\r\n				75</td><td><strong>134</strong></td></tr><tr><td>\r\n				200</td><td>\r\n				100</td><td><strong>130</strong></td></tr><tr><td>\r\n				250</td><td>\r\n				100</td><td><strong>116</strong></td></tr><tr><td>\r\n				300</td><td>\r\n				100</td><td><strong>106</strong></td></tr><tr><td>\r\n				350</td><td>\r\n				100</td><td><strong>98</strong></td></tr><tr><td>\r\n				400</td><td>\r\n				100</td><td><strong>91</strong></td></tr><tr><td>\r\n				450</td><td>\r\n				100</td><td><strong>86</strong></td></tr><tr><td>\r\n				500</td><td>\r\n				100</td><td><strong>82</strong></td></tr><tr><td>\r\n				550</td><td>\r\n				100</td><td><strong>78</strong></td></tr><tr><td>\r\n				600</td><td>\r\n				100</td><td><strong>75</strong></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(120, 'PEMBUATAN SURAT PENAWARAN', '<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					<strong>CV. TAFIO TOTAL SOLUSI</strong></p></td><td><p>\r\n					<strong>PEMBUATAN SURAT PENAWARAN</strong></p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					<strong>NO</strong></p></td><td><p>\r\n					<strong>KEGIATAN</strong></p></td></tr><tr><td><p>\r\n					1</p></td><td><p>\r\n					terima permintaan surat penawaran</p></td></tr><tr><td><p>\r\n					2</p></td><td><p>\r\n					hitung harga barang sesuai spek yang diminta</p></td></tr><tr><td><p>\r\n					3</p></td><td><p>\r\n					buka folder surat penawaran (server/rutin/tafio/penawaran)</p></td></tr><tr><td><p>\r\n					4</p></td><td><p>\r\n					buat file word dengan no surat terakhir</p></td></tr><tr><td><p>\r\n					5</p></td><td><p>\r\n					save as file doc dengan nama no surat +1 dari no surat terakhir</p></td></tr><tr><td><p>\r\n					6</p></td><td><p>\r\n					cek &amp; tulis tanggal kirim surat</p></td></tr><tr><td><p>\r\n					7</p></td><td><p>\r\n					cek &amp; tulis no surat penawaran</p></td></tr><tr><td><p>\r\n					8</p></td><td><p>\r\n					cek &amp; tulis perihal surat</p></td></tr><tr><td><p>\r\n					9</p></td><td><p>\r\n					cek &amp; tulis kepada siapa surat penawaran ditujukan</p></td></tr><tr><td><p>\r\n					10</p></td><td><p>\r\n					tulis nama, spesifikasi barang yang diminta dan harganya</p></td></tr><tr><td><p>\r\n					11</p></td><td><p>\r\n					tuliskan PPN pada jumlah total <strong>(bila diminta)</strong></p></td></tr><tr><td><p>\r\n					12</p></td><td><p>\r\n					tulis waktu pengerjaan berapa lama</p></td></tr><tr><td><p>\r\n					13</p></td><td><p>\r\n					tulis kalimat penutup</p></td></tr><tr><td><p>\r\n					14</p></td><td><p>\r\n					tulis salam penutup</p></td></tr><tr><td><p>\r\n					15</p></td><td><p>\r\n					tulis pengirim surat</p></td></tr><tr><td><p>\r\n					16</p></td><td><p>\r\n					attach ttd digital</p></td></tr><tr><td><p>\r\n					17</p></td><td><p>\r\n					cek ulang harga,qty dan spesifikasi</p></td></tr><tr><td><p>\r\n					18</p></td><td><p>\r\n					acc manajer yang bertugas</p></td></tr><tr><td><p>\r\n					19</p></td><td><p>\r\n					Konversi file word ke bentuk PDF</p></td></tr><tr><td><p>\r\n					20</p></td><td><p>\r\n					kirim surat via email atau fax</p></td></tr><tr><td><p>\r\n					21</p></td><td><p>\r\n					follow up surat apakah sudah diterima atau belum</p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					No :</p></td><td><p>\r\n					Dept : Marketing / Pemasaran</p></td><td><p>\r\n					No Revisi:</p></td></tr><tr><td><p>\r\n					Halaman :   dari</p></td><td><p>\r\n					Tgl Terbit : 14 JANUARI 2013</p></td><td><p>\r\n					Tgl Revisi :</p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'marketing' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(122, 'TERIMA TELEPON', '<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					<strong>CV. TAFIO TOTAL SOLUSI</strong></p></td><td><p>\r\n					<strong>TERIMA TELEPON</strong></p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					<strong>NO</strong></p></td><td><p>\r\n					<strong>KEGIATAN</strong></p></td></tr><tr><td><p>\r\n					1</p></td><td><p>\r\n					Waktu ucapan salam :</p><ul><li>\r\n						00.00 s/d 10.00 selamat pagi</li><li>\r\n						10.00 s/d 15.00 selamat siang</li><li>\r\n						15.00 s/d 18.00 selamat sore</li><li>\r\n						18.00 s/d 24.00 selamat malam</li></ul></td></tr><tr><td><p>\r\n					2</p></td><td><p>\r\n					Buka Salam pembuka :<em> <strong>”hallo, selamat ………….. (pagi, siang, sore)\"</strong></em></p></td></tr><tr><td><p>\r\n					3</p></td><td><p>\r\n					Tanyakan dan catat nama penelepon :<em> <strong>”maaf dengan siapa saya berbicara?” </strong></em>jika pelanggan enggan memberi tahu maka jangan dipaksakan</p></td></tr><tr><td><p>\r\n					4</p></td><td><p>\r\n					Tanyakan keperluan : <strong><em>“ada yang bisa saya bantu Bu/Pak …….. (sebutkan namanya)?”</em></strong></p></td></tr><tr><td><p>\r\n					5</p></td><td><p>\r\n					Bila ingin berbicara dengan yang lain, konfirmasikan lalu sambungkan dengan memberi tahu penerima darimana :</p><p>\r\n					<strong><em>“mohon tunggu sebentar Bu/Pak ………. (sebutkan namanya) saya sambungkan ke Pak ……..“</em></strong></p></td></tr><tr><td><p>\r\n					6</p></td><td><p>\r\n					Bila penerima sedang sibuk :</p><p>\r\n					<strong><em>“maaf Bu/Pak …………. (sebutkan namanya), Pak ………. (penerima) sedang online/menerima telepon, ada pesan Bu/Pak?“</em></strong></p><p>\r\n					Bila ada pesan dicatat / bila tidak ada beri tahu bahwa penerima mendapat telepon dari …… (penelepon)</p></td></tr><tr><td><p>\r\n					7</p></td><td><p>\r\n					Bila menanyakan harga, tanyakan detail spek, catat, beri penawaran harga, dijawab sesuai dengan standar harga dan jumlah minimal order (liat data di web / data product knowledge)</p><p>\r\n					Atau sambungkan dengan marketing : <strong><em>“ jika Ibu/Bapak ………. (sebutkan namanya) mau menanyakan harga, saya sambungkan ke bagian marketing Bu/Pak”</em></strong></p><p>\r\n					Lalu<strong><em> “Mohon tunggu sebentar”</em></strong></p><p>\r\n					Beri tahu marketing nama penelepon, darimana dan spek order (bila ada)</p></td></tr><tr><td><p>\r\n					8</p></td><td><p>\r\n					Bila ada pernyataan tidak bisa maka sampaikan dengan santun dan beri solusi <strong><em>“mohon maaf untuk brosur 5000pcs kami belum bisa dalam waktu 1 hari, standar waktu kami 3 hari”</em></strong></p></td></tr><tr><td><p>\r\n					9</p></td><td><p>\r\n					Salam penutup :<em> <strong>“terimakasih telah menghubungi percetakanbandung, selamat pagi/siang/sore”</strong></em></p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					No :</p></td><td><p>\r\n					Dept : Marketing / Pemasaran</p></td><td><p>\r\n					No Revisi:</p></td></tr><tr><td><p>\r\n					Halaman :   dari</p></td><td><p>\r\n					Tgl Terbit : 14 JANUARI 2013</p></td><td><p>\r\n					Tgl Revisi :</p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'marketing' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(123, 'CHAT MELALUI YAHOO MASSENGER', '<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					<strong>CV. TAFIO TOTAL SOLUSI</strong></p></td><td><p>\r\n					<strong>CHAT MELALUI YAHOO MASSENGER</strong></p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					<strong>NO</strong></p></td><td><p>\r\n					<strong>KEGIATAN</strong></p></td></tr><tr><td>\r\n				1</td><td>\r\n				setting YM : centang sign in automatically dan centang save all massages dibagian archive</td></tr><tr><td><p>\r\n					1</p></td><td><p>\r\n					Pergunakan kata-kata baku dan sopan</p></td></tr><tr><td><p>\r\n					2</p></td><td><p>\r\n					Standar balasan <u>+</u> 1 menit , jangan sampai pelanggan menekan <strong><em>“BUZZ”</em></strong> karena tidak ada respon dari kita</p></td></tr><tr><td><p>\r\n					3</p></td><td><p>\r\n					Tunggu sampai pelanggan selesai mengetik setelah itu baru kita balas</p></td></tr><tr><td><p>\r\n					4</p></td><td><p>\r\n					Emotikon / icon digunakan bila perlu</p></td></tr><tr><td><p>\r\n					5</p></td><td><p>\r\n					Tanyakan nama lalu perkenalkan diri:</p><p>\r\n					<em> <strong>“maaf dengan siapa ini?, saya ……. Customer Service percetakanbandung.com”</strong></em></p></td></tr><tr><td><p>\r\n					6</p></td><td><p>\r\n					Tanyakan keperluan:</p><p>\r\n					<em> <strong>“ada yang bisa dibantu Pak/Bu/Mba/Mas …..?”</strong></em></p></td></tr><tr><td><p>\r\n					7</p></td><td><p>\r\n					Tanyakan spesifikasi order detail jenis produk, jumlah, ukuran, bahan yg digunakan, cetakan (FC/tidak, 1 muka/2muka), jenis finishing dll :</p><p>\r\n					<strong><em>“saya minta spesifikasi  ….. (jumlah order, ukuran, kertas yg digunakan, cetak 1 atau 2 muka) ?” </em></strong></p></td></tr><tr><td><p>\r\n					8</p></td><td><p>\r\n					Edukasi/jelaskan pelanggan yang belum tahu soal spesifikasi percetakan yang akan diorder secara detail</p></td></tr><tr><td><p>\r\n					9</p></td><td><p>\r\n					Bila perlu dihitung<em> <strong>“mohon tunggu sebentar, saya hitung dulu”</strong></em></p></td></tr><tr><td><p>\r\n					10</p></td><td><p>\r\n					Untuk penawaran harga konsultasikan dengan manajer yang bertugas</p></td></tr><tr><td><p>\r\n					11</p></td><td><p>\r\n					Penawaran disertakan dengan spesifikasi order detail dan harganya :</p><p>\r\n					 <strong><em>“untuk order brosur 1000pcs,Uk A4, Art Paper 210 gr, Full Colour 2 muka, tanpa laminasi, Lipat 3 harganya Rp. 870.000,- “</em></strong></p></td></tr><tr><td><p>\r\n					12</p></td><td><p>\r\n					Akhiri chat dengan santun dan sopan, misal<em> <strong>“saya tunggu kabar baiknya, terimakasih”</strong></em></p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					No :</p></td><td><p>\r\n					Dept : Marketing / Pemasaran</p></td><td><p>\r\n					No Revisi:</p></td></tr><tr><td><p>\r\n					Halaman :   dari</p></td><td><p>\r\n					Tgl Terbit : 14 JANUARI 2013</p></td><td><p>\r\n					Tgl Revisi : 23 FEBRUARI 2013</p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'marketing' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(124, 'TERIMA & BALAS E - MAIL', '<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					<strong>CV. TAFIO TOTAL SOLUSI</strong></p></td><td><p>\r\n					<strong>TERIMA &amp; BALAS E - MAIL</strong></p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					<strong>NO</strong></p></td><td><p>\r\n					<strong>KEGIATAN </strong></p></td></tr><tr><td><p>\r\n					1</p></td><td><p>\r\n					Standar Balasan 15 s/d 30 menit</p></td></tr><tr><td><p>\r\n					2</p></td><td><p>\r\n					Terima E-mail, Cek pengirim (siapa dan darimana), detail isi (keinginan, spek order dll)</p></td></tr><tr><td><p>\r\n					3</p></td><td><p>\r\n					Bila minta penawaran harga, forward ke bag marketing di marketing.tafio@yahoo.com</p></td></tr><tr><td><p>\r\n					4</p></td><td><p>\r\n					Untuk penawaran harga, spesifikasi kurang detail maka diasumsikan lalu hitung dan kirim penawaran dengan spesifikasi tertulis jelas</p></td></tr><tr><td><p>\r\n					5</p></td><td><p>\r\n					Format Email :</p><ul><li>\r\n						Salam pembuka (<strong>selamat pagi/siang/sore</strong>)</li><li>\r\n						Perkenalan (bila pelanggan baru)</li><li>\r\n						Isi penawaran (spesifikasi tertulis jelas dan detail)</li><li>\r\n						Penawaran harga satuan dan total</li><li>\r\n						Waktu pengerjaan</li><li>\r\n						Tulis no kontak yang bisa dihubungi</li><li>\r\n						Kata penutup : <strong>saya tunggu kabar baiknya, atas perhatiannya saya ucapkan terimakasih</strong></li><li>\r\n						Salam penutup : salam / best regards</li><li>\r\n						Tulis nama dan jabatan jelas (setting terlebih dahulu) :</li></ul><p>\r\n					-- </p><p>\r\n					Salam,</p><p>\r\n					 </p><p>\r\n					<strong>Erwin</strong></p><p>\r\n					<strong>Marketing</strong></p><p>\r\n					 </p><p>\r\n					<strong>Percetakan Bandung</strong></p><p>\r\n					Jl. Kembar Timur 1 no. 11A Bandung</p><p>\r\n					telp. 022-61300300</p><p>\r\n					fax. 022-5221199</p><p>\r\n					 </p><p>\r\n					website. </p><p>\r\n					<a href=\"http://percetakanbandung.com/\">percetakanbandung.com</a></p><p>\r\n					<a href=\"http://tafio.com/\">tafio.com</a></p></td></tr><tr><td><p>\r\n					6</p></td><td><p>\r\n					Tulis alamat email</p></td></tr><tr><td><p>\r\n					7</p></td><td><p>\r\n					Tulis subject / perihal email misal penawaran harga, revisi desain dll</p></td></tr><tr><td><p>\r\n					8</p></td><td><p>\r\n					Tambahkan cc (tembusan) bila perlu</p></td></tr><tr><td><p>\r\n					9</p></td><td><p>\r\n					Cek status setelah 3 menit mengirim email, bila ada email masuk dengan status <strong>delivery error</strong>  maka <strong>email belum terkirim</strong> (cek alamat kirim, kapasitas penerima berapa kb dll)</p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					No :</p></td><td><p>\r\n					Dept : Marketing / Pemasaran</p></td><td><p>\r\n					No Revisi:</p></td></tr><tr><td><p>\r\n					Halaman :   dari</p></td><td><p>\r\n					Tgl Terbit : 14 JANUARI 2013</p></td><td><p>\r\n					Tgl Revisi :</p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'marketing' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32');
INSERT IGNORE INTO `data_sops` (`id`, `judul`, `isi`, `sop_bagian_id`, `global`, `created_at`, `updated_at`) VALUES
(125, 'TERIMA ORDER', '<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					<strong>CV. TAFIO TOTAL SOLUSI</strong></p></td><td><p>\r\n					<strong>TERIMA ORDER</strong></p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					<strong>NO</strong></p></td><td><p>\r\n					<strong>KEGIATAN</strong></p></td></tr><tr><td><p>\r\n					1</p></td><td><p>\r\n					Terima klien , Isi form pelanggan baru</p></td></tr><tr><td><p>\r\n					2</p></td><td><p>\r\n					Isi form Purchase Order (PO) :</p><ul><li>\r\n						Tanggal order (hari, dd/mm/yy)</li><li>\r\n						Tanggal selesai (hari, dd/mm/yy)</li><li>\r\n						Nama pelanggan</li><li>\r\n						Jenis produk</li><li>\r\n						Desain</li><li>\r\n						Jumlah order</li><li>\r\n						Ukuran</li><li>\r\n						Jumlah warna cetak (FC/BW/warna khusus)</li><li>\r\n						Jenis kertas</li><li>\r\n						Jumlah rangkap dan warnanya (untuk Nota)</li><li>\r\n						Spesifikasi cover (untuk buku, majalah, bulletin)</li><li>\r\n						Spesifikasi Isi (untuk buku, majalah, bulletin)</li><li>\r\n						Finishing (laminasi, emboss, foil, lipat, hekter, blok lem, jahit, porporasi, numerator, warna tali paper bag, potong ujung bulat untuk kartu nama dll)</li><li>\r\n						Keterangan (waktu mendesak, kirim ekspedisi dll)</li><li>\r\n						Harga satuan dan harga total</li><li>\r\n						Ttd penerima order dan pelanggan</li></ul></td></tr><tr><td><p>\r\n					3</p></td><td><p>\r\n					Cek file desain (lihat SOP TERIMA FILE DESAIN)</p></td></tr><tr><td><p>\r\n					4</p></td><td><p>\r\n					Hitung harga dan Konfirmasi ulang mengenai spesifikasi order ke pelanggan</p></td></tr><tr><td><p>\r\n					5</p></td><td><p>\r\n					Setelah harga dan desain sudah ok, PO diberitahukan ke Manajer yang bertugas</p></td></tr><tr><td><p>\r\n					6</p></td><td><p>\r\n					Jelaskan detail order yang diinginkan (waktu, desain atau ada keinginan khusus dari pelanggan) pada manajer yang bertugas serta tuliskan pada kolom informasi di samping order di web</p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					No :</p></td><td><p>\r\n					Dept : Marketing / Pemasaran</p></td><td><p>\r\n					No Revisi:</p></td></tr><tr><td><p>\r\n					Halaman :   dari</p></td><td><p>\r\n					Tgl Terbit : 14 JANUARI 2013</p></td><td><p>\r\n					Tgl Revisi :</p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'marketing' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(126, 'TERIMA FILE DESAIN', '<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					<strong>CV. TAFIO TOTAL SOLUSI</strong></p></td><td><p>\r\n					<strong>TERIMA FILE DESAIN</strong></p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					<strong>NO</strong></p></td><td><p>\r\n					<strong>KEGIATAN </strong></p></td></tr><tr><td><p>\r\n					1</p></td><td><p>\r\n					File yang diterima dalam bentuk Corel, Photoshop, Adobe Indesign, Adobe Illustrator</p></td></tr><tr><td><p>\r\n					2</p></td><td><p>\r\n					Bila file dalam bentuk jpeg maka resolusi file gambar (JPEG/bitmap) minimal 300 dpi</p></td></tr><tr><td><p>\r\n					3</p></td><td><p>\r\n					Selalu Instal versi terbaru untuk software desain</p></td></tr><tr><td><p>\r\n					4</p></td><td><p>\r\n					Garis tipis yang digunakan maksimal 0,5 point</p></td></tr><tr><td><p>\r\n					5</p></td><td><p>\r\n					Warna yang dipakai adalah CYMK</p></td></tr><tr><td><p>\r\n					6</p></td><td><p>\r\n					Teks hitam ukuran kurang dari 18 point dan garis hitam dengan ketebalan kurang dari 6 point harus menggunakan warna 100% hitam</p></td></tr><tr><td><p>\r\n					7</p></td><td><p>\r\n					Untuk Lipatan atau porporasi diharapkan memberikan tanda garis kecil</p></td></tr><tr><td><p>\r\n					8</p></td><td><p>\r\n					Buka file, bila ada error (missing font/missing links dll) konfirmasi ke pelanggan</p></td></tr><tr><td><p>\r\n					9</p></td><td><p>\r\n					Bandingkan dengan file desain dengan produk contoh dari pelanggan (bila ada contoh)</p></td></tr><tr><td><p>\r\n					10</p></td><td><p>\r\n					Teks sudah di”curve” atau font sudah disertakan</p></td></tr><tr><td><p>\r\n					11</p></td><td><p>\r\n					Jenis font sudah pantas dilihat / mudah dibaca, teks tidak ada yang loncat dan ejaan tidak ada yang salah</p></td></tr><tr><td><p>\r\n					12</p></td><td><p>\r\n					Link disertakan (khusus illustrator/indesign)</p></td></tr><tr><td><p>\r\n					13</p></td><td><p>\r\n					Cek ukuran desain, sesuaikan dengan ukuran yang akan diorder, bila tidak sesuai konfirmasi ulang ke pelanggan</p></td></tr><tr><td><p>\r\n					14</p></td><td><p>\r\n					Cek gambar pecah atau tidak (zoom sampai 80% amati dengan seksama) dan cek penempatan gambar sudah pantas dilihat atau tidak</p></td></tr><tr><td><p>\r\n					15</p></td><td><p>\r\n					Catat Jika ada yang perlu di emboss dan foil di keterangan</p></td></tr><tr><td><p>\r\n					16</p></td><td><p>\r\n					Setelah selesai dicek, file desain disimpan di <strong><em>folder rutin</em></strong> :</p><ol><li>\r\n						Bila pelanggan baru, buat folder baru an pelanggan/perusahaan, lalu buat folder baru tahun order setelah itu jenis order misal<strong><em> (Rutin -&gt; Nama pelanggan -&gt; tahun -&gt; Nama produk -&gt; nama file desain)</em></strong></li><li>\r\n						Bila pelanggan lama, simpan desain di folder pelanggan buat folder baru tahun order setelah itu jenis order <strong><em>(Rutin -&gt; Nama pelanggan -&gt; tahun -&gt; Nama produk -&gt; nama file desain)</em></strong></li></ol></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					No :</p></td><td><p>\r\n					Dept : Marketing / Pemasaran</p></td><td><p>\r\n					No Revisi:</p></td></tr><tr><td><p>\r\n					Halaman :   dari</p></td><td><p>\r\n					Tgl Terbit :</p></td><td><p>\r\n					Tgl Revisi :</p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'marketing' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(127, 'FREQUENTLY ASKED QUESTION', '<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					<strong>CV. TAFIO TOTAL SOLUSI</strong></p></td><td><p>\r\n					<strong>FREQUENTLY ASKED QUESTION</strong></p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					<strong>NO</strong></p></td><td><p>\r\n					<strong>KEGIATAN</strong></p></td></tr><tr><td><p>\r\n					1</p></td><td><p>\r\n					<strong>Alamat Percetakan Bandung dimana?</strong></p><p>\r\n					Alamat kami di Jl. Kembar timur 1 no. 11A, untuk lebih jelasnya sudah kami sediakan google maps pada bagian profil ( link : ) di web kami <a href=\"http://www.percetakanbandung.com/\">www.percetakanbandung.com</a></p></td></tr><tr><td><p>\r\n					2</p></td><td><p>\r\n					<strong>Apakah ada minimum order untuk setiap produk?</strong></p><p>\r\n					Minimum order untuk mengoptimalkan harga, karena pada prinsipnya semakin banyak jumlah order maka akan didapat harga yang optimal.</p></td></tr><tr><td><p>\r\n					3</p></td><td><p>\r\n					<strong>Bagaimana cara order di Percetakan Bandung?</strong></p><p>\r\n					Kontak Divisi Marketing kami melalui YM, telp, BB, email atau datang langsung. Beritahukan jenis produk yang diinginkan beserta spesifikasinya lalu kami akan memberikan penawaran harganya. Bila harga sudah cocok maka file desain final diberikan atau dikirim via email.</p></td></tr><tr><td><p>\r\n					4</p></td><td><p>\r\n					<strong>Apakah bisa order via YM/email?</strong></p><p>\r\n					Bisa, kami spesialisasi dalam hal pemesanan online, Anda tinggal mengirimkan data desain via email, untuk pembayaran bisa ditransfer dan barang akan kami kirim. Komunikasi bisa melalui telp, YM, email atau BB.</p></td></tr><tr><td><p>\r\n					5</p></td><td><p>\r\n					<strong>Bagaimana mengetahui harga produk ?</strong></p><p>\r\n					Didalam web kami <a href=\"http://www.percetakanbandung.com/\">www.percetakanbandung.com</a> sudah disediakan fasilitas untuk menghitung harga suatu produk berdasarkan kebutuhan yang diperlukan, anda tinggal mengisi form yang ada lalu proses, harga akan langsung muncul. Harga tersebut bisa dijadikan patokan harga.</p></td></tr><tr><td><p>\r\n					6</p></td><td><p>\r\n					<strong>Bagaimana bila spesifikasi yang saya butuhkan tidak ada dalam perhitungan harga?</strong></p><p>\r\n					Hubungi Divisi Marketing kami atau isi form penawaran, kami akan memberikan penawaran harga sesuai dengan spesifikasi yang diberikan.</p><p>\r\n					                                                                                                         </p></td></tr><tr><td><p>\r\n					7</p></td><td><p>\r\n					<strong>Apakah ada ketentuan untuk file desainnya?</strong></p><p>\r\n					File desain kami terima dalam bentuk Corel, Illustrator, indesign, photoshop. Mohon diemail juga fontnya.</p></td></tr><tr><td><p>\r\n					8</p></td><td><p>\r\n					<strong>Kalau desain dalam bentuk jpeg, apakah bisa diproses?                                    </strong></p><p>\r\n					Akan kami lihat kelayakan file tersebut. Salah satu syaratnya adalah minimal resolusinya 300dpi.</p></td></tr><tr><td><p>\r\n					9</p></td><td><p>\r\n					<strong>Desain apakah dari klien atau bisa dibuatkan?</strong></p><p>\r\n					Desain biasanya dari klien, tapi jika desain belum ada, akan kami bantu dengan tambahan biaya desain (tergantung dengan jenis produk yang akan didesain).</p></td></tr><tr><td><p>\r\n					10</p></td><td><p>\r\n					<strong>Apakah bisa dibuatkan dummy terlebih dahulu?</strong></p><p>\r\n					Bisa, tergantung jenis produk yang diinginkan dan waktu selesainya suatu produk, bila waktu mepet maka dummy tidak bisa kami penuhi</p></td></tr><tr><td><p>\r\n					11</p></td><td><p>\r\n					<strong>Berapa lama waktu pengerjaan suatu produk cetak?</strong></p><p>\r\n					Lama pengerjaan tergantung dengan jenis produk dan spesifikasi cetakan, waktu selesai akan diberitahukan ketika kami terima pemberitahuan ordernya.</p></td></tr><tr><td><p>\r\n					12</p></td><td><p>\r\n					<strong>Bagaimana cara pembayarannya?</strong></p><p>\r\n					Diawal DP 50% sebagai tanda jadi, untuk pelunasan ketika barang kami kirim dan diterima oleh klien, kecuali klien di luar kota sebelum barang dikirim maka klien harus melunasi pembayarannya.</p></td></tr><tr><td><p>\r\n					13</p></td><td><p>\r\n					<strong>Apakah harga di web sudah termasuk ongkos kirim?</strong></p><p>\r\n					Untuk kiriman didaerah kota bandung tidak dibebankan biaya kirim alias gratis (minimal order 100rb), sedangkan untuk klien diluar kota akan kami berikan alternative pilihan jasa ekspedisi dengan kualitas, kecepatan dan harga yang optimal.</p></td></tr><tr><td><p>\r\n					14</p></td><td><p>\r\n					<strong>Misal saya membutuhkan produk cetak dalam waktu singkat?</strong></p><p>\r\n					Hubungi Divisi Marketing kami, jelaskan secara detail spesifikasi dan waktu yang harus dipenuhi, kami akan memberi waktu yang tercepat yang bisa kami penuhi, dengan syarat file desain sudah final dan pembayaran 70% diawal.</p></td></tr><tr><td><p>\r\n					15</p></td><td><p>\r\n					<strong>Bagaimana bila saya mau repeat order?</strong></p><p>\r\n					Data desain anda akan kami simpan rapi selama 3 tahun, bilamana ada perubahan desain (tidak merubah konsep) maka bisa kami akomodir tanpa tambahan biaya.</p></td></tr><tr><td><p>\r\n					16</p></td><td><p>\r\n					<strong>1 box kartu nama isi berapa banyak kartu?</strong></p><p>\r\n					1 box kartu nama berisi 100 kartu.</p></td></tr><tr><td><p>\r\n					17</p></td><td><p>\r\n					<strong>Pada nota apa itu porporasi dan numerator?</strong></p><p>\r\n					Porporasi adalah garis putus-putus untuk memudahkan menyobek nota sedangkan numerator adalah angka-angka berurutan yang ada pada nota.</p></td></tr><tr><td><p>\r\n					18</p></td><td><p>\r\n					<strong>Minimal pemesanan nota?</strong></p><p>\r\n					Minimal pemesanan nota adalah 1 rim, misal ukuran A4 minimal 10 buku, 1 buku berisi 50 set.</p></td></tr><tr><td><p>\r\n					19</p></td><td><p>\r\n					<strong>Apakah hari minggu tutup?</strong></p><p>\r\n					Iya, hari minggu dan tanggal merah kami libur</p><p>\r\n					Jam kerja kami :</p><p>\r\n					Senin s/d juma’at 08.00 – 17.00 WIB</p><p>\r\n					Selasa 08.00 – 16.00 WIB</p><p>\r\n					Sabtu 08.00 – 12.00 WIB</p></td></tr><tr><td><p>\r\n					20</p></td><td><p>\r\n					<strong>Ada kontak person yang bisa saya hubungi?</strong></p><p>\r\n					Kami bisa dihubungi melalui :</p><p>\r\n					YM   : <a href=\"mailto:cs.tafio@yahoo.com\">cs.tafio@yahoo.com</a></p><p>\r\n					          <a href=\"mailto:marketing.tafio@yahoo.com\">marketing.tafio@yahoo.com</a></p><p>\r\n					Kantor  (+Fax) 022-5221199</p><p>\r\n					Call Center flexi 022 61300300</p><p>\r\n					Call Center simpti  085321300300</p><p>\r\n					Call Center im3  085721300300</p><p>\r\n					Call Center xl  081910001020</p><p>\r\n					PIN BB 29713582</p><p>\r\n					Divisi Marketing kami akan selalu siap melayani anda</p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					No :</p></td><td><p>\r\n					Dept : Marketing / Pemasaran</p></td><td><p>\r\n					No Revisi:</p></td></tr><tr><td><p>\r\n					Halaman :   dari</p></td><td><p>\r\n					Tgl Terbit : 14 JANUARI 2013</p></td><td><p>\r\n					Tgl Revisi :</p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'marketing' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(129, 'Service Photocopy 7 feb 2013', '<p>\r\n	Ganti Cleaning Blade</p>\r\n<p>\r\n	Bersihin roller pake sanpoli</p>\r\n<p>\r\n	bubuhi bedak sedikit</p>\r\n<p>\r\n	sering nyangkut bersihin roller pake kain+sanpoli (bagian yg sering di copot)</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:37:09'),
(130, 'KETENTUAN SCAN FOTO/GAMBAR/IMAGE/LAINNYA', '<p>\r\n	1. Scan harus menggunakan Photoshop, tidak menggunakan CorelDraw</p>\r\n<p>\r\n	2. Resolusi harus 600 Dpi</p>\r\n<p>\r\n	3. Blur Image (terutama foto) dengan Gaussian Blur 1 pixel, pastikan titik-titik hilang (harus halus)</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(131, 'AGENDA KERJA 1', '<p>\r\n	 </p>\r\n<p>\r\n	1. Cek email untuk melihat perkembangan order desain yang sedang dikerjakan</p>\r\n<p>\r\n	2. Tilawah : Membaca  Alquran &amp; Menyimak (sesuai giliran harian)</p>\r\n<p>\r\n	3. Inspirasi  Pagi : Membacakan Buku untuk Memotivasi team &amp; personal atau Menyimak</p>\r\n<p>\r\n	4. Brifing : Membahas pekerjaan yang akan dan sedang berlangsung (perkembangan, kendala, dll.) </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'desain' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(132, 'AGENDA KERJA DESAIN', '<p>\r\n	 </p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	1. Mempelajari permasalahan kreatif brief dari marketing/klien</p>\r\n<p>\r\n	2. Mencarai solusi/konsep desain/ide desain</p>\r\n<p>\r\n	3. Pengumpulan data/bahan-bahan yang dibutuhkan (text, logo, gambar/foto, dll.)</p>\r\n<p>\r\n	4. Menyusun tata letak elemen-elemen layout (text, gambar/foto, logo, dll.)</p>\r\n<p>\r\n	5. Pemilihan font/jenis huruf sesuai tema/konsep desain</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'desain' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(133, 'PENGIRIMAN', '<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					<strong>CV. TAFIO TOTAL SOLUSI</strong></p></td><td><p>\r\n					<strong>PENGIRIMAN</strong></p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n<p>\r\n	 </p>\r\n<table><tbody><tr><td><p>\r\n					<strong>NO</strong></p></td><td><p>\r\n					<strong>KEGIATAN </strong></p></td></tr><tr><td><p>\r\n					1</p></td><td><p>\r\n					Pengiriman barang dilakukan setelah pembayaran lunas, bila belum lunas barang tidak boleh dikirim, kecuali ada jaminan dari marketing bahwa akan dibayar.</p></td></tr><tr><td><p>\r\n					2</p></td><td><p>\r\n					Pengiriman  untuk kota bandung gratis dengan syarat minimal order 100 ribu,</p></td></tr><tr><td><p>\r\n					3</p></td><td><p>\r\n					Ketentuan pemilihan jasa ekspedisi :</p><ul><li>\r\n						Daerah Jakarta : Travel (baraya, Xtrans dll), Elteha, Indah cargo</li><li>\r\n						Daerah Jateng dan Jatim : BIS, Cobra, Leuwi gajah, Pahala Kencana</li><li>\r\n						Daerah Sumatra : BIS, Indah Cargo</li><li>\r\n						Daerah Timur : Via Laut dan Udara</li><li>\r\n						Luar Negeri : POS, DHL, Cargo (ada minimum, harus banyak)</li><li>\r\n						TIKI / JNE hanya bila barang mendesak dan klien yang meminta</li></ul><p>\r\n					Syarat-syarat pengiriman</p></td></tr><tr><td><p>\r\n					4</p></td><td><p>\r\n					Standar berat barang :</p><ul><li>\r\n						Berat HVS 1 rim A4 = 3 kg</li><li>\r\n						Berat Banner Bahan Flexi 1x1Meter 0,5Kg</li></ul></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'marketing' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(134, 'Lipatan Mesin di JKT (katalog DSE)', '<p>	<img alt=\"\" src=\"/project/pb/gambar/images/1_%202013-03-08%2014_56_39.jpg\"></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/2_%202013-03-08%2014_57_01.jpg\"></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/3_%202013-03-08%2014_58_30.jpg\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(136, 'JO BAHAN BOX CLEOPATRA', '<p>\r\n	 </p>\r\n<p>\r\n	Project</p>\r\n<p>\r\n	 </p>\r\n<table><tbody><tr><td>\r\n				box</td><td>\r\n				kemasan merk cleopatra</td><td>\r\n				250</td><td>\r\n				3.000</td><td><p>\r\n					<b>warna:</b>1 warna (hitam)  <b>bahan:</b>AP 310 gr  <b>foil:</b>emas  <b>emboss</b>   <b>pond</b>  <b>laminasi:</b>doff 2 muka  <b>ukuran:</b>17,2 x 4 x 7 cm,  <b>mesin:</b>cetak 2 muka  lainnya:REPEAT ORDER, minta 50 pcs dulu  </p></td></tr></tbody></table>\r\n<p>\r\n	 </p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	Bahan Plano 108x79 cm</p>\r\n<p>\r\n	dipotong jadi 9, 6 untuk box, 3 untuk selongsong (2x3 pcs)</p>\r\n<p>\r\n	ukuran potong 36x26 cm</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(137, 'HARGA PISAU POND', '<p>\r\n	Pisau biasa   =  325/cm</p>\r\n<p>\r\n	Pisau Standar  = 375/cm (yg biasa kita pakai)</p>\r\n<p>\r\n	Pisau Viking  =  500/cm</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(138, 'HARGA INDIGO JKT', '<p>\r\n	Stiker chromo A3 = 2300 /pcs</p>\r\n<p>\r\n	HVS 100 gr, Ap 120, 150, matte 120, 150 gr = 1500 per 1000 lembar, &gt; 1000 pcs 1200</p>\r\n<p>\r\n	AP 190, 210, 260,</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:37:09'),
(139, 'Kartu Nama Nona Rara', '<p>	Update 10-07-13</p><p>	Kartu nama ada tambahan alamat di bawah Krang Kring: </p><p>	 </p><p>	Plaza Semanggi lt. GF No. 197 Jakarta</p><p>	 </p><p>	Sparasi pake yg 30%</p><p>	 </p><p>	file terakhir: Z:\\_hari ini\\polar\\tgl 21-01-14</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/kartu%20nama%20nona%20rara%2030%25%2C%20bikin%20CTP%201%20warna%2C%20mesin%2052(1).jpg\"></p><p>	JO terakhir (10-07-13)</p><p>	Order 2000, area cetak 186x232 mm, bahan AP 260 gr 100x65 cm, potong jadi 12 (ukuran 216x250 mm), cetak BBS, 1 warna , pink, doff 2 muka, pond L 50</p><p>	JO terakhir (21-01-14)</p><p>	Order 2000, area cetak 186x240 mm, bahan AP 260 gr 100x65 cm, potong jadi 12 (ukuran 216x250 mm), cetak BBS, 1 warna , pink, doff 2 muka, pond L 50</p><p>	Sudah dilengkapi arah tarikan &amp; pisau L 50</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/JO%20kartu%20nama%20Nona%20rara.jpg\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(140, 'Kartu Berobat Dr. Sandrik (Repeat order)', '<table><tbody><tr><td>				Update 19 Juli 2013</td><td>				 </td><td>				 </td><td>				 </td><td>				 </td></tr></tbody></table><table><tbody><tr><td>				kartu berobat</td><td>				dr.sandrik</td><td>				order 1.000</td><td>				harga 200/pc</td><td><b>warna:</b>1 warna (hitam)  <b>bahan:</b>AP 260 gr plano 100x65 cm <b>ukuran:</b>11 x 7 cm  <b>mesin:</b>gto 52  lainnya:offset 2 muka</td><td>				area cetak 237x297 mm</td><td>				bahan potong jadi 8 (25x32.5 cm) 1 area cetak jadi 8</td><td>				jumlah bahan 19 plano</td></tr></tbody></table><p>	 </p><p>	 </p><p>	 </p><p>	 </p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/kartu%20berobat%20pasien_set%2C%20240x324%20mm%2C%20BBS.jpg\"></p><p>	 </p><p>	file terakhir di pake : rutin\\dr.sandrik\\2014\\kartu berobat pasien\\post set</p><p>	JO terakhir</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/JO%20Kartu%20Berobat%20Dr_%20Sandrik.jpg\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(141, 'UNTUK SEMUA UNDANGAN A5 INDIGO (distandarkan)', '<p>	- Amplop undangan harus disesuaikan ukurannya agar bisa naik 2 mata dalam mesin indigo.</p><p>	- Apabila naik offset, settingan tetap sama, ukuran pun akan sama.</p><p>	- isi menyesuaikan dengan amplop.</p><p>	- arahkan semua order undangan yg ukuran A5 bisa naik 2 mata, seperti layout di bawah ini.</p><p>	- ukuran yg distandarkan adalah: <strong>Amplop 145x202 mm, isi 140x197 mm. Lidah tutup 46 mm.</strong></p><p>	- contoh undangan A5 yg eksisting adalah, Balai Diklat Sumandi, RSHS, Media citra.</p><p>	 </p><p>	tampilan amplop + pisau 2 mata:</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/layout%20undangan%20A5%20indigo%2C%202%20mata.jpg\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(142, 'UKURAN BAHAN AP PLANO DI JKT', '<p>\r\n	Bahan ukuran plano di JKT<br>\r\n	65x90<br>\r\n	65x100<br>\r\n	61x92<br>\r\n	79x109</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(143, 'SLIP PEMBAYARAN BRI (repeat order)', '<p>	Slip Pembayaran BRI merupakan salah satu orderan yg berulang.</p><p>	Project:</p><table><tbody><tr><td><strong>slip setoran</strong></td><td><strong>jumlah 1.000 buku</strong></td><td><strong>cetak 1 warna (biru untuk bahan putih, hitam untuk bahan kuning), bahan: NCR 2 rangkap (putih &amp; kuning) ukuran:21,3 x 11,9 cm. harga 3.750</strong></td><td><strong>jilid: blok lem kiri, mesin:gto 52, 1 buku isi 50 lembar rangkap 2 .</strong></td></tr></tbody></table><table><tbody><tr><td>				 </td><td>				 </td><td>				 </td><td>				 </td><td>				 </td></tr></tbody></table><p>	JO</p><p>	area cetak = 43x32,4 cm, bahan double folio, 1 area ada 6, cetak 1 muka, potong jadi sepertiga folio.</p><p>	Kebutuhan bahan:</p><p>	NCR Putih : <strong>18 rim</strong> (top), NCR Kuning : <strong>18 rim</strong> (buttom)</p><p>	Posisi cetakan harus center, pisahkan antara cetakan sebelah kanan dengan cetkaan sebelah kiri, utk menghindari tumpukan yg geser.</p><p>	file: Z:\\Bank BRI\\2013\\Nota\\post set ------------------yg Revisi2</p><p>	Jumlah order slip setoran ini jika ada lebihan disimpen dlm stok, dimasukkan pada order selanjutnya, seperti Brataco.</p><p>	Preview film/CTP:</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/nota%20BRI%20(revisi2)%2C%20CTP%201%20warna%2C%20mesin%2052.jpg\"></p><p>	(update 10-09-13)</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/JO%20Slip%20Setoran%20BRI.jpg\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(144, 'BOX ERLYS KUE (REPEAT ORDER)', '<h2>	PROJECT</h2><table><tbody><tr><td>				box kodok besar</td><td>				17x13x7,5 cm</td><td>				order 3.000 pcs</td><td>				harga 700</td><td><b>warna:</b>1 warna magenta  <b>bahan: </b>duplek 310 gr  <b>pond</b>  <b>laminasi: </b>tanpa laminasi </td></tr></tbody></table><h2>	JOB ORDER</h2><p>	Bahan Duplek 310 gr, ukuran 120x90 cm, Beli 540 plano</p><p>	Potong jadi 6, ukuran potong 36x45 cm.</p><p>	Area cetak 326x443 mm.</p><p>	Offset 1 muka, 1 warna (magenta).</p><p>	Pond pake pisau BX 54</p><p>	Pake film di pola.</p><p>	 </p><p>	Last file Z:\\erlys kue\\2013\\kodok besar 2 17x13x7,5cm\\post set</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/box%20erlys%20kecil2.jpg\"></p><p>	 </p><p>	 </p><p>	 </p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(145, 'PAPERBAG YUMMY (REPEAT ORDER)', '<h2>	PROJECT </h2><table><tbody><tr><td>				kemasan</td><td>				yummi</td><td>				4.000</td><td>				260</td><td><b>warna:</b>2 warna (merah&amp;kuning)  <b>bahan:</b>hvs 70 gr  <b>laminasi:</b>tanpa laminasi  lainnya:ukuran:T:18,5xL:4xP:10 cm, cetak 1 muka, REPEAT ORDER  </td></tr></tbody></table><p>	 </p><h2>	JOB ORDER</h2><h3>	Order 4000 pcs</h3><p>	Bahan HVS 70 gr, ukuran plano 90x65 cm + Double Folio.</p><h3>	Kebutuhan bahan 1 Rim Plano 90x65 cm + 1 rim Double Folio.</h3><p>	Plano potong jadi 4, ukuran potong 430x325 mm, Double folio samain ukuran jadi 430x325 mm.</p><p>	Area cetak 430x300 mm. 2 mata. </p><p>	Offset 1 muka, 2 warna (merah &amp; kuning), pond pake pisau P 23.</p><p>	 </p><p>	Catatan: Hati-hati, klien tidak mau kalo lipatnya seperti bungkus gorengan.</p><p>	 </p><p>	File Z:\\Pratama Adhi Guna\\2013\\kemasan\\post set</p><p>	 </p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/paperbag%20yummy%20(sejajar)%2C%20CTP%202%20warna%2C%20mesin%2052.jpg\"></p><p>	 </p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/JO%20kemasan%20Yummy.jpg\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(146, 'STIKER SARTIKA ADVERTISING', '<p>	<strong>Format Setting Stiker Sartika</strong></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/format%20settinga%20Stiker%20sartika.jpg\"></p><p>	 </p><p>	<strong>Format potong bahan</strong></p><p>	<strong>Bahan stiker chromo ukuran 108x70 cm</strong></p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/format%20potong%20bahan%20stiker%20Sartika.jpg\"></p><p>	 </p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27');
