(147, 'BROSUR/FLYER BORMA VASMEDIKA', '<table><tbody><tr><td>												Flyer borma			</td><td>												barcode 4 jenis			</td><td>												10.000 pcs			</td><td><b>warna:</b>FC  <b>bahan:</b>AP 150 gr  <b>pond:</b>BR 17  <b>ukuran:</b>sesuai sample</td><td>				Keterangan: barcode di bagi 4 print pake stiker HVS pake laser</td></tr></tbody></table><p>	Link file: <strong>rutin\\Vassmedica Spunbond\\2012\\brosur\\borma\\post set</strong></p><p>	 </p><div>	data order offset brosur borma</div><div>	 </div><div>	1. Vassmedica</div><div>	 </div><div>	brosur borma</div><div>	 </div><div>	    a. cetak</div><div>	 </div><div>	- jumlah order 10000 pcs</div><div>	- area cetak 456x282 mm, 4 mata</div><div>	- bahan AP 150 gr</div><div>	- offset 1 muka</div><div>	- mesin SM 52</div><div>	- full colour</div><div>	 </div><div>	    b. finishing</div><div>	- tanpa laminasi </div><div>	- pond di bandung</div><div>	 </div><div>	Kirim senin, kamis 20 Feb, jam 17:00</div><div>	_______________________________________</div><div>	 </div><div>	<img alt=\"\" src=\"/project/pb/gambar/images/brosur%20borma%20vassmedica.jpg\"></div>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(148, 'MACAM-MACAM LIPATAN KERTAS', '<p>	MACAM-MACAM LIPATAN KERTAS</p><p>	 </p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/jenis%20lipatan%20surat.jpg\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(149, 'Inventaris', '<div>\r\n	<div>\r\n		 </div>\r\n	<table><tbody><tr><td>\r\n					NO</td><td>\r\n					TANGGAL</td><td>\r\n					NAMA</td><td>\r\n					BARANG</td><td>\r\n					TGL PINJAM</td><td>\r\n					TGL KEMBALI</td><td>\r\n					KETERANGAN</td></tr><tr><td>\r\n					1</td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td></tr><tr><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td></tr><tr><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td></tr><tr><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td></tr><tr><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td></tr><tr><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td></tr><tr><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td></tr><tr><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td></tr><tr><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td></tr><tr><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td></tr><tr><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td></tr><tr><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td></tr><tr><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td></tr><tr><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td></tr><tr><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td></tr><tr><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td><td>\r\n					 </td></tr></tbody></table>\r\n</div>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(151, 'WAKTU KERJA', '<ol><li>\r\n		Hari Kerja</li></ol>\r\n<ul><li>\r\n		Hari kerja dalam 1 minggu 6 hari (senin – sabtu)</li></ul>\r\n<ol><li>\r\n		Jam Kerja</li></ol>\r\n<ul><li>\r\n		Senin – Jum’at : pkl.08.00 – 16.30 WIB</li><li>Rabu pkl. 07.00-15.30 WIB</li><li>\r\n		Sabtu : pkl.08.00 – 12.00 WIB</li><li>\r\n		Istirahat 1 jam mulai pkl.12.00 – 13.00 WIB</li><li>\r\n		Jika karyawan masih bekerja diluar waktu kerja yang telah ditentukan dan atas permintaan atasannya langsung maka kelebihan jam kerja tersebut dihitung sebagai lembur</li></ul>\r\n<ol><li>\r\n		Libur Kerja</li></ol>\r\n<ul><li>\r\n		Hari ahad dan hari libur nasional</li><li>\r\n		Libur hari raya idul fitri ditentukan kemudian disesuaikan dengan kondisi yang ada ~</li></ul>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(153, 'IZIN DAN CUTI', '<ol><li>\r\n		Izin</li></ol>\r\n<ul><li>\r\n		Izin tidak masuk kerja</li></ul>\r\n<ul><li>\r\n		Jika karyawan tidak bisa masuk kerja maka harus memberitahukan ke atasannya langsung  dan bagian administrasi (bisa via tlp atau sms)</li><li>\r\n		Izin sakit selama lebih dari 2 hari maka harus menyertakan surat keterangan sakit dari dokter</li><li>\r\n		Izin tidak masuk kerja karena alasan selain sakit maka otomatis dianggap sebagai cuti dan harus mengisi <strong><em>Form Pengajuan Cuti</em></strong></li></ul>\r\n<ul><li>\r\n		Izin meninggalkan pekerjaan (IMP)</li></ul>\r\n<ul><li>\r\n		Jika akan meninggalkan pekerjaan sementara waktu maka harus memberitahukan ke atasannya langsung</li><li>\r\n		IMP bisa dilakukan jika karyawan telah hadir bekerja terlebih dahulu </li><li>\r\n		Waktu maksimal IMP adalah 3 jam kerja dan 5 kali dalam 1 bulan</li><li>\r\n		Jika IMP dilakukan sebelum karyawan masuk kerja atau melebihi waktu maksimal yang telah ditentukan maka akan mengurangi nilai tunjangan kehadiran pada bulan tersebut</li><li>\r\n		Mengisi <strong><em>Form IMP </em></strong></li></ul>\r\n<ol><li>\r\n		Cuti</li></ol>\r\n<ul><li>\r\n		Cuti regular</li><li>\r\n		Cuti diberikan kepada karyawan yang telah melewati masa percobaan kerja selama 3 bulan</li></ul>\r\n<ul><li>\r\n		Jatah cuti regular pertahun sebanyak 17 kali (12 kali cuti utama + 5 kali cuti tambahan (olahraga &amp; pengajian))</li><li>\r\n		Karyawan yang belum genap 1 tahun bekerja maka jumlah cuti yg didapatkan adalah :                                                                                                                                     1 x (jumlah bulan bekerja - masa percobaan 3 bulan) + 3x cuti tambahan</li><li>\r\n		Untuk karyawan yang tidak mengikuti kegiatan olahraga/pengajian karena kondisi tertentu maka jatah cuti regular sebanyak 15 kali</li><li>\r\n		Pengajuan cuti min 3 hari sebelum hari cuti dengan mengisi <strong><em>Form Pengajuan Cuti</em></strong> dan sudah disetujui oleh atasannya langsung</li><li>\r\n		Pengambilan cuti dalam 1 bulan hanya bisa maks 3 hari</li><li>\r\n		Jika sampai akhir tahun masih ada jatah cuti yang tidak diambil maka ada penggantian dalam bentuk uang dengan ketentuan perhitungan sbb :</li></ul>\r\n<p>\r\n	       1,5   x   <u>gaji pokok perbulan</u></p>\r\n<p>\r\n	                              25</p>\r\n<ul><li>\r\n		Pembayaran uang kompensasi cuti yang tidak diambil dilakukan di bulan pertama tahun berikutnya</li></ul>\r\n<ul><li>\r\n		Cuti khusus</li></ul>\r\n<p>\r\n	Setiap karyawan berhak mendapatkan cuti khusus selain cuti regular diatas, yaitu :</p>\r\n<ul><li>\r\n		 Cuti menikah : 3 hari (untuk pernikahan yang pertama saja)</li><li>\r\n		Cuti anggota keluarga meningga l (ayah/ibu, adik/kakak, istri/suami, anak) : 1 hari </li><li>\r\n		Cuti istri melahirkan : 1 hari</li><li>\r\n		Cuti hamil / melahirkan</li></ul>\r\n<ul><li>\r\n		Setiap karyawan wanita akan mendapat cuti hamil / melahirkan</li><li>\r\n		Jumlah waktu cuti sesuai dengan keputusan manajemen perusahaan</li><li>\r\n		Selama masa cuti tersebut, karyawan tetap mendapatkan gaji setelah dikurangi dengan tunjangan komunikasi, tunjangan transport, tunjangan kehadiran dan tunjangan lain2 (selain t.keluarga)</li></ul>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(155, 'KEGIATAN', '<p>\r\n	a. Rapat koordinasi</p>\r\n<ul><li>\r\n		Setiap bagian diwajibkan untuk melakukan rapat per bagian min 1 bulan sekali yang dipimpin oleh kepala bagiannya masing2</li><li>\r\n		Waktu, tempat dan agenda rapat ditentukan oleh manager masing-masing</li><li>\r\n		Karyawan yang tidak bisa hadir harus memberitahukan sebelumnya kepada atasannya dan harus mengisi <strong><em>Form Berita Acara Ketidakhadiran</em></strong></li></ul>\r\n<p>\r\n	b. Pengajian rutin</p>\r\n<ul><li>\r\n		Setiap karyawan diwajibkan untuk mengikuti kegiatan pengajian rutin yang diadakan oleh pihak perusahaan</li><li>\r\n		Pengelolaan pengajian dilakukan oleh pihak kedua yang ditunjuk langsung oleh perusahaan (tafio foundation)</li><li>\r\n		Pengajian rutin berupa</li><li>\r\n		- Pengajian Pekanan : 1 minggu sekali diluar waktu kerja</li><li>\r\n		- Pengajian Bulanan : 1 bulan sekali di waktu yg sudah ditentukan </li><li>\r\n		Waktu, tempat dan bentuk kegiatan ditentukan oleh pihak pengelola pengajian</li><li>\r\n		Karyawan yang tidak bisa hadir harus memberitahukan sebelumnya kepada Murobbi dan atasannya</li><li>\r\n		Mengisi <strong><em>Form Berita Acara Ketidakhadiran</em></strong></li><li>\r\n		Jika karyawan tidak hadir tanpa pemberitahuan sebelumnya atau dengan alasan yang tidak sesuai maka akan dikenakan sanski berupa pengurangan jatah cuti 1x</li><li>\r\n		Alasan yang dibenarkan : sakit, keluarga meninggal, lembur</li></ul>\r\n<p>\r\n	c. Olahraga rutin</p>\r\n<ul><li>\r\n		Setiap karyawan diwajibkan untuk mengikuti kegiatan olahraga yang diadakan oleh pihak perusahaan</li><li>\r\n		Olahraga rutin dilakukan 1 minggu sekali diluar waktu kerja</li><li>\r\n		Waktu, tempat dan bentuk kegiatan ditentukan oleh pihak perusahaan</li><li>\r\n		Karyawan yang tidak bisa hadir harus memberitahukan sebelumnya kepada atasannya</li><li>\r\n		Mengisi <strong><em>Form Berita Acara Ketidakhadiran</em></strong></li><li>\r\n		Jika karyawan tidak hadir tanpa pemberitahuan sebelumnya atau dengan alasan yang tidak sesuai maka akan dikenakan sanski berupa pengurangan jatah cuti 1x</li><li>\r\n		Alasan yang dibenarkan : sakit, keluarga meninggal, lembur</li><li>\r\n		 </li></ul>\r\n<p>\r\n	d. Donor Darah</p>\r\n<ul><li>\r\n		Setiap karyawan diwajibkan untuk mengikuti kegiatan Donor Darah yang diadakan oleh pihak perusahaan</li><li>\r\n		Donor darah dilakukan rutin 3 bulan sekali secara massal</li><li>\r\n		Waktu, tempat  kegiatan ditentukan oleh pihak perusahaan</li><li>\r\n		Karyawan yang tidak bisa hadir / tidak lolos donor darah maka harus mencoba lagi donor </li><li>\r\n		Batas Waktu percobaan ulang donor adalah 10 hari dari waktu kegiatan donor massal</li><li>\r\n		Jika di percobaan donor ulang tetep tidak berhasil dan batas waktunya sudah habis maka tidak perlu mencoba donor lagi</li></ul>\r\n<p>\r\n	e. Mukhoyam </p>\r\n<ul><li>\r\n		Setiap karyawan diwajibkan untuk mengikuti kegiatan Mukhoyam yang diadakan oleh pihak perusahaan</li><li>\r\n		Mukhoyam  dilakukan rutin 1 tahun sekali </li><li>\r\n		Waktu, tempat dan bentuk kegiatan ditentukan oleh pihak perusahaan</li><li>\r\n		Karyawan yang tidak bisa hadir harus memberitahukan sebelumnya kepada atasannya</li><li>\r\n		Mengisi <strong><em>Form Berita Acara Ketidakhadiran</em></strong></li><li>\r\n		Jika karyawan tidak hadir tanpa pemberitahuan sebelumnya atau dengan alasan yang tidak sesuai maka akan dikenakan sanski berupa pengurangan jatah cuti 1x</li><li>\r\n		Alasan yang dibenarkan : sakit, keluarga meninggal</li></ul>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(156, 'TUNJANGAN', '<ol><li>\r\n		Tunjangan makan</li></ol>\r\n<ul><li>\r\n		Makan siang karyawan sudah disediakan oleh perusahan</li><li>\r\n		Khusus untuk hari sabtu makan siang diganti dengan uang senilai Rp.20.000,-</li></ul>\r\n<ol><li>\r\n		Tunjangan Kesehatan</li></ol>\r\n<p>\r\n	Setiap karyawan berhak untuk mendapatkan tunjangan kesehatan dengan ketentuan sbb :</p>\r\n<ul><li>\r\n		Karyawan dengan status sudah menikah dan masa kerja 1 tahun atau lebih mendapatkan rp. 900.000,- pertahun</li><li>\r\n		Karyawan dengan status belum menikah dan masa kerja 1 tahun atau lebih mendapatkan rp. 600.000,- pertahun</li><li>\r\n		Masa kerja kurang dari 1 tahun nilai tunjangannya sbb :</li></ul>\r\n<p>\r\n	             <u>Masa kerja (bulan)</u>   x   nilai tunjangan kesehatan</p>\r\n<p>\r\n	                        12</p>\r\n<ul><li>\r\n		Sistem penggunaannya adalah sistem reimburst dengan menyerahkan bukti-bukti biaya pengobatan</li><li>\r\n		Tunjangan kesehatan bisa digunakan oleh karyawan yang bersangkutan dan keluarganya</li><li>\r\n		Jika sampai akhir tahun masih ada sisa yang tidak digunakan maka akan diberikan uang tunai senilai uang tunjangan yang masih tersisa</li><li>\r\n		Pembayaran uang tunjangan kesehatan yang tersisa dilakukan paling lambat di bulan pertama tahun berikutnya</li></ul>\r\n<ol><li>\r\n		Tunjangan Kecelakan Kerja</li></ol>\r\n<ul><li>\r\n		Setiap karyawan yang mengalami kecelakan selama melakukan pekerjaan maka akan mendapatkan tunjangan kecelakan kerja kecuali kecelakaan yang diakibatkan oleh kelalaian karyawan itu sendiri</li><li>\r\n		Yang dimaksud dengan kecelakaan kerja adalah kecelakaan yang menimpa seorang pegawai pada saat:</li></ul>\r\n<ul><li>\r\n		   Karyawan meninggalkan rumah/tempat tinggalnya untuk menuju tempat kerja dengan melalui jalan yang biasa dilaluinya.</li><li>\r\n		   Karyawan bekerja atau berada ditempat kerja.</li><li>\r\n		   Karyawan dalam perjalanan pulang ke rumah atau tempat tinggalnya dengan melalui jalan yang biasa dilaluinya.</li></ul>\r\n<ul><li>\r\n		Tunjangan kecelakan kerja berupa biaya pengobatan ditanggung oleh perusahaan dengan nilai yang akan ditentukan kemudian oleh pihak manajemen perusahaan sesuai dengan kondisi yang ada</li><li>\r\n		Sistem penggunaannya adalah sistem reimburst dengan menyerahkan bukti-bukti biaya pengobatan</li></ul>\r\n<ol><li>\r\n		Tunjangan Hari Raya</li></ol>\r\n<p>\r\n	Setiap karyawan berhak untuk mendapatkan tunjangan hari raya dengan ketentuan sbb :</p>\r\n<ul><li>\r\n		Masa kerja 1 tahun atau lebih mendapatkan 100% dari nilai perhitungan THR</li><li>\r\n		Masa kerja kurang dari 1 tahun nilai tunjangannya sbb :</li></ul>\r\n<p>\r\n	             <u>Masa kerja(bulan)</u>    x   nilai perhitungan THR</p>\r\n<p>\r\n	                       12</p>\r\n<ul><li>\r\n		Nilai perhitungan THR akan ditentukan kemudian sesuai keputusan pihak manajemen dan bisa berubah-rubah sesuai dengan kondisi yang ada</li><li>\r\n		Pembayaran THR dilakukan beberapa hari sebelum hari raya idul fitri</li></ul>\r\n<ol><li>\r\n		Tunjangan Kehadiran</li></ol>\r\n<p>\r\n	Setiap karyawan berhak untuk mendapatkan tunjangan kehadiran dengan ketentuan sbb:</p>\r\n<ul><li>\r\n		Nilai tunjangan kehadiran : Rp. 175.000 perbulan</li><li>\r\n		Jika karyawan terlambat atau tidak masuk kerja (kecuali cuti) 1x maka nilai tunjangan akan berkurang sebesar Rp. 100.000</li><li>\r\n		Jika karyawan terlambat atau tidak masuk kerja (kecuali cuti) 2x atau lebih maka tunjangan tunjangan kehadiran akan hilang.</li><li>\r\n		Data absensi yang diambil adalah data absensi digital</li><li>\r\n		Data absensi manual dipakai untuk backup data jika ada kendala pada sistem absensi digital sehingga data absensi karyawan tidak bisa dilihat</li><li>\r\n		Jika karyawan lupa tidak absensi digital dan data absensi manual tidak ada maka karyawan dianggap terlambat hadir pada hari tersebut </li></ul>\r\n<ol><li>\r\n		Bonus Tahunan</li></ol>\r\n<p>\r\n	Setiap karyawan berhak untuk mendapatkan bonus tahunan yang nominalnya  sesuai dengan keputusan manajemen perusahaan berdasarkan parameter sbb :</p>\r\n<ul><li>\r\n		   Kondisi keuangan perusahaan diakhir tahun</li><li>\r\n		   Lama kerja</li><li>\r\n		   Jabatan</li><li>\r\n		   Prestasi kerja</li><li>\r\n		Pembayaran bonus tahunan dilakukan paling lambat di bulan pertama tahun berikutnya</li></ul>\r\n<ol><li>\r\n		Bonus Khusus</li></ol>\r\n<ul><li>\r\n		Masa kerja 3 tahun (nilainya : 1x gaji - tunjangan kehadiran - tunjangan keluarga)</li><li>\r\n		Inovasi</li><li>\r\n		Inovasi adalah hal baru yang dilakukan untuk menunjang / meningkatkan kinerja dan hasil produksi yang lebih baik.</li></ul>\r\n<ul><li>\r\n		  Ide bisa disampaikan melalui rapat rutin bidang atau diluar rapat bidang</li><li>\r\n		  Ide akan dinilai dan diuji kelayakannya oleh bidang yang berwenang</li><li>\r\n		  Ide bisa ditujukan untuk bidangnya sendiri atau bidang lain</li><li>\r\n		  Ide harus baru dan belum pernah dilakukan sebelumnya di percetakan bandung</li><li>\r\n		Ide yang bisa diterapkan dan terbukti berhasil maka inilah yang masuk ke kategori inovasi</li><li>\r\n		Jika ada karyawan yang memenuhi salah satu dari 3 kriteria diatas maka akan mendapatkan  bonus khusus yang nilainya ditentukan oleh kebijakan perusahaan</li><li>\r\n		 </li><li>\r\n		 </li><li>\r\n		h. Tunjangan Keluarga \r\n		<div>\r\n			menikah (istri/suami) 10%  dari gaji pokok</div><div>\r\n			anak ke-1                   5% dari gaji pokok</div><div>\r\n			anak ke-2                   5% dari gaji pokok<br>\r\n			anak ke 3 dst tidak di hitung</div></li></ul>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(158, 'LARANGAN', '<p>\r\n	Larangan yang tidak boleh dilanggar oleh setiap pegawai antara lain:</p>\r\n<ol><li>\r\n		merokok </li><li>\r\n		berpacaran, dsj.</li><li>\r\n		melakukan transaksi - transaksi ribawi</li><li>\r\n		berbohong berkaitan dengan urusan pekerjaan</li><li>\r\n		melakukan manipulasi data perusahaan</li><li>\r\n		melakukan tindakan kriminal (mencuri, berkelahi, narkoba, minum minuman keras. Tato, tindik, dll)</li><li>\r\n		mempengaruhi karyawan lain untuk tidak melakukan kewajiban</li><li>\r\n		menggunakan alat-alat perusahaan tanpa ijin atasan dan menyerahkan tugas kerja kepada orang lain tanpa persetujuan atasan.</li><li>\r\n		menjalankan kendaraan/alat-alat perusahaan dengan mengabaikan syarat-syarat keselamatan kerja</li><li>\r\n		membawa keluar barang-barang milik perusahaan atau barang-barang milik orang lain tanpa ijin atasan atau pemiliknya</li><li>\r\n		mempengaruhi pegawai lain untuk melanggar ketentuan-ketentuan perusahaan</li><li>\r\n		menjalankan kendaraan perusahaan secara kebut-kebutan/tidak mengindahkan sopan santun baik di jalan raya, maupun di area perusahaan, tidak mentaati tata tertib dalam ber lalu lintas</li><li>\r\n		melakukan perbuatan asusila di lingkungan perusahaan</li><li>\r\n		mencemarkan nama baik perusahaan</li><li>\r\n		tidak diperbolehkan melakukan kegiatan usaha pribadi yang sama dengan jenis bisnis perusahaan</li></ol>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(159, 'SANKSI', '<ol><li>\r\n		Teguran Lisan</li></ol>\r\n<p>\r\n	Jika karyawan melakukan pelanggaran-pelanggaran sbb :</p>\r\n<ul><li>\r\n		Tidak masuk kerja tanpa keterangan yang jelas sebanyak 3x dalam 1 bulan</li><li>\r\n		Terlambat masuk kerja sebanyak 8x atau lebih dalam 1 bulan</li><li>\r\n		Tidak mengikuti kegiatan2 kantor tanpa alasan yg jelas sebanyak 3x</li><li>\r\n		Ketentuan yang termasuk dalam poin – poin larangan</li></ul>\r\n<p>\r\n	maka akan mendapatkan teguran lisan dengan ketentuan sbb :</p>\r\n<ul><li>\r\n		Mengisi <strong><em>Form Teguran Lisan</em></strong></li><li>\r\n		Sanki yang diterima :</li><li>\r\n		Tunjangan Kehadiran berkurang 100%· pada bulan tersebut      </li><li>\r\n		Pemotogan gaji rp. 200.000,- pada bulan tersebut</li></ul>\r\n<ul><li>\r\n		Peringatan ini akan dihapuskan apabila selama 3 (tiga) bulan ia tidak melakukan pelanggaran</li></ul>\r\n<ol><li>\r\n		SP 1</li></ol>\r\n<p>\r\n	Jika karyawan melakukan pelanggaran kembali dari point-point teguran lisan maka akan mendapatkan SP 1 dengan ketentuan sbb :</p>\r\n<ul><li>\r\n		Mengisi <strong><em>Form SP 1</em></strong></li><li>\r\n		Sanki yang diterima</li></ul>\r\n<ul><li>\r\n		Pemotogan gaji rp. 300.000,-   pada bulan tersebut</li><li>\r\n		Tunjangan Kehadiran berkurang 100% pada bulan tersebut·        </li></ul>\r\n<ul><li>\r\n		Peringatan ini akan dihapuskan apabila selama 6 (enam) bulan ia tidak melakukan pelanggaran</li></ul>\r\n<ol><li>\r\n		SP 2</li></ol>\r\n<p>\r\n	Jika karyawan melakukan pelanggaran kembali dari point-point teguran lisan setelah mendapatkan SP 1 maka akan mendapatkan SP 2 dengan ketentuan sbb :</p>\r\n<ul><li>\r\n		Mengisi <strong><em>Form SP 2</em></strong></li><li>\r\n		Sanki yang diterima</li></ul>\r\n<ul><li>\r\n		Pemotongan gaji rp. 400.000,-   pada bulan tersebut</li><li>\r\n		Tunjangan kehadiran berkurang 100% pada bulan tersebut</li><li>\r\n		Tidak mendapatkan bonus tahunan</li></ul>\r\n<ul><li>\r\n		Peringatan ini akan dihapuskan apabila selama 12 (dua belas) bulan ia tidak melakukan pelanggaran</li></ul>\r\n<ol><li>\r\n		SP 3</li></ol>\r\n<p>\r\n	Jika karyawan melakukan pelanggaran kembali dari point-point teguran lisan setelah mendapatkan SP 2 maka akan mendapatkan saksi berupa PHK secara sepihak oleh perusahaan.</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(160, 'GANTI RUGI', '<p>\r\n	Karyawan diwajibkan membayar ganti rugi kepada perusahaan apabila:</p>\r\n<ul><li>\r\n		Menghilangkan / merusak barang-barang milik perusahaan</li><li>\r\n		Karena kurang hati-hati atau karena kesalahan karyawan yang bersangkutan menimbulkan kerugian bagi perusahaan.</li><li>\r\n		Karyawan tidak mentaati kewajiban/peraturan perusahaan, sehingga menimbulkan kerugian bagi perusahaan</li></ul>\r\n<p>\r\n	Nilai ganti rugi yang harus dibayarkan oleh karyawan sesuai dengan keputusan manajemen perusahaan</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(161, 'PENUTUP', '<p>\r\n	Aturan – aturan lain yang belum diatur dalam point-point diatas maka itu menjadi kewenangan manajeman perusahan yang keputusannya tidak bisa diganggu gugat.</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(162, 'Pengaturan Parkir Kantor', '<p>\r\n	DAFTAR KARYAWAN YANG MENGGUNAKAN MOTOR PRIBADI</p>\r\n<ol><li>\r\n		Hafid                                5.  Jamil                                   9.  Sarah</li><li>\r\n		Herwin                             6.  Lukman                              10. Erwin</li><li>\r\n		Mujib                                7.  Cecep                                  11.  Mas Dzikro</li><li>\r\n		Sul                                    8.  Anna                                   12.  Roy</li></ol>\r\n<p>\r\n	 </p>\r\n<p>\r\n	Ketentuan :</p>\r\n<ol><li>\r\n		Area parkir (warna merah) itu hanya untuk parkir motor-motor yang tercantum diatas</li><li>\r\n		Dilarang untuk memarkirkan motor di Area bebas motor, area ini hanya untuk jalan keluar masuk motor</li><li>\r\n		Untuk karyawan yang menggunakan motor kantor maka parkir motornya diluar pagar (rapih, lurus sejajar pagar)</li><li>\r\n		Mohon untuk memarkirkan motornya dengan rapih sesuai aturan yang telah ditentukan</li></ol>\r\n<p>\r\n	 </p>\r\n<p>\r\n	Keterangan Gambar :</p>\r\n<ol><li>\r\n		Warna merah :  area parkir</li><li>\r\n		Warna biru      :  area bebas motor (jalan keluar – masuk motor)</li></ol>\r\n<p>\r\n	LAYOUT TEMPAT PARKIR</p>\r\n<p>\r\n	<img></p>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(163, 'TATA TERTIB PENGGUNAAN DAPUR', '<p>\r\n	 </p>\r\n<p>\r\n	Kepada semua karyawan diwajibkan untuk ikut menjaga KEBERSIHAN dan KERAPIHAN dapur ini.</p>\r\n<p>\r\n	Dengan cara :</p>\r\n<ol><li>\r\n		Setiap selesai menggunakan peralatan (piring, gelas, sendok, dll) harus dicuci kembali sampai bersih</li><li>\r\n		Simpan kembali semua peralatan yang telah digunakan ketempat semula</li><li>\r\n		Pada saat mencuci agar tidak meninggalkan sisa-sisa makan di dalam saluran air tempat cuci dan tidak membiarkan busa-busa sabun berceceran</li><li>\r\n		Diharapkan untuk selalu menggunakan peralatan makan dan minum miliknya sendiri</li><li>\r\n		Buanglah sampah pada tempatnya dengan memilah sampah sesuai kategorinya :</li></ol>\r\n<ul><li>\r\n		Sampah basah (sisa2 makan, dll)</li><li>\r\n		Sampah kering (kertas, plastik, dll)</li></ul>\r\n<p>\r\n	Demikian kami sampaikan tata tertib ini agar bisa dijalankan sebaik-baiknya oleh seluruh karyawan demi terciptanya KENYAMANAN BERSAMA</p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	Ttd</p>\r\n<p>\r\n	HRD Manajemen</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 1, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(164, 'SOP Katalog DSE', '<p>	SOP Katalog DSE</p><p>	 </p><p>	1. Cek folder katalog DSE sebelumnya (Lihat di folder Layout Rekanan):</p><p>	     Katalog DSE terpecah menjadi:</p><p>	     - Hal 1 Cover dalam (sesuaikan dengan Edisi &amp; tahunnya)</p><p>	     - Hal 2-15 Our FO (data ini tidak berubah sejak awal, kecuali ada revisi/perubahan yg baru)</p><p>	     - Hal 16-27 layout rekanan (silakan update sesuai data di web)</p><p>	     - Hal 28-31 artikel (artikel disesuaikan dengan penambahan /pengurangan jumlah rekanan)</p><p>	     - Hal 32 foto-foto rekanan FO</p><p>	2. Gabung jadi 1 file file-filedi atas, save as ke folder final</p><p>	3. Setting layout katalog DSE, save indesign-nya, export PDF-nya</p><p>	 </p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/format%20layout%20buku%20katalog%20DSE.jpg\"></p><p>	4. Print Dummy</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(165, 'Job Desk Pengiriman', '<p>\r\n	-         Cek jadwal pengiriman barang harian di project</p>\r\n<p>\r\n	-         Cek status keberadaan barang yang akan dikirim (koordinasi dengan bagian produksi dan finishing): di tempat finishing (sanggar), di kantor, pengiriman dari Jakarta (via sun express atau cipaganti travel)</p>\r\n<p>\r\n	-         Cek pengiriman barang dari Jakarta via sun express (barang harus diambil atau bisa diantar) atau cipaganti travel (pastikan pool cipaganti, no. resi dan jam keberangkatan dari Jakarta)</p>\r\n<p>\r\n	-         Packing barang yang akan dikirim (pastikan packingan sesuai standar packing dan jenis pengiriman)</p>\r\n<p>\r\n	-         Atur proses pengirimannya</p>\r\n<p>\r\n	-         Siapkan dokumen-dokumen pengiriman (surat jalan, invoice, data alamat dan dokumen lainnya jika diperlukan)</p>\r\n<p>\r\n	-         Cek jenis pengiriman (diantara langsung ke alamat ato via jasa pengiriman), jika via jasa pengiriman croscek dengan pihak jasa pengirimannya (jadwal kirim, ongkir, alamat, barang bisa diambil ke kantor atau tidak)</p>\r\n<p>\r\n	-         Koordinasi dengan bagian CS mengenai status pengirimannya (jika ada yg pending, dll)</p>\r\n<p>\r\n	-         Untuk pengiriman barang ke luar kota dan status pembayarannya belum lunas maka konfirmasi dulu ke bagian CS apa bisa langsung dikirim atau menunggu pelunasan dulu</p>\r\n<p>\r\n	-         Input data laporan hasil pengiriman di project (untuk pengiriman via jasa pengiriman maka ongkir di tulis di bagian pesan)</p>\r\n<p>\r\n	-         Ubah status diproject menjadi finish</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'pengiriman' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(166, 'Packing', '<p>\r\n	-         Setiap barang yang akan dikirim harus dipacking terlebih dahulu</p>\r\n<p>\r\n	-         Pastikan packingan rapih dan sesuai standar packing yg ditentukan</p>\r\n<p>\r\n	-         Setiap packingan harus dibeli label identitas</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'pengiriman' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(167, 'Finishing Kantor', '<p>\r\n	-         Bagian finishing kantor untuk mengerjakan finishing dengan kategori mudah dan tidak memerlukan alat khusus</p>\r\n<p>\r\n	-         Koordinasi dengan bagian produksi untuk memilah hasil cetakan yg akan di finishing di kantor dan di sanggar (pisahkan)</p>\r\n<p>\r\n	-         Untuk finishing yang di sanggar itu menjadi tanggung jawab bagian produksi</p>\r\n<p>\r\n	-         Atur proses finshing yang di kembar (koordinasi dengan bagian produksi mengenai deadline waktu, jumlah order dan jenis finishingnya)</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'pengiriman' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(168, 'Purchasing', '<p>\r\n	-         Buat jadwal untuk pengecekan status opname barang (koordinasi dengan bagian lain jika ada yang memerlukan pembelian barang)</p>\r\n<p>\r\n	-         Atur jadwal pembelian barang perminggu</p>\r\n<p>\r\n	-         Buat system stok opname barang</p>\r\n<p>\r\n	-         Buat database harga2 barang</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'pengiriman' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(169, 'Standart Packing', '<p>\r\n	 </p>\r\n<p>\r\n	1.    Pastikan Label Product  / label identitas tertera</p>\r\n<p>\r\n	2.    Pengiriman ke luar kota harus dibungkus dengan plastik standar packing</p>\r\n<p>\r\n	3.    Pengiriman diwilayah bandung dibungkus plastik apabila hujan atau kondisi lain</p>\r\n<p>\r\n	4.    Ukuran Packing:</p>\r\n<p>\r\n	       ·       Produck dikirim via paket ukuran packing menyesuikan dengan kapasitas volumetric yang ditentukan</p>\r\n<p>\r\n	       ·       Produck dikirim oleh team pb ukuran disesuaikan dengan kebutuhan yg ada</p>\r\n<p>\r\n	       ·       Produk diambil oleh klien usahakan ukuran tidak membebani klien</p>\r\n<p>\r\n	5.  Packingan khusus, dengan ketentuan : </p>\r\n<p>\r\n	<strong>     AMPLOP 23 x 11 cm (A12)</strong></p>\r\n<p>\r\n	     -  Packing amplop menggunakan box (BX 115)</p>\r\n<p>\r\n	     -  Amplop di packing per 100 pcs </p>\r\n<p>\r\n	     - Satukan dalam packingan dus / kertas</p>\r\n<p>\r\n	     Cat : untuk amplop dengan ukuran selain itu maka packing dulu dengan plastik dengan isi 50/100 pcs per pack</p>\r\n<p>\r\n	<strong>     BROSUR &amp; KOP SURAT</strong></p>\r\n<p>\r\n	     - Packing menggunakan plastik ( a4, a3 atau a2 )</p>\r\n<p>\r\n	     - Packing per 500 pcs </p>\r\n<p>\r\n	     - Satukan dalam packingan dus / kertas</p>\r\n<p>\r\n	<strong>     BUKU, NOTES (YG PAKE RING), KALENDER DUDUK</strong></p>\r\n<p>\r\n	     - bagian ring tidak boleh mengenai bagian kertas cover</p>\r\n<p>\r\n	     - posisi tumpukan harus dibuat selang-seling</p>\r\n<p>\r\n	     - jumlah yang masuk dalam 1 dus tidak boleh telalu banyak/berat, nanti bisa menyebabkan ring terlalu menekan shg ring bisa penyok</p>\r\n<p>\r\n	<strong>     MAP, STIKER, DLL</strong></p>\r\n<p>\r\n	     - Packing menggunakan plastik ( a4, a3 atau a2 )</p>\r\n<p>\r\n	     - isi per packing disesuaikan dengan kapasitas plastik yang digunakan tp dibuat seragam </p>\r\n<p>\r\n	     - Satukan dalam packingan dus / kertas</p>\r\n<p>\r\n	6.  Menjaga kerapihan packing semaximal mungkin</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'pengiriman' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(170, 'Pajak', '<ol><li>Menghitung, merekap serta membayarkan pajak sesuai jenis pajak (PPN, PPh pasal 21/26 dan PPh pasal 25) setiap bulan.</li><li>Menerbitkan faktur pajak sesuai nomor seri dengan kode status masing<sup>2</sup> transaksi (utk pemungut PPN; kode status 02..dst  ATAU faktur pajak yang PPN-nya dipungut sendiri, kode status 01..dst)</li><li>Menerbitkan SSP utk PPN dan SSP utk PPh, apabila ada transaksi yang termasuk kategori pajak keluaran (pajaknya dibayar oleh pembeli JKP/BKP, dlm hal ini disebut \"Pemungut PPN\").</li><li>Meminta SSP utk PPN dan PPh apabila ada transaksi yang termasuk pajak keluaran yang dibayar oleh pembeli JKP/BKP sebagai Pemungut PPN.</li><li>Meminta SSP dan Faktur Pajak dari pembelian barang (supplier) apabila ada transaksi Pajak Masukan dengan menggunakan faktur pajak.</li><li>Kode akun pajak dlm SSP bisa berbeda sesuai jenis pajak/transaksinya.</li><li>Menerbitkan nomor seri faktur pajak pengganti bila ada laporan pembetulan dengan faktur pajak yang harus diganti menjadi; 011..dst atau 021..dst.</li><li>Melakukan pembetulan untuk SPT Masa PPN yang harus dibetulkan.</li><li>Mengisi SSP dan Faktur Pajak diketik dengan mesin tik manual.</li></ol>\r\n			\r\n<p>\r\n	 </p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'administrasi' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:54:20');
INSERT IGNORE INTO `data_sops` (`id`, `judul`, `isi`, `sop_bagian_id`, `global`, `created_at`, `updated_at`) VALUES
(171, 'daily notes', '<ul><li>\r\n		Adobe CS6 semua crack pake 64 bit, kecuali Indesign CS6 pake crack 32 bit.</li><li>\r\n		Photoshop CS6 Extended 64 bit &amp; Illustrator CS6 64 bit, copy crack 64bit ke Program File &amp; Program File (x86)</li><li>\r\n		Adobe acrobat pake Adobe CS4, crack 64 bit, harus ada program lain yg nyala, contoh PSD.</li><li>\r\n		format nama file proses indigo: NAMA BARANG_BAHAN_1MKA/2MKA_DOFF/GLOSSY/TANPA_JUMLAH PCS_DEADLINE</li><li>\r\n		akses project: PB 192.168.88.200/pb, ID 192.168.88.200/id, GK 192.168.88.200/gerai</li></ul>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(173, 'hal hal yang perlu di perhatikan sebelum memulai finishing', '<p>\r\n	1. cek cetakan yang akan di kerjakan di tempat finishing<br>\r\n	2. buat dummy atau contoh dulu, cobain sampai jadi item yang di inginkan.<br>\r\n	3. cari permasalahnya atau sesuatu yang terlihat tabu (halam kepotong atau gambar kepotong dan lain sebagainya).<br>\r\n	4. kalau muncul sesuatu yang terlihat tabu atau muncul permasalahan konsultasikan dengan manager produksi buat mencari solusinya.<br>\r\n	5. setelah dummy  (OK) tidak ada permasalahan lanjutkan ke proses selanjutnya.<br>\r\n	6. selalu cek list sesekali dalam proses finishing hingga kerjaan tsb finish.<br>\r\n	7. setelah hasil finish, tingkatkan QCnya dan pastikan kerjaan tsb clear tidak ada permasalahan.<br>\r\n	8. hitung jumlah hasil bersihnya dari QC tsb sesuai dengan jumlah order.<br>\r\n	9. paking yang rapi n kuat sehingga tidak mengakibatkan barang tersebut rusak saat pengiriman.<br>\r\n	10. finish</p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'finishing' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(178, 'Cara arsip data bank BCA', '<p>\r\n	1.Buka BCA i-Banking </p>\r\n<p>\r\n	2.Klik individual (Login)</p>\r\n<p>\r\n	3.Masukan User ID dan Password</p>\r\n<p>\r\n	4.Klik Informasi Rekening</p>\r\n<p>\r\n	5.Klik Mutasi rekening</p>\r\n<p>\r\n	6.Masukan tanggal/bulan/tahun sesuai yang di butuhkan</p>\r\n<p>\r\n	7.klik download mutasi</p>\r\n<p>\r\n	8.setelah download selesai</p>\r\n<p>\r\n	9.Klik hasil download dan nantinya akan masuk ke excel </p>\r\n<p>\r\n	10.Cara merapikan di excel blok coloum klik data---&gt;text to columns--&gt;Delimited---&gt;klik next---&gt;ceklis Tab,semicolon,comma--&gt;Klik next--&gt;ceklis general--&gt;Klik Finish</p>\r\n<p>\r\n	5.Klik Mutasi rekening</p>\r\n<p>\r\n	6.Masukan tanggal/bulan/taun sesuai yang di butuhkan</p>\r\n<p>\r\n	7.klik download mutasi</p>\r\n<p>\r\n	8.setelah download selesai</p>\r\n<p>\r\n	9.Klik hasil download dan nantinya akan masuk ke excel </p>\r\n<p>\r\n	10.Cara merapikan di excel blok coloum klik data---&gt;text to columns--&gt;Delimited---&gt;klik next---&gt;ceklis Tab,semicolon,comma--&gt;Klik next--&gt;ceklis general--&gt;Klik Finish</p>\r\n<div>\r\n	 </div>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'keuangan' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(179, 'Cara arsip data bank Mandiri', '<p>\r\n	1.Buka Mandiri i-Banking</p>\r\n<p>\r\n	2.Klik relogin </p>\r\n<p>\r\n	3.Masukan user id dan password</p>\r\n<p>\r\n	4.Klik informasi rekening</p>\r\n<p>\r\n	5.Pilih mutasi rekening</p>\r\n<p>\r\n	6.Masukan tanggal/bln/thn yang di butuhkan </p>\r\n<p>\r\n	7.klik kirim</p>\r\n<p>\r\n	8.klik download</p>\r\n<p>\r\n	9.klik hasil download yang hasilnya akan masuk ke excel</p>\r\n<p>\r\n	10.Cara merapihkan di excel blok coloum klik data--&gt;text to coloumn--&gt;klik delimited--&gt;Next--&gt;ceklis tab,semicolon,comma--&gt;Next--&gt;ceklis general--&gt;finish</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'keuangan' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(180, 'Cara arsip data bank BSM', '<p>\r\n	1.Buka BSMNet</p>\r\n<p>\r\n	2.klik LOGIN disini</p>\r\n<p>\r\n	3.Masukan user id dan password</p>\r\n<p>\r\n	4.di kolom rekening pilih Tabungan/Giro</p>\r\n<p>\r\n	5.Pilih yang TEGUH HADI JUNAEDI pada kolom kiri klik Mutasi rekening</p>\r\n<p>\r\n	6.maukan tanggal/bln/thn sesuai kebutuhan </p>\r\n<p>\r\n	7.klik submit</p>\r\n<p>\r\n	8.klik versi cetak</p>\r\n<p>\r\n	9.blok dari atas sampai coloum akhir klik kanan pilih salin</p>\r\n<p>\r\n	10.buka MS.excel klik kanan pilih Paste</p>\r\n<p>\r\n	11.Geser coloum untuk merapihkan </p>\r\n<div>\r\n	 </div>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'keuangan' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(182, 'Cara merubah warna dgn teknik color style di corel draw', '<h3>	<strong>Color Style</strong></h3><p>	Window &gt; Dockers &gt; Color Style</p><p>	(Shortcut-nya Ctrl+F6)</p><p>	 </p><h3>	Konversi warna RGB ke CMYK</h3><p>	<img alt=\"\" src=\"/project/pb/gambar/images/Warna%20RGB.jpg\"></p><p>	<strong>                                 Warna-warna RGB</strong></p><p>	 </p><p>	Drag &amp; Drop kumpulan warna-warna yg akan kita ubah dengan color style ke bilah :</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/Drag%20here2.jpg\"></p><p>	<strong>Drag here to add color style &amp; generate a harmony</strong></p><p>	 </p><p>	 </p><p>	Opsi Create Color Styles setelah drag &amp; drop</p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/Create%20Color%20Styles.jpg\"></p><p>	opsi yg perlu diperhatikan :</p><p>	- Create color styles from : <strong>Both fill &amp; outline</strong></p><p>	- Checklist pada Convert all color styles to : <strong>CMYK</strong></p><p>	 </p><p>	<img alt=\"\" src=\"/project/pb/gambar/images/Warna%20CMYK.jpg\"></p><p>	<strong>                                Warna-warna CMYK</strong></p><p>	 </p><p>	 </p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'setting' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(183, 'Maintenance Motor Kantor', '<p>\r\n	1. Service Rutin</p>\r\n<p>\r\n	     service yang diberlakukan adalah : </p>\r\n<p>\r\n	     - ganti oli : federal oil / standar honda</p>\r\n<p>\r\n	     - service standar</p>\r\n<p>\r\n	     - kampas rem</p>\r\n<p>\r\n	     waktu service sebulan sekali, kecuali motor untuk marketing waktu service nya 2 bulan sekali</p>\r\n<p>\r\n	2. Jika ada perbaikan selain yg di ketentuan service rutin, maka harus konfirmasi dahulu ke Supervisor General Affair (GA)</p>\r\n<p>\r\n	3. Service Motor harus dilakukan di tempat service resmi</p>\r\n<p>\r\n	4. Jikada pergantian sparepart maka sparepart lama harus diserahkan ke Supervisor General Affair (GA)</p>\r\n<p>\r\n	5. Jika motor akan digunakan keluar kota bandung maka harus izin terlebih dahulu ke manager</p>\r\n<p>\r\n	6.keadaan motor harus tetap standar, tidak boleh dimodifikasi</p>\r\n<p>\r\n	7.penggantian spare part diatas 300rb harus konfirmasi masing2 manager</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'pengiriman' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(186, 'HP HOT LINE', '<p>\r\n	<strong>SOP Hot line</strong></p>\r\n<p>\r\n	1. HP Hotline standby dari jam 08.00 s/d 21.00 tanpa jeda istirahat (dibagi menjadi Shift I dan Shift II)</p>\r\n<p>\r\n	2. Dalam HP Hotline diinstall :</p>\r\n<p>\r\n	-          Yahoo messenger <a href=\"mailto:cs.tafio@yahoo.com\">cs.tafio@yahoo.com</a></p>\r\n<p>\r\n	-          Whatsapp</p>\r\n<p>\r\n	-          BB Massanger</p>\r\n<p>\r\n	-          Email <a href=\"mailto:cs.tafio@yahoo.com\">cs.tafio@yahoo.com</a></p>\r\n<p>\r\n	3. Koneksi internet memakai WIFI dengan no Whatsapp memakai indosat dengan no telp 0857 2138 6600</p>\r\n<p>\r\n	4. Account yang dipakai untuk android <a href=\"mailto:cs.tafio@yahoo.com\">cs.tafio@yahoo.com</a></p>\r\n<p>\r\n	5. Setiap email permintaan penawaran langsung dibalas di HP, kecuali permintaan SPH dibalas oleh email gmail User HP </p>\r\n<p>\r\n	6. Penanggung Jawab HP dan kelengkapannya adalah CS Support</p>\r\n<p>\r\n	7. User HP Hotline adalah karyawan Shift I dan Shift II (pengaturan  diatur oleh Manager pelayanan)</p>\r\n<p>\r\n	8. Jadwal penggunaan HP Hot line :</p>\r\n<p>\r\n	-          Jam 08.00 – 12.00 Shift I</p>\r\n<p>\r\n	-          Jam 12. 00 – 13.00 shift II</p>\r\n<p>\r\n	-          Jam 13.00 – 17.00 shift I</p>\r\n<p>\r\n	-          Jam 17.00 – 21.00 Shift II</p>\r\n<p>\r\n	9. Semua kontak BB boleh dihapus dalam jangka waktu 3 bulan sekali</p>\r\n<p>\r\n	10. WIFI kantor aktif dari jam 06.00 s/d 21.00,<u> kondisikan chat dengan klien tepat waktu sesuai jam aktif WIFI</u></p>\r\n<p>\r\n	11. HP Hotline khusus untuk penerimaan pertama, misal tanya harga, alamat, tanya produk percetakan. Bila jadi order klien dipindah ke kontak AR yang ditunjuk SPV</p>\r\n<p>\r\n	12. Pembagian AR, ditentukan oleh SPV berdasarkan load kerjaan dan nominal order ( &lt; 10 jt CS, &gt;10jt s/d 100 jt spv, &gt; 100jt Manager)</p>\r\n<p>\r\n	13. AR yang ditunjuk wajib mengontak pertama kali ke klien untuk proses lebih lanjut (permintaan kelengkapan data klien, permintaan file desain, pembayaran DP dll)</p>\r\n<p>\r\n	14. Semua komunikasi dicatat di Follow up Shift I untuk shift II dicatat di log book</p>\r\n<p>\r\n	15. Semua komunikasi wajib dijawab dengan toleransi waktu jeda 3 menit</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'marketing' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(187, 'Job desk CS Support', '<p>\r\n	Job Desk CS Support</p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	1. Bertemu klien diluar kantor (marketing luar) dengan ijin SPV memakai form marketing luar</p>\r\n<p>\r\n	2. Maintenance perlengkapan CS, meliputi :</p>\r\n<p>\r\n	  - Maitenance Laptop ( Ghost, Antivirus, Troubleshooting dll)</p>\r\n<p>\r\n	  - Maintenance HP (delete massage, charger, toubleshooting dll)</p>\r\n<p>\r\n	  - Maintenance Printer (toubleshooting)</p>\r\n<p>\r\n	3. Menyediakan form-form yang dibutuhkan CS</p>\r\n<p>\r\n	4. bertanggung jawab terhadap sample yang dipajang dan sample hasil produksi</p>\r\n<p>\r\n	5. 1 minggu sekali sample dibuang</p>\r\n<p>\r\n	6. bertugas juga sebagai marketing online, yaitu :</p>\r\n<p>\r\n	  - Update produk di social media (Facebook, twitter)</p>\r\n<p>\r\n	  - Update artikel di blog percetakan 1 minggu sekali</p>\r\n<p>\r\n	  - update alexa rank</p>\r\n<p>\r\n	  - promosi di media online misal indonetwork, kaskus, olx dll</p>\r\n<p>\r\n	  - berinovasi mencari celah promo online</p>\r\n<p>\r\n	  - membuat laporan  markting online per minggu</p>\r\n<p>\r\n	7.  penagihan pembayaran klien, termasuk pengingatan Follow up penagihan oleh cs</p>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'marketing' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(188, 'ukuran ring', '<div>\r\n	RING SOFT COVER</div>\r\n<div>\r\n	isi 10 lbr ring 1/4              tebel 2.57 mm                 (19.5 perlobang)</div>\r\n<div>\r\n	isi 15 lbr ring 1/4              tebel 3.10 mm                 (19.5 perlobang)</div>\r\n<div>\r\n	isi 20 lbr ring 1/4              tebel 3.63 mm                 (19.5 perlobang)</div>\r\n<div>\r\n	isi 25 lbr ring 1/4              tebel 4.17 mm                 (20.2 perlobang)</div>\r\n<div>\r\n	isi 30 lbr  ring  5/16          tebel 4.70 mm                 (25.2 perlobang)</div>\r\n<div>\r\n	isi 35 lbr  ring  5/16          tebel 5.23 mm                 (25.2 perlobang)</div>\r\n<div>\r\n	isi 40 lbr  ring  3/8            tebel 5.76 mm                 (30.1 perlobang)</div>\r\n<div>\r\n	isi 45 lbr  ring  3/8            tebel 6.30 mm                 (30.1 perlobang)</div>\r\n<div>\r\n	isi 50 lbr  ring  7/16          tebel  6.83 mm                (34.6 perlobang)</div>\r\n<div>\r\n	isi 55 lbr  ring  7/16          tebel 7.36 mm                 (34.6 perlobang)</div>\r\n<div>\r\n	isi 60 lbr  ring  1/2            tebel 7.90 mm                  (44.5 perlobang)</div>\r\n<div>\r\n	isi 65 lbr  ring  1/2            tebel 8.43 mm                  (44.5 perlobang)</div>\r\n<div>\r\n	isi 70 lbr  ring  1/2            tebel  9.00 mm                 (44.5 perlobang)</div>\r\n<div>\r\n	isi 75 lbr  ring   9/16         tebel 9.50 mm                  (49.7 perlobang)</div>\r\n<div>\r\n	isi 80 lbr  ring   9/16         tebel 10.03 mm               (49.7 perlobang)</div>\r\n<div>\r\n	isi 85 lbr  ring   9/16         tebel 11.00 mm               (49.7 perlobang)</div>\r\n<div>\r\n	isi 90 lbr  ring   9/16         tebel 11.00 mm               (49.7 perlobang)</div>\r\n<div>\r\n	isi 95 lbr  ring   9/16         tebel 11.00 mm               (49.7 perlobang)<br>\r\n	isi 100 lbr  ring  9/16        tebel 11.00 mm               (49.7 perlobang)</div>\r\n<div>\r\n	isi 110 lbr  ring   5/8          tebel 11.63 mm                (59.7 perlobang) (lobang besar)</div>\r\n<div>\r\n	isi 130 lbr ring  5/8            tebel 12.16 mm                (59.7 perlobang (lobang besar)</div>\r\n<div>\r\n	isi 150 lbr ring  3/4            tebal 17.00 mm                (74.5 perlobang) (lobang besar)</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	CATATAN LOBANG RING KECIL</div>\r\n<div>\r\n	a1 lobang kiri       lobang - lobang atas 70 lobang (pakai omega (33/33)</div>\r\n<div>\r\n	a2 lobang kiri 70 lobang  - lobang atas 49 lobang (pakai omega (24/24)</div>\r\n<div>\r\n	37 cm                                                                               (pakai omega (20/20)</div>\r\n<div>\r\n	35 cm                                   - lobang atas 39 lobang (pakai omega (18/18)</div>\r\n<div>\r\n	a3 lobang kiri 49   lobang - lobang atas 38 lobang (pakai omega (15/15)</div>\r\n<div>\r\n	f4 lobang kiri 38 lobang -  lobang atas 24 lobang   (pakai omega (10/10)</div>\r\n<div>\r\n	a4 lobang kiri 34lobang - lobang atas 24 lobang   (pakai omega (10/10)</div>\r\n<div>\r\n	B5 lobang kiri 28 lobang - lobang atas 19 lobang (17x25 hasil jadi)</div>\r\n<div>\r\n	a5 lobang kiri 24 lobang - lobang atas 16 lobang</div>\r\n<div>\r\n	a6 lobang kiri 16 lobang - lobang atas 12 lobang</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	CATATAN LOBANG RING BESAR</div>\r\n<div>\r\n	a3 lobang kiri 32 lobang - lobang atas 25 lobang</div>\r\n<div>\r\n	f4 lobang kiri 25 lobang - lobang atas 16 lobang</div>\r\n<div>\r\n	a4 lobang kiri 23 lobang - lobang atas 16 lobang</div>\r\n<div>\r\n	a5 lobang kiri 16 lobang - lobang atas 11 lobang</div>\r\n<div>\r\n	a6 lobang kiri 11 lobang - lobang atas 7 lobang</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	.kalau tdk tau jenis ring nya pakai hitungan tebel buku.</div>\r\n<div>\r\n	<br>\r\n	<div>\r\n		cara potong lobang kecil</div>\r\n	<div>\r\n		- lobang 10 menggunakan a4 cara potong 10,10,15</div>\r\n	<div>\r\n		- lobang 12 menggunakan f4 cara potong 24,12 / 12,12,12</div>\r\n	<div>\r\n		- lobang 15 menggunakan f4 cara potong 15,23</div>\r\n	<div>\r\n		- lobang 17 menggunakan a4 cara potong 17,17,1</div>\r\n	<div>\r\n		- lobang 23 menggunakan f4 cara potong 23,15</div>\r\n	<div>\r\n		- lobang 38 menggunakan f4 cara potong 38</div>\r\n	<div>\r\n		ring diatas sesuai stb</div>\r\n</div>\r\n<p>\r\n	<br>\r\n	JUMLAH LUBANG DALAM 1 ROLL<br>\r\n	<br>\r\n	1. 1/4       84.000 lubang<br>\r\n	2. 5/16     60.000 lubang<br>\r\n	3. 3/8      43.000 lubang<br>\r\n	3. 7/16    32.000 lubang<br>\r\n	4. 1/2      20.000 l;ubang<br>\r\n	5. 9/16    19.300 lubang<br>\r\n	6. 5/8      10.500 lubang<br>\r\n	7. 3/4      7.000  lubang<br>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'finishing' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(189, 'Isi Notes (Mesin GTO / SM52)', '<p>\r\n	1. Tentukan ukuran yang ditentukan :</p>\r\n<p>\r\n	<strong>     A6 = 105mm x 148mm</strong></p>\r\n<p>\r\n	<strong>     A5 = 148mm x 210mm</strong></p>\r\n<p>\r\n	<strong>     A4 = 210mm x 297mm</strong></p>\r\n<p>\r\n	<strong>     F4 = 210mm x 330mm</strong></p>\r\n<p>\r\n	     - Set Ukuran Canvas sesuai ukuran yang ditentukan,</p>\r\n<p>\r\n	     - Pastikan desain tidak mepet,</p>\r\n<p>\r\n	     - Posisi teks dari tepi canvas minimal <strong>5mm - 7mm</strong></p>\r\n<p>\r\n	     - Buat kotak seukuran canvas <strong>(Kotak A)</strong> dengan mengklik <strong>double </strong>pada <strong>rectangle tool</strong></p>\r\n<p>\r\n	2. Dari ukuran yang telah ditentukan, <strong>Perhatikan ukuran bahan yg akan digunakan !!!</strong></p>\r\n<p>\r\n	<strong>    Ukuran Bahan :</strong></p>\r\n<p>\r\n	    - Cetakan <strong>A4, A5, A6</strong> menggunakan bahan <strong>RA3 : 43cmx30,5cm</strong></p>\r\n<p>\r\n	    - Cetakan <strong>F4 </strong>menggunakan bahan <strong>Double Folio : 43cmx33cm</strong></p>\r\n<p>\r\n	3. Set Canvas sesuai ukuran bahan dengan <strong>posisi Landscape</strong></p>\r\n<p>\r\n	4. Buat kotak seukuran canvas <strong>(Kotak B) </strong>dengan mengklik <strong>double </strong>pada <strong>rectangle tool</strong></p>\r\n<p>\r\n	    <strong>Kotak B</strong> dibagi sesuai ukuran yang diinginkan menjadi <strong>Kotak C</strong></p>\r\n<p>\r\n	<strong>    - Untuk ukuran A6 (107,5mm x 152,5mm) Portrait</strong>,</p>\r\n<p>\r\n	      Lebar/ width dibagi <strong>4, </strong>Tinggi/Height dibagi<strong> 2</strong></p>\r\n<p>\r\n	<strong>   - Untuk ukuran A5 (215mm x 152,5mm) Landscape</strong>, </p>\r\n<p>\r\n	      Lebar/ width dibagi <strong>2, </strong>Tinggi/Height dibagi <strong>2</strong></p>\r\n<p>\r\n	<strong>   - Untuk ukuran A4 (215mm x 305mm) / F4 (215mm x 330mm) Portrait</strong>, </p>\r\n<p>\r\n	      Lebar/ width dibagi<strong> 2, </strong>Tinggi/Height dibagi <strong>1</strong></p>\r\n<p>\r\n	5. Lebihkan background sesuai <strong>kotak C</strong></p>\r\n<p>\r\n	6. Tata Desain repeat di ukuran bahan (<strong>Kotak B</strong>)</p>\r\n<p>\r\n	7. Buat garis penanda potongan seukuran <strong>kotak C </strong>dengan ketentuan :</p>\r\n<p>\r\n	     - panjang garis minimal  <strong>1,5mm - 3mm </strong>dan</p>\r\n<p>\r\n	     - ketebalan garis minimal <strong>0,5pt - 1pt</strong></p>\r\n<p>\r\n	     - Komposisi warna garis disesuaikan dengan desain</p>\r\n<p>\r\n	8. Jangan lupa untuk selalu menyimpan / men <strong>SAVE </strong>hasil desain Anda setiap saat <strong>!!!</strong></p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	<strong>Catatan :</strong></p>\r\n<p>\r\n	1. Bahan kertas HVS standar : <strong>Merk Bola Dunia</strong></p>\r\n<p>\r\n	2. Pertimbangan ukuran bahan disesuaikan dengan kebutuhan cetak</p>\r\n<p>\r\n	3. Tepi atas desain dari arah tarikan minimal <strong>1,5cm</strong></p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	<strong>revisi terakhir tanggal 8 Muharram 1437 H / 22 Oktober 2015 M</strong></p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'cetak' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(190, 'KATALOG DSE', '<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/seting%20katalog%20DSE(1).jpg\"></p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'cetak' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(191, 'Nota 1/4, 1/3, 1/2 F4 (Mesin Toko)', '<p>\r\n	1. Jarak tepi/ potongan dari desain minimal <strong>5 - 7mm</strong></p>\r\n<p>\r\n	2. Jarak desain dari sisi yang diblok lem sekitar <strong>13 - 15mm </strong></p>\r\n<p>\r\n	3. Jarak tarikan mesin sekitar <strong>7mm</strong> dari sisi kertas terpanjang</p>\r\n<p>\r\n	4. Area cetak maksimal di bahan F4 : <strong>315x210mm</strong></p>\r\n<p>\r\n	5. Ukuran-ukuran yg digunakan:</p>\r\n<p>\r\n	    Ukuran Plat / CtP untuk mesin toko : </p>\r\n<p>\r\n	    - Lubang Kecil : <strong>254mm x 361mm x 0,15 mikro</strong></p>\r\n<p>\r\n	    - Lubang Besar :<strong> 254 x 394mm x 0,15 mikro</strong></p>\r\n<p>\r\n	    Bahan F4 dipasaran : 330x215mm</p>\r\n<p>\r\n	    Seting Ukuran Canvas/Desain : 330x210mm</p>\r\n<p>\r\n	    <strong>1/4 F4 = 165mm x 105mm</strong> (antar bagian sekali potong, sisi yg belum rata di sisir sekitar 2,5mm)</p>\r\n<p>\r\n	     <strong>1/3 F4 = 108mm x 210mm </strong>(antar bagian sekali potong, sisi yg belum rata di sisir sekitar 3mm)</p>\r\n<p>\r\n	    <strong>1/2 F4 = 162mm x 210mm </strong>(antar bagian sekali potong, sisi yg belum rata di sisir sekitar 3mm)</p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	<strong>Nota 1/4 Folio</strong></p>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/Nota%201%20per%204.jpg\"></p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	<strong>Nota 1/3 Folio</strong></p>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/Nota%201%20per%203.jpg\"></p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	<strong>Nota 1/2 Folio</strong></p>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/Nota%201%20per%202.jpg\"></p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'cetak' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(192, 'Tata Hal (Lipat Tumpuk)', '<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/Lipat%20Tumpuk%20Offset2.jpg\"></p>\r\n<p>\r\n	* update 16/05/2017 Utk posisi landscape</p>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/Lipat%20Tumpuk%20Indigo2.jpg\"></p>\r\n<p>\r\n	* update 16/05/2017 Utk posisi landscape</p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	<strong>8 Mata, 2 Set, 16 Halaman, OFFSET</strong></p>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/8mata%20Offset.jpg\"></p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	8 Mata, 1 Set, 8 Halaman, OFFSET, BBS</p>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/8mata%20Offset%20BBS.jpg\"></p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	8 Mata, 2 Set, 16 Halaman, OFFSET, Landscape</p>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/8%20offset%20tumpuk%20landscape.jpg\"></p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	6mata, offset</p>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/6mata%20offset(1).jpg\"></p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'cetak' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(194, 'Tata Hal (Lipat Sisip)', '<p>\r\n	<strong>Lipat Sisip (Jahit)</strong> per <strong>8; 16; 24; 32 </strong>Halaman</p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/Lipat%20Sisip%20Offset.jpg\"></p>\r\n<p>\r\n	 </p>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/Lipat%20Sisip%20Indigo.jpg\"></p>\r\n<p>\r\n	 </p>\r\n<h3>\r\n	<strong>8 MATA 16 HALAMAN</strong></h3>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/LIPAT%20SISIP%208%20MATA%201-16.jpg\"></p>\r\n<h3>\r\n	 </h3>\r\n<h3>\r\n	8 MATA LIPAT SISIP</h3>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/LIPAT%20SISIP%208%20MATA%201A.jpg\"></p>\r\n<h3>\r\n	8 MATA 8 HALAMAN - BBS</h3>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/LIPAT%20SISIP%208%20MATA%20BBS.jpg\"></p>\r\n<h3>\r\n	 </h3>\r\n<h3>\r\n	8 MATA 32 HALAMAN</h3>\r\n<p>\r\n	<img alt=\"\" src=\"/project/pb/gambar/images/LIPAT%20SISIP%208%20MATA%201-32.jpg\"></p>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'cetak' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
