(250, 'Harga Spanduk/banner', '<div>\r\n	Harga Banner mulai hari ini pakai harga :</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	bahan flexi </div>\r\n<div>\r\n	<div>\r\n		 </div>\r\n	<div>\r\n		harga</div>\r\n	<div>\r\n		260 gr = Rp 13.000 per meter</div>\r\n	<div>\r\n		280 gr = Rp 21.000 per meter</div>\r\n	<div>\r\n		Flexi CINA 340 gr = Rp 35.000 per meter<br>\r\n		Flexi KOREAN 340 gr = 40.000 per meter</div>\r\n</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	dari jasaprint:</div>\r\n<div>\r\n	<div>\r\n		260 gr = Rp 12.500 per meter</div>\r\n	<div>\r\n		280 gr = Rp 15.000 per meter</div>\r\n	<div>\r\n		Flexi CINA 340 gr = Rp 24.000 per meter BAHAN LEBIH KE GLOSSY, LEBIH TIPIS DIBANDING FLEXI KOREA 340 GR</div>\r\n	<div>\r\n		Flexi KOREAN 340 gr = 24.000 per meter BAHAN LEBIH KE DOFF, LEBIH TEBAL DIBANDING FLEXI CINA 340 GR</div>\r\n	<div>\r\n		 </div>\r\n</div>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'daftar-harga' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(251, 'Gantungan Kunci dan gelang karet', '<div>\r\n	<strong>- Harga dibawah masih harga dari vendor</strong></div>\r\n<div>\r\n	<strong>- Kontak vendor = +62 877-1444-0003 MRN Pusat Gantungan Kunci (cianjur)</strong></div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	100pcs harga 7000/pcs </div>\r\n<div>\r\n	200pcs harga 6500/pcs</div>\r\n<div>\r\n	300pcs harga 6000/pcs</div>\r\n<div>\r\n	400pcs harga 5500/pcs</div>\r\n<div>\r\n	500pcs harga 5000/pcs</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	600pcs harga 4500/pcs</div>\r\n<div>\r\n	700pcs harga 4000/pcs</div>\r\n<div>\r\n	800pcs harga 3500/pcs</div>\r\n<div>\r\n	900pcs harga 3300/pcs</div>\r\n<div>\r\n	1000pcs harga 3000/pcs</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	1500pcs harga 2700/pcs</div>\r\n<div>\r\n	2000pcs harga 2600/pcs</div>\r\n<div>\r\n	3000pcs harga 2500/pcs</div>\r\n<div>\r\n	4000pcs harga 2400/pcs</div>\r\n<div>\r\n	5000pcs harga 2300/pcs</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	6000pcs harga 2200/pcs</div>\r\n<div>\r\n	8000pcs harga 2100/pcs</div>\r\n<div>\r\n	10.000pcs harga 2000/pcs</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	<br>\r\n	Harga Gelang :</div>\r\n<div>\r\n	<div>\r\n		100pcs harga 8000/pcs </div>\r\n	<div>\r\n		200pcs harga 7500/pcs</div>\r\n	<div>\r\n		300pcs harga 7000/pcs</div>\r\n	<div>\r\n		400pcs harga 6500/pcs</div>\r\n	<div>\r\n		500pcs harga 6000/pcs</div>\r\n	<div>\r\n		600pcs harga 5500/pcs</div>\r\n	<div>\r\n		700pcs harga 5000/pcs</div>\r\n	<div>\r\n		 800pcs harga 4500/pcs</div>\r\n	<div>\r\n		900pcs harga 4000/pcs</div>\r\n	<div>\r\n		1000pcs harga 3500/pcs</div>\r\n	<div>\r\n		1500pcs harga 3400/pcs</div>\r\n	<div>\r\n		2000pcs harga 3000/pcs</div>\r\n	<div>\r\n		3000pcs harga 2800/pcs</div>\r\n	<div>\r\n		4000pcs harga 2600/pcs</div>\r\n	<div>\r\n		5000pcs harga 2500/pcs</div>\r\n	<div>\r\n		6000pcs harga 2400/pcs</div>\r\n	<div>\r\n		8000pcs harga 2300/pcs</div>\r\n	<div>\r\n		9000pcs harga 2200/pcs</div>\r\n	<div>\r\n		10.000pcs harga 2000/pcs</div>\r\n	<div>\r\n		 </div>\r\n</div>\r\n<p