(253, 'MESIN PRINTER JET PRESS', '<p>\r\n	Order &lt;= 150 pcs , di print pakai <strong>mesin jet press 75 </strong></p>\r\n<p>\r\n	<strong>Ukuran kecil : </strong><br>\r\n	area cetak maks : <strong>64x47 cm2 </strong><br>\r\n	ukuran bahan : <strong>64,8x49,8 cm2</strong><br>\r\n	maksimal print : <strong>2 A3 / 1 A2 </strong></p>\r\n<p>\r\n	<strong>Ukuran Besar : </strong><br>\r\n	area cetak maks : <strong>73x51,5 cm2 </strong><br>\r\n	ukuran bahan : <strong>75x54,3 cm2</strong></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'cetak' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27');
