(254, 'tas sekolah', '<p>\r\n	bahan dobly + bordir<br>\r\n	100 - 200 harga 170.000 ( harga jual )<br>\r\n	201 - 300 harga 165.000 ( harga jual )<br>\r\n	301 - 500 harga 160.000 ( harga jual</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'daftar-harga' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(255, 'kardus box', '<p>\r\n	bahan corrugated</p>\r\n<p>\r\n	ukuran plano dus 80x115<br>\r\n	area maximal pond 50x70 </p>\r\n<p>\r\n	harga Rp 9.000 per plano</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'daftar-harga' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(256, 'Kardus Coklat (Polosan)', '<p>\r\n	- Dus polosan</p>\r\n<p>\r\n	- Bisa sablon 1-2 warna, tinggal ditambah harga sablon</p>\r\n<p>\r\n	- Ukuran dibawah ini ready stok, tidak ada minimal order</p>\r\n<p>\r\n	- Ukuran custom, PO 2 bulan</p>\r\n<p>\r\n	<img alt=\"\"></p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'daftar-harga' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(257, 'Map Kulit Imitasi', '<div>\r\n	<strong>1. Map standart</strong></div>\r\n<ul><li>\r\n		-  bahan ASE</li><li>\r\n		-  karton 30+</li><li>\r\n		-  foil logo dan tulisan</li><li>\r\n		-  mika buat nama almamater</li><li>\r\n		-  Mika buat foto</li><li>\r\n		-  mika dalam belakang sampul</li><li>\r\n		-  plastik bening / buram</li><li>\r\n		-  plastik perkalian 2 dokumen</li><li>\r\n		-  harga <strong>plastik bening</strong> 2 dokumen <strong>Rp 1.800</strong></li><li>\r\n		-  harga <strong>platik buram</strong> 2 dokumen <strong>Rp 2.000</strong></li><li>\r\n		-  harga <strong>cover Rp 13.000</strong></li></ul>\r\n<div>\r\n	Minimal order 100 pcs tinggal ditambah margin selisih</div>\r\n<div>\r\n	Jika dibawah 100 pcs semua ongkos ditanggung pemesan</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	<div>\r\n		<strong>2. Map diatas standart</strong></div>\r\n	<ul><li>\r\n			-  bahan ASE</li><li>\r\n			-  pakai busa + kapital</li><li>\r\n			-  karton 30+</li><li>\r\n			-  foil logo dan tulisan</li><li>\r\n			-  mika buat nama almamater</li><li>\r\n			-  mika buat foto</li><li>\r\n			-  mika dalam belakang sampul</li><li>\r\n			-  plastik bening / buram</li><li>\r\n			-  plastik perkalian 2 dokumen</li><li>\r\n			-  harga <strong>plastik bening</strong> 2 dokumen <strong>Rp 1.800</strong></li><li>\r\n			-  harga <strong>platik buram</strong> 2 dokumen <strong>Rp 2.000</strong></li><li>\r\n			-  harga <strong>cover Rp 19.000</strong></li></ul>\r\n	<div>\r\n		Minimal order 100 pcs tinggal ditambah margin selisih</div>\r\n	<div>\r\n		Jika dibawah 100 pcs semua ongkos ditanggung pemesan</div>\r\n</div>\r\n<p>\r\n	 </p>\r\n<div>\r\n	<u><strong>Contoh 1 :</strong></u></div>\r\n<div>\r\n	<strong>Map standart</strong> untuk 10 dokumen surat (5 lembar), plastik bening</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	Plastik = Rp 1.800 x 5 lbr = <strong>Rp 9.000</strong></div>\r\n<div>\r\n	Cover  = <strong>Rp 13.000</strong></div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	=&gt; Rp 9.000 + Rp 13.000 = Rp 22.000 x 1.5 = <strong>Rp 33.000 </strong></div>\r\n<div>\r\n	(mainkan saja pengalinya biar ada pengurangan harga jika bnyak )</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	<div>\r\n		<u><strong>Contoh 2 :</strong></u></div>\r\n	<div>\r\n		<strong>Map diatas standart</strong> untuk 10 dokumen surat (5 lembar), plastik bening</div>\r\n	<div>\r\n		 </div>\r\n	<div>\r\n		Plastik = Rp 1.800 x 5 lbr = <strong>Rp 9.000</strong></div>\r\n	<div>\r\n		Cover  = <strong>Rp 19.000</strong></div>\r\n	<div>\r\n		 </div>\r\n	<div>\r\n		=&gt; Rp 9.000 + Rp 19.000 = Rp 28.000 x 1.5 = <strong>Rp 42.000 </strong></div>\r\n	<div>\r\n		(mainkan saja pengalinya biar ada pengurangan harga jika bnyak )</div>\r\n</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	* Contoh diatas untuk isi plastik bening, kalau plastik buram tinggal dirubah hitungannya</div>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'daftar-harga' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:52:32'),
(258, 'UKURAN POTONG DAN PISAU BOX SHOPEE', '<p>\r\n	1.BOX 22X11X5 (SHAHIDA) ukuran pot bahan 39x33,5 jadi 6 dan 2 ukurn 60x22,5 (BX 141 DAN L217)<br>\r\n	2.BOX 22x11x5 (bukaan smping) ukuran potong bahan 22,5x60 jadi 8 (BX 163)</p>\r\n<p>\r\n	3.BOX 18X18X5 ukuran potong bahan 52x29 jadi 3 gabung (BX 167)<br>\r\n	4.BOX 20X20X5 ukuran potong bahan 56x31 jadi 5 gabung (BX 168)<br>\r\n	5.BOX 22X22X5 ukruan potong bahan 60x33 jadi 4 gabung 2 ukuran 60x22,5 (BX164)<br>\r\n	6.BOX 25X25X5  ukuran potong bahan 66x35,5  jadi 2 gabung,(BX 169)</p>\r\n<p>\r\n	7.BOX 20X10X5 ukuran potong bahan 56x22 jadi 1 gabung (BX 166)<br>\r\n	8. BOX 25X10X4 ukuran potong bahan 66x19 jdi 1 gabung (BX 165)<br>\r\n	<br>\r\n	9.BOX SOSIS 25X5X4,5 ukruan potong bahan 36x15 jadi 15 plano 109x79 (BX 170)<br>\r\n	10.BOX SOSIS 16X5X4,5 ukuran potong bahan 27x15 jdi 20 plno 1o9x79 (bx171)<br>\r\n	<br>\r\n	11.BOX 30X10X5 ukuran potong bahan 37x42 jadi 6 (BX 178)<br>\r\n	<br>\r\n	<br>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'finishing' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(259, '[Marketplace] Pengiriman via GoSend / Grab (sameday)', '<div>\r\n	POLA PENANGANAN ORDER DI MARKET PLACE</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	Khusus : pengiriman via Grab/Gojek</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	1. CS wajib mengkonfirmasi penerima melalui chat/telpon</div>\r\n<div>\r\n	2. Cara mendapatkan nomor untuk konfirmasi penerima :</div>\r\n<div>\r\n	- Tokopedia minta ke drivernya (di aplikasi nomor konsumen di hidden)</div>\r\n<div>\r\n	- Shopee dan Bukalapak cek di aplikasi</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	ALURNYA</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	Tokopedia</div>\r\n<div>\r\n	1. terima pesanan</div>\r\n<div>\r\n	2. siapkan barang, packing rapih</div>\r\n<div>\r\n	3. request pickup</div>\r\n<div>\r\n	4. driver datang minta no.hp konsumen</div>\r\n<div>\r\n	5. telp/chat wa konsumen..infokan kalo barang pesanan sedang dikirim, pastikan konsumen ada di lokasi</div>\r\n<div>\r\n	6. jika driver tidak berhasil ketemu lokasi tujuan/konsumen tdk ada ditempat dan konsumen ditelp /chat wa tdk ada respon, maka :</div>\r\n<div>\r\n	- driver klik barang sudah sampai tujuan</div>\r\n<div>\r\n	- minta barang dibawa balik lagi ke kantor kita</div>\r\n<div>\r\n	- ada kompensasi biaya senilai ongkir atas pengiriman kembali tersebut</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	Shopee &amp; Bukalapak</div>\r\n<div>\r\n	1. terima pesanan </div>\r\n<div>\r\n	2. siapkan barang, packing rapih</div>\r\n<div>\r\n	3. sebelum request pickup, telp/chat wa dulu konsumennya...infokan bahwa pesanan akan dikirim, jadi pastikan konsumen ada di lokasi tujuan pengiriman</div>\r\n<div>\r\n	4. jika telp/chat wa tidak ada respon maka jangan klik request pickup terlebih dahulu</div>\r\n<div>\r\n	5. request pickup baru dilakukan jika konsumen sudah bisa di telp/balas chat wa nya<img alt=\"\"></div>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'marketing' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(260, '[Marketplace] Harga Custom', '<div>\r\n	<strong>1) Kalender Mini+Memo 2021</strong></div>\r\n<div>\r\n	harga kalender mini+notes custom, spesifikasi sama dengan yang di shopee</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	100x 10.000 = 1.000.000</div>\r\n<div>\r\n	200 x 7.500 = 1.500.000</div>\r\n<div>\r\n	300 x 5.500 = 1.650.000</div>\r\n<div>\r\n	400 × 4.000 = 1.600.000</div>\r\n<div>\r\n	500 x 3.000 = 1.750.000</div>\r\n<div>\r\n	750 × 2.500 = 1.875.000</div>\r\n<div>\r\n	1.000 x 2.000 = 2.000.000</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	<strong>2) Kalender Duduk 2021 Custom Foto</strong></div>\r\n<div>\r\n	kalender foto<br>\r\n	- ukuran total 13x18.5<br>\r\n	- ukuran kalender 6x12<br>\r\n	- ukuran foto 9.5x 12 / full cetak<br>\r\n	- kalender 7 lbr<br>\r\n	- bahan kalender dan dudukan ap/ac 260 gr<br>\r\n	- tanpa laminasi<br>\r\n	- model persis seperti diatas cuma beda dudukan dicetak bukan di bolong buat fotonya.<br>\r\n	- free plastik undangan<br>\r\n	200 pcs harga 7.000<br>\r\n	300 pcs harga 6.000<br>\r\n	400 pcs harga 5.000<br>\r\n	500 pcs harga 4.000<br>\r\n	700 pcs harga 3.000<br>\r\n	1.000 pcs harga 2.900<br>\r\n	<br>\r\n	harga belum termasuk ongkir toped &amp; biaya desain<br>\r\n	waktu 7 hari PO toped</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	3) Dus Kraft 275 gr Uk. 16x14x2 cm</div>\r\n<div>\r\n	Order dus kraft 275 gr polos laminasi lobang ( dalam) ukuran 16x14x2 cm</div>\r\n<pre>\r\n100 pcs harga 5.000\r\n200 pcs harga 3.000\r\n300 pcs harga 2.400\r\n500 pcs harga 1.900\r\n1.000 pcs harga 1.200\r\n2.000 pcs harga 1.000\r\n\r\nIni rincian harganya kaa</pre>\r\n<p>\r\n	 </p>\r\n<p>\r\n	4) Lakban Handeru</p>\r\n<div>\r\n	Lakban handeru</div>\r\n<div>\r\n	1. Lebar 4.8 mm x panjang 90 yard / 82 meter</div>\r\n<div>\r\n	Harga per pcs 7.500</div>\r\n<div>\r\n	Harga per roll 43.500 ( isi 6 )</div>\r\n<div>\r\n	Harga per dus 500.000 ( isi 72 )</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	Hpp 6.600</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	2. Lebar 4.8 mm x panjang 72 yard / 65meter</div>\r\n<div>\r\n	Harga per pcs 6.500</div>\r\n<div>\r\n	Harga per roll 37.500 ( isi 6 )</div>\r\n<div>\r\n	Harga per dus 432.000 ( isi 72 )</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	<div>\r\n		Hpp 5.400 </div>\r\n	<div>\r\n		 </div>\r\n</div>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'daftar-harga' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(261, 'ukuran amplop coklat jadi', '<p>\r\n	UKURAN AMPLOP COKLAT JADI :</p>\r\n<p>\r\n	kabinet 110x240 mm</p>\r\n<p>\r\n	super kabinet 140 x 270 mm</p>\r\n<p>\r\n	super kabinet 120 x 280 mm</p>\r\n<p>\r\n	1/2 folio 190 x 250 mm</p>\r\n<p>\r\n	quarto 210 x 300 mm</p>\r\n<p>\r\n	a4 220 x 300 mm</p>\r\n<p>\r\n	folio (F4) 240 x 345 mm</p>\r\n<p>\r\n	map 275 x 375 mm</p>\r\n<p>\r\n	super map 290 x 390 mm</p>\r\n<p>\r\n	A3 330 x 430 mm</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'daftar-harga' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:37:09'),
(262, 'bahan samson kraft', '<div>\r\n	kraft 275 = Rp 3.500</div>\r\n<div>\r\n	kraft 350 = Rp 4.500</div>\r\n<div>\r\n	kraft 400 = Rp 5.000</div>\r\n<div>\r\n	kraft 500 = Rp 6.000</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	plano 90 x 120 cm </div>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'daftar-harga' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(263, 'PRINT CUT', '<p>\r\n	ukuran 29.5 x 47 cm</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'cetak' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:37:09'),
(264, 'REFUND', '<p>\r\n	proses refund :</p>\r\n<p>\r\n	- waktu proses 3 hari kerja</p>\r\n<p>\r\n	- Cek tf ke bag keuangan, apakah tfnya sudah masuk ke rek PB</p>\r\n<p>\r\n	- tidak menerima refund Cash</p>\r\n<p>\r\n	- rekening untuk refund wajib sama dengan no rek pengirim di awal</p>\r\n<p>\r\n	- apabila klien tidak mau refund boleh dijadikan deposit untuk order selanjutnya, silahkan konfirmasi ke bag keuangan</p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'marketing' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:37:09'),
(265, 'Refund Kelebihan Transfer', '<p>\r\n	1. Bagian keuangan akan <strong>mengecek Mutasi</strong> terlebih dahulu via i-banking</p>\r\n<p>\r\n	2. Proses refund harus ke <strong>nomor rekening yang sama</strong> dengan saat proses transfer masuk</p>\r\n<p>\r\n	3. Proses refund <strong>maksimal H+3</strong> dari request klien</p>\r\n<p>\r\n	4. Refund <strong>tidak boleh berupa cash</strong>, harus transfer ke nomor rekening asal</p>\r\n<p>\r\n	 </p>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'keuangan' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
