(269, 'Upload shopee', '<div>\r\n	input keuangan shopee</div>\r\n<div>\r\n	1. klik saldo saya</div>\r\n<div>\r\n	2. klik tanggal minim 1 pekan</div>\r\n<div>\r\n	3. klik semua</div>\r\n<div>\r\n	4. klik ekspor lalu downlod</div>\r\n<div>\r\n	5. buka dengan libre</div>\r\n<div>\r\n	6. save ke exel 97-2003</div>\r\n<div>\r\n	7. upload ke project</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	input order shopee</div>\r\n<div>\r\n	1. klik pesanan saya</div>\r\n<div>\r\n	2. klik semua pesanan</div>\r\n<div>\r\n	3. atur rentang tanggal minim 1 pekan</div>\r\n<div>\r\n	4. klik eksport lalu download</div>\r\n<div>\r\n	5. buka dengan libre</div>\r\n<div>\r\n	6. save ke exel 97-2003</div>\r\n<div>\r\n	7. upload ke project</div>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'order' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(270, 'upload toped', '<div>\r\n	input keuangan toped</div>\r\n<div>\r\n	1. klik saldo</div>\r\n<div>\r\n	2. klik semua transaksi</div>\r\n<div>\r\n	3. klik tanggal minim 1 pekan</div>\r\n<div>\r\n	4. downlod riwayat</div>\r\n<div>\r\n	5. buka dengan libre</div>\r\n<div>\r\n	6. save ke exel 97-2003</div>\r\n<div>\r\n	7. upload ke project</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	input order lazada</div>\r\n<div>\r\n	1. klik pesanan</div>\r\n<div>\r\n	2. klik semua pesanan</div>\r\n<div>\r\n	3. atur rentang tanggal minim 1 pekan</div>\r\n<div>\r\n	4. klik download laporan penjualan</div>\r\n<div>\r\n	5. buka dengan libre</div>\r\n<div>\r\n	6. save ke exel 97-2003</div>\r\n<div>\r\n	7. upload ke project</div>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'order' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(271, 'upload lazada', '<div>\r\n	order</div>\r\n<div>\r\n	1.pesanan</div>\r\n<div>\r\n	2. klik versi lama</div>\r\n<div>\r\n	3. klik semua</div>\r\n<div>\r\n	4. klik rentang tanggal</div>\r\n<div>\r\n	5. klik ok lalu cari</div>\r\n<div>\r\n	6. klik ekspor pencarian pesanan</div>\r\n<div>\r\n	7. klik lihat riwayat ekspor</div>\r\n<div>\r\n	8. klik download paling atas ( Download Result File )</div>\r\n<div>\r\n	9. buka menggunakan libre</div>\r\n<div>\r\n	10. save ke EXEL 97-2003</div>\r\n<div>\r\n	11. upload ke project</div>\r\n<div>\r\n	 </div>\r\n<div>\r\n	keuangan</div>\r\n<div>\r\n	1. klik saldo toko</div>\r\n<div>\r\n	2. klik semua</div>\r\n<div>\r\n	3. klik rentang tanggal</div>\r\n<div>\r\n	4. klik ok</div>\r\n<div>\r\n	5. unduh detail transaksi ( csv )</div>\r\n<div>\r\n	6. langsung upload project</div>\r\n<div>\r\n	 </div>\r\n', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'order' LIMIT 1), 0, '2026-11-25 10:37:09', '2026-11-25 10:51:27'),
(272, 'asdf', '<p>asfd</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'pengiriman' LIMIT 1), 0, '2025-01-31 22:36:37', '2025-01-31 22:36:37'),
(275, 'CUTTINGAN', '<p>SEMUA CUTTINGAN DI JASA PRINT HARUS SELESAI 1 HARI BERES, KECUALI CUTTINGAN YANG MASUK DI JAM 5 SORE BOLEH DI JADWALKAN BESOK HARINYA.<br><img alt=\"\"><img alt=\"\"></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'cetak' LIMIT 1), 0, '2025-03-05 17:36:11', '2026-11-25 10:51:27');
INSERT IGNORE INTO `data_sops` (`id`, `judul`, `isi`, `sop_bagian_id`, `global`, `created_at`, `updated_at`) VALUES
(276, 'LAMINASIAN', '<p>UNTUK LAMINASIAN, <br>1.JIKA JUMLAHNYA DIATAS 200 LBR BOLEH LAMINASIKAN KELUAR DENGAN SYARAT BAHAN SATU UKURAN <br>2.SETIAP ADA LAMINASIAN DI JADWALKAN 1 HARI (PAGI SIANG DAN SORE), JIKA ADA LAMINASIAN YANG URGENT, WAJIB LANGSUNG DI LAMINASI.<br>3. LAMINASIAN YANG MASUK LEWAT DARI JAM 5, BOLEH DI JADWALKAN KE BESOK HARINYA.</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'cetak' LIMIT 1), 0, '2025-03-05 17:39:33', '2026-11-25 10:51:27'),
(277, 'PRINTAN', '<p>1. CEK PRINTAN SESUAI DENGAN FILENYA, JIKA ADA MASALAH DARI FILE WAJIB KONFIRMASI KEPADA YANG BERSANGKUTAN BAIK ITU PB,PK,ATAU DSB.<br>2. TES PRINT 1 PCS DULU, DAN ACC KAN KEPADA YANG BERSANGKUTAN.<br>3. PASTIKAN BAHAN SESUAI DENGAN SPEK RENAME, YAITU B5,B4+,A3 MAUPUN A3+.<br>4. PASTIKAN SELALU CEK FILE KETIKA MAU NGE PRINT, ENTAH ITU FULLCOLUR ATAU BLACK WHITE.</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'cetak' LIMIT 1), 0, '2025-03-05 17:45:03', '2026-11-25 10:42:39'),
(278, 'TATA TERTIB', '<p>TATA TERTIB</p><ul><li><p>Mentaati ketentuan waktu kerja</p></li><li><p>Seluruh karyawan wajib untuk mengikuti tilawah pagi &amp; briefing pagi</p></li><li><p>Karyawan yang berada di kantor pada saat jam shalat (dhuhur &amp; ashar) berkewajiban untuk mengikuti shalat berjamaah (khusus ikhwan shalat berjamaah di masjid)</p></li><li><p>Tidak boleh mendengarkan musik saat jam kerja.</p></li><li><p>Tidak boleh menonton youtube, tiktok, dan download pribadi &amp; lainnya, saat jam kerja.</p></li><li><p>Tidak boleh merokok bagi karyawan &amp; freelance</p></li><li><p>Tidak boleh bergadang untuk kepentingan &amp; kesenangan diri sendiri, misal bermain game, dan lainnya</p></li><li><p>Dilarang berbuat asusila dilingkungan perusahaan</p></li><li><p>dilarang melakukan manipulasi data perusahaan</p></li><li><p>Tidak diperbolehkan melakukan kegiatan usaha pribadi yang sama dengan jenis bisnis perusahaan</p></li><li><p>Dilarang melakukan transaksi ribawi</p></li><li><p>Setiap hari sabtu diwajibkan sholat dzuhur berjamaah terlebih dahulu sebelum pulang.</p></li><li><p>Setiap waktu sholat, saat tiba dimesjid harus langsung bergegas untuk masuk kedalam mesjid, tidak boleh duduk atau mengobrol terlebih dahulu diteras mesjid.</p></li><li><p>Seluruh karyawan berkewajiban untuk menjaga kebersihan dan kerapihan, seperti : area tempat kerjanya, tempat makan dan minum, sandal/sepatu disimpan pada tempatnya, dan parkir kendaraan ditempat yang telah ditentukan.</p></li><li><p>Melaksanakan tugas/pekerjaan dengan sebaik-baiknya, penuh pengabdian, kesadaran dan bertanggung jawab.</p></li><li><p>Menjaga &amp; tidak membocorkan rahasia perusahaan</p></li><li><p>Memelihara dan meningkatkan keutuhan, kekompakan dan persatuan untuk menciptakan suasana kerja yang baik sesuai dengan harapan perusahaan</p></li><li><p>Menggunakan dan memelihara barang-barang milik perusahaan dengan sebaik-baiknya.</p></li><li><p>Berpenampilan rapih dan bersih.</p></li><li><p>bersikap dan bertingkah laku sopan santun terhadap masyarakat dan sesama karyawan</p></li><li><p>Bersikap sopan, jujur dan selalu mentaati perintah atasan dalam melakukan pekerjaannya serta selalu meningkatkan efisiensi dan produktifitas kerja</p></li><li><p>Tidak melakukan perbuatan yang dapat merusak atau merugikan nama baik perusahaan, pimpinan atau teman sekerja, dan harus memelihara kerjasama yang baik diantara karyawan untuk menciptakan ketenangan kerja dan memelihara ketertiban dalam perusahaan</p></li><li><p>Menggunakan, menjalankan atau menyimpan dengan baik semua peralatan atau mesin-mesin, bahan-bahan atau surat-surat berharga milik perusahaan yang dipercayakan kepadanya</p></li><li><p>Bertanggung jawab atas semua barang atau harta milik perusahaan yang dipercayakan kepadanya dan harus segera melaporkan kehilangan atau kerusakan yang terjadi terhadap barang-barang atau harta milik perusahaan tersebut kepada atasannya.</p></li></ul>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-04-24 17:20:39', '2026-11-25 10:51:27'),
(288, 'PROGRAM OLAHRAGA', '<p>PROGRAM OLAHRAGA</p><p>Futsal / Minsoc</p><ul><li><p>Setiap karyawan diwajibkan untuk mengikuti kegiatan olahraga futsal / Minsoc1 minggu sekali, yang diadakan oleh pihak perusahaan.</p></li><li><p>Wajib menggunakan celana panjang</p></li><li><p>Wajib mengikuti aturan Futsal / Minsoc sesuai arahan dari PIC Program</p></li><li><p>Karyawan yang tidak bisa hadir harus memberitahukan sebelumnya kepada ketua timnya.</p></li><li><p>Jika karyawan tidak hadir tanpa pemberitahuan sebelumnya atau dengan alasan yang tidak sesuai maka akan mempengaruhi penilaian diakhir tahun.</p></li></ul><p><br></p><p>Lari</p><ul><li><p>Setiap karyawan diwajibkan untuk lari 2x periode dalam 1 minggu</p></li><li><p>Min. jarak tempuh dalam 1x periode ialah 4 km, dengan kecepatan ( pace ) min. 8</p></li><li><p>Jadwal lari Periode 1, hari Senin – Rabu, bila hari rabu belum maelaksanakan lari, maka diberikan toleransi dihari kamis pagi, atau saat jam istirahat.</p></li><li><p>Jadwal lari periode 2, hari Jum’at – Minggu</p></li><li><p>Lari menggunakan aplikasi STRAVA.</p></li><li><p>Data lari otomatis terekap disistemku</p></li></ul><p><br></p><p>Timbang Badan</p><ul><li><p>Kegiatan timbang badan dijadwalkan 1 bulan sekali</p></li><li><p>Input data timbang badan ke sistemku</p></li><li><p>Hasil timbang badan yang masuk kategori obesitas, akan masuk program penurunan berat badan</p></li></ul><p><br></p><p>Sepeda</p><ul><li><p>Karyawan yang tinggal dalam jarak 1 hingga 7,5 kilometer dari kantor diwajibkan menggunakan sepeda untuk berangkat kerja.</p></li><li><p>Dalam satu minggu kerja (Senin sampai Sabtu), karyawan diminta menggunakan sepeda minimal 3 kali. Sisanya bebas.</p></li><li><p>Jika dalam seminggu karyawan tidak memenuhi penggunaan sepeda sebanyak 3 kali, maka akan dikenakan sanksi berupa iqob sepeda. </p></li><li><p>Karyawan yang masuk dalam ketentuan ini wajib memiliki sepeda.</p></li><li><p>Jika belum memiliki sepeda, perusahaan menyediakan bantuan subsidi sebesar 50% dari harga sepeda.</p></li><li><p>Apabila karyawan berhenti bekerja, maka subsidi tersebut wajib dikembalikan. Pengembalian akan dilakukan melalui pemotongan dari hak karyawan yang masih tersisa.</p></li><li><p>Subsidi sebesar 50% wajib dikembalikan kepada perusahaan apabila karyawan mengundurkan diri atau diberhentikan sebelum masa kerja mencapai satu tahun. Namun, jika karyawan telah bekerja selama lebih dari satu tahun, maka subsidi 50% tersebut tidak perlu dikembalikan dan apabila selama bekerja tidak boleh dijual atau di gadai.<br><br></p><p>Penyesuaian program sepeda di pekan yang bertepatan dengan PHBN/ Tanggal Merah, ataupun cuti bagi SDM yang berkewajiban menjalankan Program : </p><p>Kondisi Pertama : Jika ada tanggal merah di pekan berjalan, </p><p>kewajiban sepeda berkurang sesuai tanggal merah di pekan tersebut</p><p>misal : Tanggal 1 -6, Tanggal 2 nya Tanggal merah, Maka kewajiban bersepeda hanya menjadi 2 kali</p><p>dan berlaku akumulatif, </p><p>(jika lebih dari 1 maka kewajiban bersepda berkurang sesuai banyakna tanggal merah dipekan berjalan)</p><p>Kondisi Kedua : Jika Karyawan mengambil cuti dipekan berjalan</p><p>Kewajiban sepeda berkurang sesuai banyakna cuti yang diambil dipekan berjalan</p><p>misal : Tanggal 1-6 , Ambil 1 hari cuti maka kewajiban bersepedannya berkurang 1x, dan berlaku akumulatif,</p><p>(jika cuti diambil lebih dari 1 hari maka kewajiban bersepeda berkurang sesuai banyaknya cuti yang diambil dipekan berjalan)</p><p>Kondisi Ketiga Jika Karyawan Ambil cuti di pekan yang ada tanggal merahnya</p><p>Kewajiban sepeda berkurang sesuai banyaknya cuti dan tanggal merah di pekan berjalan</p><p></p><p>dan berlaku akumulatif.</p></li></ul>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-04-29 20:26:19', '2026-11-25 10:51:27'),
(292, 'TUNJANGAN KARYAWAN', '<ul><p>TUNJANGAN KARYAWAN</p></ul><p>Tunjangan makan</p><ul><li><p>Makan siang karyawan sudah disediakan oleh perusahan untuk hari Senin – Jum’at.</p></li><li><p>Khusus untuk hari sabtu makan siang diganti dengan uang cash Rp.20.000,-</p></li></ul><p><br></p><p>Tunjangan Kesehatan</p><p>Setiap karyawan berhak untuk mendapatkan tunjangan kesehatan dengan ketentuan sbb :</p><ul><li><p>Karyawan dengan status sudah menikah mendapatkan rp. 900.000,- pertahun</p></li><li><p>Karyawan dengan status belum menikah mendapatkan rp. 600.000,- pertahun</p></li><li><p>Masa kerja kurang dari 1 tahun nilai tunjangannya sbb :</p></li><li><p><u>Masa kerja (bulan)</u> x nilai tunjangan kesehatan</p><p>             12</p></li><li><p>Tunjangan kesehatan tidak bisa digunakan lagi bila sudah mencapai limit</p></li></ul><ul><li><p>Sistem penggunaannya adalah sistem reimburst, dengan menyerahkan bukti-bukti biaya pengobatan</p></li><li><p>Tunjangan kesehatan bisa digunakan oleh karyawan yang bersangkutan dan keluarganya.</p></li><li><p>Jika sampai akhir tahun masih ada sisa yang tidak digunakan maka akan diberikan uang tunai senilai uang tunjangan yang masih tersisa</p></li><li><p>Pembayaran uang tunjangan kesehatan yang tersisa dilakukan paling lambat di bulan pertama tahun berikutnya</p></li></ul><p><br></p><p>Tunjangan Kecelakan Kerja</p><p>Setiap karyawan yang mengalami kecelakan selama melakukan pekerjaan maka akan mendapatkan tunjangan kecelakan kerja, kecuali kecelakaan yang diakibatkan oleh kelalaian karyawan itu sendiri.</p><p>Yang dimaksud dengan kecelakaan kerja adalah kecelakaan yang menimpa seorang pegawai pada saat:</p><ul><li><p>Karyawan meninggalkan rumah/tempat tinggalnya untuk menuju tempat kerja dengan melalui jalan yang biasa dilaluinya.</p></li><li><p>Karyawan bekerja atau berada ditempat kerja.</p></li><li><p>Karyawan dalam perjalanan pulang ke rumah atau tempat tinggalnya dengan melalui jalan yang biasa dilaluinya.</p></li><li><p>Tunjangan kecelakan kerja berupa biaya pengobatan ditanggung oleh perusahaan dengan nilai yang akan ditentukan kemudian oleh pihak manajemen perusahaan sesuai dengan kondisi yang ada.</p></li><li><p>Sistem penggunaannya adalah sistem reimburst dengan menyerahkan bukti-bukti biaya pengobatan</p></li></ul><p><br></p><p>Tunjangan Hari Raya</p><p>Setiap karyawan berhak untuk mendapatkan tunjangan hari raya dengan ketentuan sbb :</p><ul><li><p>Masa kerja 1 tahun atau lebih mendapatkan 100% dari nilai perhitungan THR</p></li><li><p>Masa kerja kurang dari 1 tahun nilai tunjangannya sbb :</p></li><li><p><u>Masa kerja(bulan) </u>x nilai perhitungan THR</p><p>           12</p></li><li><p>Nilai perhitungan THR akan ditentukan kemudian sesuai keputusan pihak manajemen dan bisa berubah-rubah sesuai dengan kondisi yang ada</p></li><li><p>Pembayaran THR dilakukan beberapa hari sebelum hari raya idul fitri</p></li></ul><p><br></p><p>Tunjangan Kehadiran</p><p>Setiap karyawan berhak untuk mendapatkan tunjangan kehadiran dengan ketentuan sbb:</p><ul><li><p>Karyawan akan mendapatkan tunjangan kehadiran sebesar Rp.175.000 perbulan, bila dalam 1 bulan full absen tanpa ada keterlambatan.</p></li><li><p>Jika karyawan terlambat atau tidak absen 1x, maka nilai tunjangan akan berkurang sebesar Rp. 75.000</p></li><li><p>Jika karyawan terlambat atau tidak absen 2x, maka tunjangan kehadirannya akan hangus.</p></li><li><p>Keterlambatan akan mempengaruhi penilaian diakhir tahun.</p></li></ul><p><br></p><p>Bonus Tahunan</p><p>Setiap karyawan berhak untuk mendapatkan bonus tahunan yang nominalnya sesuai dengan keputusan manajemen perusahaan berdasarkan parameter sbb :</p><ul><li><p>Kondisi keuangan perusahaan diakhir tahun, Lama kerja, Jabatan, Prestasi kerja ( mencakup performance kinerja karyawan ).</p></li><li><p>Pembayaran bonus tahunan direalisasikan setelah data valid</p></li></ul>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-05-05 20:40:10', '2026-11-25 10:51:27'),
(293, 'KASBON', '<p>KASBON</p><ul><li><p>Setiap karyawan diberikan limit untuk setiap pengajuan kasbon, yaitu 90% dari total gaji ( diluar perhitungan bonus &amp; lemburan ),</p></li><li><p>Nilai pengajuan kasbon harus disetujui oleh atasannya terlebih dahulu.</p></li><li><p>Karyawan tidak bisa mengajukan kasbon, apabila karyawan tersebut masih mempunyai kasbon yang belum selesai / belum dilunasi.</p></li><li><p>karyawan yang akan mengajukan kasbon mengisi form yang sudah disediakan, dan disetujui oleh atasannya.</p></li><li><p>Pengembalian kasbon bisa dengan cara dicicil, yaitu maksimal dalam jangka waktu 3 bulan, dengan besar minimum pengembalian perbulannya ialah 30% dari total gaji.</p></li><li><p>Apabila pengajuan kasbon dengan nilai kasbonnya dibawah 30% dari total nilai gaji, maka kasbonnya akan langsung dipotongkan semua dipenggajian bulan berikutnya.</p></li><li><p>Apabila karyawan sudah melunasi kasbonnya, maka baru bisa mengajukan kasbon lagi, dalam rentang waktu 1 bulan kedepan setelah pelunasan.</p></li><li><p>Data pengajuan yang sudah diajukan, akan dikroscek serta divalidasi oleh bag. Finance</p></li><li><p>Bila data sudah valid &amp; disetujui, maka akan direalisasikan maksimal 2 x 24 jam ( Hari kerja )</p></li><li><p>Apabila ada karyawan berhenti/ keluar kerja, tetapi masih memiiki kasbon, maka harus diselesaikan/ dilunasi. </p></li></ul>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-05-05 20:41:30', '2026-11-25 10:51:27'),
(296, 'IJIN', '<p>IZIN</p><p>Izin tidak masuk kerja</p><ul><li><p>Jika ijin tidak masuk kerja, maka yang bersangkutan mengisi permohonan ijin tidak masuk kerja yang ada diaplikasi web sistemku.</p></li><li><p>Yang bersangkutan memberitahukan juga ke atasannya langsung ( bisa via tlp atau chat )</p></li><li><p>Bila yang bersangkutan tidak ada kabar berita, maka dianggap mangkir. Akan mempengaruhi penilaian diakhir tahun, dan performance nya akan dievaluasi kembali.</p></li><li><p>Bila mangkir lebih dari 1x, maka akan dikenakan sanksi teguran SP 1, jika sudah mendapat SP 1, tetapi dilakukan kembali maka sanksinya meningkat menjadi SP 2, dan jika berulang kembali maka sanksi naik menjadi SP 3.</p></li><li><p>Ijin tidak masuk kerja berbeda dengan cuti, sifatnya mutlak, dan statusnya tidak bisa bertukar dari ijin menjadi cuti dan sebaliknya dari cuti menjadi ijin.</p></li><li><p>Izin tidak masuk kerja karena alasan sakit, harus menyertakan surat keterangan sakit dari dokter dan kwintansi biaya berobat untuk claim penggantian biaya berobat tersebut. </p></li><li><p>Bila tidak menyertakan surat dokter dan kwitansi biaya berobat, maka tunjangan kesehatannya tidak bisa digunakan untuk claim biaya berobat tersebut.</p></li><li><p>Jika ijin sakit tidak menyertakana surat sakit, maka akan dianggap ijin biasa saja, bukan termasuk kategori sakit.</p></li><li><p>Jika yang bersangkutan sakit selama 3 hari belum bisa masuk kerja, maka atasan serta rekan kerja akan menjenguk yang bersangkutan.</p></li><li><p>Ijin sering tidak masuk kerja, maka akan mempengaruhi peniaian diakhir tahun</p></li><li><p>Ijin maksimal 3x dalam 1 bulan, bila melebihi batas ijin yang bersangkutan akan dievaluasi dan diberikan teguran secara bertahap.</p></li></ul><p><br></p><p>Izin meninggalkan pekerjaan (IMP)</p><ul><li><p>Jika akan meninggalkan pekerjaan sementara waktu, maka harus memberitahukan ke atasannya langsung, dan harus diijinkan oleh atasannya.</p></li><li><p>IMP bisa dilakukan jika karyawan telah hadir bekerja terlebih dahulu &amp; Absen diweb sistemku saat jam masuk pagi hari.</p></li><li><p>Tidak tercatat IMP bila dibawah batas toleransi yaitu 1 jam, bila meninggalkan pekerjaan lebih dari 1 jam, maka dicatat IMP.</p></li><li><p></p><ul><li><p>IMP harus mengisi form pengajuan diaplikasi web sistemku ( masuk kategori ijin, dan dikolom keterangan tulis IMP ).</p></li></ul></li><li><p>Jika sering IMP, akan mempengaruhi penilaian akhir tahun, dan performance yang bersangkutan akan dievaluasi.</p></li><li><p>IMP hanya bisa dilakukan untuk kondisi yang bersifat urgent.</p></li></ul>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-05-05 20:57:27', '2026-11-25 10:51:27'),
(299, 'PROGRAM SOSIAL', '<p>PROGRAM SOSIAL</p><p>Donor Darah</p><ul><li><p>Setiap karyawan diwajibkan untuk mengikuti kegiatan Donor Darah yang diadakan oleh pihak perusahaan</p></li><li><p>Donor darah dilakukan rutin minimal 2 bulan sekali.</p></li><li><p>Waktu, dan tempat kegiatan ditentukan oleh pihak perusahaan</p></li><li><p>Karyawan yang tidak bisa hadir / tidak lolos donor darah maka harus mencoba lagi donor darah dicabang PMI terdekat.</p></li><li><p>Batas Waktu percobaan ulang donor, adalah 7 hari dari waktu kegiatan donor darah massal</p></li><li><p>Jika dipercobaan donor ulang tetap tidak berhasil dan batas waktunya sudah habis, maka tidak perlu mencoba donor lagi</p></li><li><p>kegiatan donor darah dapat mempengaruhi penilaian diakhir tahun.</p></li></ul><p><br></p><p>Bakti Sosial</p><ul><li><p>Kegiatan Jumsih, kegiatan bakti sosial yang dlaksanakan setiap hari jumat pagi dilingkungan sekitar kantor.</p></li><li><p>Peserta jumsih terdiri dari karyawan &amp; freelance ( opsional )</p></li><li><p>Peserta jumsih akan dikelompokkan, dan ditentukan lokasi pelaksanaannya.</p></li></ul>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-05-05 21:00:05', '2026-11-25 10:51:27'),
(301, 'PROGRAM ROHANI', '<p>PROGRAM ROHANI</p><p>Tilawah &amp; Tahsin</p><ul><li><p>Setiap karyawan diwajibkan untuk mengikuti tilawah rutin melalui aplikasi yang telah ditetapkan, setiap hari minimal 1 halaman per hari,</p></li><li><p>Data Rekapan tilawah otomatis terekap disistemku</p></li><li><p>Setiap pagi dihari kerja sebelum briefing pagi, dilaksanakan tilawah bersama disetiap divisi. ( Bisa berubah sewaktu waktu )</p></li><li><p>Untuk kegiatan Tahsin, karyawan &amp; freelance ( tetap ) akan dikelompokkan dan disesuaikan dengan kemampuan membaca Qurannya</p></li><li><p>Program tahsin ( belajar mengaji ), berlaku untuk karyawan &amp; freelance tetap.</p></li><li><p>Tahsin dijadwalkan setiap 1 minggu sekali.</p></li><li><p>Tahsin dijadwalkan mulai pukul 07.30 - 09.00 WIB.( Conditional )</p></li></ul><p>Kajian Rutin</p><ul><li><p>Kajian rutin dilaksanakan 2 minggu sekali</p></li><li><p>Pemateri, waktu &amp; lokasi kajian sudah ditentukan.</p></li><li><p>SDM luar kota bisa mengikuti secara online via link yang sudah disiapkan..</p></li><li><p>Karyawan &amp; freelance tetap, absen melalui aplikasi yang telah ditentukan</p></li><li><p>Kehadiran saat kajian, dapat mempengaruhi penilaian akhir tahun</p></li></ul><p>Yaumian Sholat 5 Waktu Berjamaah</p><ul><li><p>SDM mengisi via sistemku, maksimal ( H+2 ), karena akan terkunci otomatis</p></li><li><p>Leader setiap divisi akan mengingatkan timnya yang belum mengisi yaumian</p></li><li><p>Bila telat mengisi yaumian disistemku, maka tim HR akan merekap sesuai yang terisi, untuk keperluan data performance akhir tahun.</p></li></ul><p><br></p><p>Itikaf Bulan Ramadhan</p><ul><li><p>Karyawan &amp; Freelance mengikuti kegiatan Itikaf dimesjid yang telah ditentukan.</p></li><li><p>Selama mengikuti kegiatan itikaf, karyawan &amp; Freelance harus mengikuti aturan yang telah ditentukan oleh panitia Itikaf, </p></li></ul><p><br></p><p>Baca Surat Alkahf</p><ul><li>Dibaca setiap hari Jum’at ( diusahakan baca full sampai akhir surat )</li></ul>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-05-05 21:01:42', '2026-11-25 10:51:27'),
(302, 'TEGURAN DAN SURAT PERINGATAN', '<p>SANKSI</p><p>Teguran Lisan</p><p>Jika melanggar aturan yang telah ditetapkan, maka akan diberikan teguran lisan terlebih dahulu, dan sanksi akan meningkat bila masih melakukan pelanggaran kembali.</p><ul></ul><p>SP 1</p><p>Jika karyawan melakukan pelanggaran kembali secara berulang, setelah diberikan teguran lisan, maka akan mendapatkan SP 1 dengan ketentuan sbb :</p><p>Mengisi <em>Form SP 1</em></p><p>Sanki yang diterima :</p><ul><li><p>Segala bentuk promosi dan kenaikan gaji akan ditangguhkan</p></li><li><p>mengurangi penilaian bonus akhir tahun</p></li><li><p>Peringatan ini akan dihapuskan apabila selama 1 (satu) bulan yang bersangkutan tidak melakukan pelanggaran</p></li><li><p>Bila dalam masa hukuman melakukan pelanggaran kembali, maka statusnya meningkat menjadi SP 2</p></li></ul><p><br></p><p>SP 2</p><p>Jika karyawan melakukan pelanggaran kembali setelah mendapatkan SP 1 maka akan mendapatkan SP 2 dengan ketentuan sbb :</p><p>Mengisi<em>Form SP 2</em></p><p>Sanki yang diterima :</p><ul><li><p>Segala bentuk promosi dan kenaikan gaji akan ditangguhkan</p></li><li><p>mengurangi penilaian bonus akhir tahun</p></li><li><p>Peringatan ini akan dihapuskan apabila selama 2 (dua) bulan yang bersangkutan tidak melakukan pelanggaran</p></li><li><p>Bila dalam masa hukuman melakukan pelanggaran kembali, maka statusnya meningkat menjadi SP 3</p></li></ul><p><br></p><p>SP 3</p><p>Jika Karyawan yang mendapatkan SP 3, silahkan mengundurkan diri ( resign ).</p><p><br></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-05-05 21:02:56', '2026-11-25 10:51:27'),
(308, 'ABSENSI', '<p>ABSENSI</p><p>Absensi menggunakan <em>sistem digital</em>  dengan Aplikasi Web Sistemku sebagai alat bantu absensi</p><ol><li><p>Absensi dilakukan setiap hari kerja pada saat jam datang, dan dilokasi yang sudah ditetapkan.</p></li><li><p>Absen diaplikasi web Sistemku menggunakan scan verifikasi wajah</p></li><li><p>Bila ada Karyawan &amp; Freelance, tidak melakukan absen diaplikasi web sistemku atas kelalaiannya sendiri ( diluar kendala teknis ). Tetapi yang bersangkutan hadir untuk bekerja diwaktu tersebut, maka;</p><p>Untuk Freelance, masuk kategori ijin ( mangkir ). Bila dilakukan kembali dalam periode dibulan yang sama ( lebih dari 3x ), maka akan kena sanksi secara bertahap, mulai dari teguran lisan,jika berulang dibulan berikutnya akan dikenakan sanksi tegas berupa  teguran tertulis SP 1, dan bila sudah mendapat SP 1, tetapi tetap dilakukan kembali maka sanksi teguran naik jadi SP 2, dan bila tidak ada perubahan sanksi meningkat menjadi SP 3 ( diresignkan secara sepihak ).</p><p>Untuk Karyawan, masuk kategori ijin ( mangkir ). karyawan yang tidak absen di aplikasi web sistemku dalam periode bulan yang sama lebih dari 2x, maka uang kehadirannya hangus ( dianggap terlambat absen ), Jika dalam periode bulan yg sama ( lebih dari 3x ), maka akan kena sanksi teguran lisan, jika dibulan berikutnya berulang maka dikenakan sanksi tertulis SP 1, dan bila sudah mendapat SP 1, tetap dilakukan kembali maka sanksi teguran naik jadi SP 2, dan bila tidak ada perubahan sanksi meningkat menjadi SP 3 ( diresignkan secara sepihak ).</p></li><li><p>Bila ada Karyawan &amp; Freelance, tidak melakukan absen diaplikasi web sistemku dikarenakan kendala teknis, seperti error aplikasi, HP error, dsb, bisa membuat surat rekomendasi yang disetujui atasannya langsung, dan dianggap hadir.</p></li><li><p>Akumulasi sanksi yang didapat akan mempengaruhi penilaian performa yang bersangkutan  diakhir tahun.</p></li><li><p>Untuk absen freelance harian, akan dipantau oleh atasannya langsung. Bila yang bersangkutan sering terlambat, disarankan untuk yang bersangkutan tidak usah dipanggil kerja lagi.</p></li></ol>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-05-05 21:19:03', '2026-11-25 10:51:27'),
(309, 'HARI &JAM KERJA', '<p>Hari Kerja</p><p>Hari kerja dalam 1 minggu 6 hari (senin – sabtu)</p><p><br></p><p>Jam Kerja</p><p>Senin – Jum’at : pkl.08.30 – 17.00 WIB</p><p>Sabtu : pkl.08.00 – 12.00 WIB</p><p>Istirahat 1 jam mulai pkl.12.00 – 13.00 WIB</p><p>Jika karyawan masih bekerja diluar waktu kerja yang telah ditentukan dan atas permintaan atasannya langsung, maka kelebihan jam kerja tersebut dihitung sebagai lembur.</p><p><br></p><p>Libur Kerja</p><p>Hari ahad dan hari libur nasional</p><p>Libur hari raya idul fitri ditentukan kemudian disesuaikan dengan kondisi yang ada</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-05-05 21:19:27', '2026-11-25 10:51:27'),
(320, 'LEMBUR', '<ul><ul><ul><ul><p>LEMBUR</p></ul><ul><li><p>Lembur berlaku, jika karyawan masih bekerja diluar dari waktu kerja yang telah ditentukan.</p></li><li><p>Lembur dilakukan atas permintaan atasannya langsung.</p></li><li><p>Jika lembur dilakukan 3 jam atau lebih maka ada tambahan uang makan lembur Rp.10.000,-, tapi jika lemburnya harus sampai keluar kota maka akan disesuaikan dengan kondisi yang ada</p></li><li><p>Ketentuan perhitungan uang lembur :</p><p><em>Freelance Rp. 7</em><em>,5</em><em>00</em><em> x jumlah jam lembur </em></p></li><li><p><em>Karyawan Rp. 9,000 x jumlah jam lembur</em></p></li><li><p>Untuk lembur silahkan mengisi pengajuan Lembur diaplikasi Web Sistemku, dan Atasannya mengisi data lembur bawahannya di link SS yang sudah disediakan.</p></li><li><p>Data Validasi akan direkonsil oleh tim HR</p></li><li><p>Pembayaran uang lembur, diberikan pada saat pembayaran gaji yang bersangkutan ( disatukan ).</p></li></ul></ul></ul></ul>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-05-05 21:35:27', '2026-11-25 10:51:27'),
(355, 'IQOB TILAWAH', '<ul><li><ul><li><p>Bila ada hari yang terlewat tidak melaksanakan tilawah, maka Iqob nya wajib tilawah tambahan min. 10 halaman diminggu berikutnya. Misal kelewat 1 hari, maka tambahan tilawahnya 10 halaman, bila kelewat 2 hari maka tambahan tilawahnya 20 halaman, dan berlaku kelipatan.</p></li><li><p>Bila masa toleransi masih belum juga melaksanakan, maka kena sanksi teguran serta minus point performance akan berlipat sesuai dengan berapa lama penggantian iqobnya ( makin ditunda, makin besar minus pointnya )</p></li></ul></li></ul>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-07-03 16:20:00', '2026-11-25 10:51:27'),
(358, 'IQOB LARI', '<ul><li><ul><li><p>Bila ada karyawan yang melanggar/ terlewatkan periode larinya, maka ada iqob yang harus ditunaikan. Yaitu tambahan jarak lari 2 km plus hutang lari yang belum tertunaikan ( 4km + 2 km ).</p></li><li><p>Maksimal toleransi pelaksanaan iqob, dengan alasan udzur max. 2 minggu, dengan alasan tidak udzur max 1 minggu. </p></li><li><p>Iqob harus segera dilaksanakan, bila masih terlewatkan iqobnya/ tidak dilaksanakn, maka akan dikenakan sanksi teguran serta minus point performance akhir tahun yang berlipat sesuai lama waktu penggantiannya ( makin lama, makin besar minus pointnya )</p></li><li><p>Hasil lari, baik kesesuaian jarak tempuh, pace, dan lainnya, itu akan mempengaruhi penilaian diakhir tahun.</p></li><li><p>Iqob bisa diganti denda berupa nilai uang yang telah ditetapkan</p></li></ul></li></ul>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-07-03 16:23:15', '2026-11-25 10:51:27'),
(370, 'KEGIATAN LARI KARYAWAN', '<p><strong>1. Tujuan</strong></p><p>Memberikan panduan pelaksanaan kegiatan lari yang teratur dan disiplin bagi karyawan sebagai bagian dari program kesehatan dan kebugaran perusahaan.</p><p><br></p><p><strong>2. Ketentuan Umum</strong></p><p></p><ul><li>Setiap karyawan wajib menyelesaikan dua kali lari (thermin) dalam satu minggu.</li><li>Jarak minimal 5 km per sesi lari</li><li>Tidak diberlakukan target kecepatan (tanpa pace).</li><li>Setiap sesi lari wajib direkam melalui aplikasi Strava/jika Error Boleh input manual.</li></ul><p></p><p><strong>3. Jadwal Thermin</strong></p><p></p><ul><li>Thermin 1: Dilakukan paling lambat hari Kamis.</li><li>Thermin 2: Dilakukan paling lambat hari Ahad (Minggu).</li><li>Thermin 2 dapat mulai dilakukan pada hari Rabu, jika Thermin 1 sudah diselesaikan pada hari Senin atau Selasa.</li></ul><p></p><p><strong>4. Ketentuan Pelaksanaan</strong></p><p></p><ul><li>Satu hari hanya diperbolehkan menyelesaikan satu thermin.</li><li>Tidak diperkenankan menyelesaikan dua thermin dalam satu hari</li><li>Karyawan dianjurkan untuk tidak menunda pelaksanaan thermin hingga batas waktu terakhir</li></ul><p></p><p><strong>5. Pemantauan</strong></p><p></p><ul><li>Aktivitas lari akan dipantau melalui akun Strava masing-masing karyawan.</li><li>Pelanggaran terhadap ketentuan dapat berpengaruh pada penilaian kepatuhan program</li></ul><p></p><p><br></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-07-10 18:59:56', '2026-11-25 10:51:27'),
(372, 'IQOB SEPEDA', '<p>IQOB SEPEDA</p><ul><li><p>\r\n	Jika\r\n	tidak dilaksanakan 3x dalam sepekan, maka kekurangannya wajib\r\n	ditunaikan dipekan selanjutnya</p></li><li><p>Jika dilakukan secara berturut\r\n	- turut akan dikenakan sanski teguran, serta minus point performance akan berlipat sesuai lama waktu penggantiannya ( makin ditunda, makin besar minus pointnya )</p></li><li><p>Dan bila masih berulang akan dikenakan sanksi lanjutan ( SP 1 / SP 2 / SP 3 )</p></li></ul><p>\r\n</p><p>\r\n<br>\r\n\r\n</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-07-15 20:48:10', '2026-11-25 10:52:32'),
(382, 'HARI DAN JAM KERJA', '<p>Hari Kerja</p><p>Hari kerja dalam 1 minggu 6 hari (senin – sabtu)</p><p><br></p><p>Jam Kerja</p><p>Senin – Jum’at : pkl.08.00 – 16.30 WIB</p><p>Sabtu : pkl.08.00 – 12.15 WIB</p><p>Istirahat 1 jam mulai pkl.12.00 – 13.00 WIB</p><p>Jika karyawan masih bekerja diluar waktu kerja yang telah ditentukan dan atas permintaan atasannya langsung, maka kelebihan jam kerja tersebut dihitung sebagai lembur.</p><p><br></p><p>Libur Kerja</p><p>Hari ahad dan hari libur nasional</p><p>Libur hari raya idul fitri ditentukan kemudian disesuaikan dengan kondisi yang ada</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-07-15 23:43:04', '2026-11-25 10:51:27'),
(392, 'Lari', '<h4><strong>*ATURAN LARI PB GROUP* <br></strong><strong>Update 01 Oktober 2025</strong></h4><p>1. Aplikasi Lari wajib memakai Strava.</p><p>2. wajib mengaktifkan cadence di HP atau heart rate di smart wacth.</p><p>3. Setiap anggota hanya dapat mencatat satu kali lari dalam satu hari.</p><p>4. Konfirmasi PJ lari maksimal hari Ahad pukul 20.00 WIB. bila sakit, ijin, atau ada masalah dengan aplikasi Strava (input manual) diluar itu tidak dianggap.</p><p>5. Lari tidak diperbolehkan memakai Alat (sepeda, sepeda motor dan sejenisnya).</p><p>6. Jarak total keseluruhan dalam 1 pekan minimal 10 km, dibagi minimal 2x lari (tidak ditentukan jarak per larinya, bisa 7+3 km, 5+5km, 6+4km dll), kecuali group khusus atau ada amanat khusus.</p><p>7. Bila jarak pekanan tidak tercapai, maka target pekan berikutnya menjadi 20 km.</p><p>8. Pace bebas (yang terpenting jarak tercapai). </p><p>9. Waktu lari dibatasi hingga pukul 20.00 WIB.</p><p>10. Lari di Jam Kerja diperbolehkan (waktu setelah briefing pagi) atas ijin atasan.</p><p>11. Rapel boleh digabung dengan lari pekanan,  dengan syarat minimal jarak satu kali lari berjarak 6 km.</p><p>12. Jika tidak ada laporan maka akan dipotong cuti</p><p>13. Sanksi tegas akan diberlakukan bila melanggar aturan. ( sanksi potong cuti &amp; SP ) </p><p><br></p><p>Penanggung Jawab <br>Kembar : Erwin<br>Katapang : Juli<br>Bekasi : Opik </p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-09-30 09:11:23', '2026-11-25 10:51:27'),
(393, 'Tahsin', '<h4>*TAHSIN* <br>Update 01 Oktober 2025</h4><p><br>1. Jadwal di kembar 07.00 s/d 08.30 WIB setiap hari Selasa, Rabu dan Kamis</p><p>2. Jadwal KTP &amp; bekasi 13.00 s/d Ashar (KTP setiap hari Rabu dan Jumat, Bekasi setiap hari Selasa)</p><p>3. Tidak boleh berpindah-pindah hari.</p><p>4. Ijin atau pindah hari karena halangan wajib konfirmasi.</p><p>5. Susunan dan Jadwal anggota group sesuai kebijakan PJ masing-masing tidak boleh dirubah sendiri.</p><p>6. Telat 2 kali dalam 1 bulan atau tidak hadir tanpa konfirmasi langsung dikenakan sanksi potong cuti.<br></p><p><br></p><p>Penanggung Jawab </p><p>Kembar : Erwin<br>Katapang : Juli<br>Bekasi : Opik </p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-09-30 09:13:23', '2026-11-25 10:51:27');
INSERT IGNORE INTO `data_sops` (`id`, `judul`, `isi`, `sop_bagian_id`, `global`, `created_at`, `updated_at`) VALUES
(394, 'Donor darah dan kajian intensif', '<h4>*DONOR DARAH DAN KAJIAN INTENSIF TAFIO* <br>Update 01 Oktober 2025</h4><p><br>1. Pengajian dan Donor darah mengikuti jadwal event dari Tafio </p><p>2. Wajib absensi dilokasi </p><p>3. bila berhalangan hadir (ijin/cuti) bisa live streaming jika memungkinkan</p><p>4. bila berhalangan hadir tanpa alasan langsung potong cuti</p><p>5. khusus donor darah jika tidak lolos maka mengulang kembali dalam waktu 2 pekan jika tetap tidak lolos tidak perlu mengulang kembali ( tidak ada sanksi )</p><p>6. Tiap donor darah karyawan wajib update di project</p><p>7. khusus diluar kota Bandung :</p><p>- Untuk Event Pengajian mengikuti streaming online</p><p>- untuk Event Donor darah langsung datang ke PMI terdekat ketika event Tafio dibandung berlangsung</p><p><br></p><p>*Penanggung Jawab*</p><p>Kembar : Erwin<br>Katapang : Juli<br>Bekasi : Opik </p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-09-30 09:29:20', '2026-11-25 10:51:27'),
(395, 'Futsal', '<h4></h4><p>*ATURAN FUTSAL* </p><p>Update 01 Oktober 2025</p><p></p><p><br></p><p><strong>1. WAKTU dan TEMPAT:</strong></p><p>Futsal diadakan pukul 16.00-17.00 WIB di bandung ktp &amp; bekasi (jadwal sesuai lokasi masing-masing)</p><p></p><p><br></p><p><strong>2. PAKAIAN:</strong></p><p>- Semua peserta wajib memakai CELANA PANJANG/TRAINING (bukan celana PENDEK/KOLOR) selama bermain futsal dan memakai ROMPI yang sudah di sediakan.</p><p>- Setelah bermain, Rompi dikembalikan ke petugas atau dicuci oleh masing-masing.<br><br></p><p><strong>3. KEHADIRAN</strong></p><p>- Semua peserta diharapkan hadir 10 menit sebelum waktu permainan dimulai untuk persiapan dan pengaturan tim. (Shalat ashar berjamaah dulu di mesjid)</p><p>- Semua peserta di wajibkan mengikuti kegiatan futsal dari awal sampai selesai. (TIDAK BOLEH DATANG TELAT/PULANG DULUAN) </p><p><br></p><p><strong>4. PERILAKU:</strong></p><p>- Hormati rekan-rekan sesama peserta dan jaga sportivitas dalam permainan.</p><p>- Tidak diperkenankan menggunakan bahasa atau perilaku yang tidak pantas atau merugikan orang lain. </p><p><br></p><p><strong>5. KESEHATAN dan KESELAMATAN:</strong></p><p>- Peserta diharapkan untuk menjaga kesehatan dan keselamatan diri sendiri serta peserta lainnya selama bermain (JANGAN BERMAIN KASAR).</p><p><br></p><p><strong>6. ATURAN PERMAINAN:</strong></p><p>- Dibagi menjadi 4 tim (1 tim terdiri dari 5 orang)</p><p>- Main 30 menit per pertandingan.</p><p>- Main di lapangan yang sudah di tentukan. </p><p>- Sistemnya pertandingan saling bertemu (beberapa kali bertemu setiap team)</p><p>- Membawa air minum masing-masing menggunakan thumbler.</p><p>- Memakai rompi yang sudah di sediakan.</p><p>- Setiap kapten tim bertugas menjadi wasit 1 dan wasit 2 di pertandingan yg sebelumnya di mainkan.</p><p><br></p><p><strong>7. KOMITMEN:</strong></p><p>Diharapkan semua peserta untuk mematuhi aturan ini.</p><p><br></p><p>8. Jika tidak hadir tanpa ijin syar\'i maka dikenakan ( sanksi potong cuti )</p><p><br></p><p>#UTAMAKANCARIKERINGATBUKANCARIPERINGKAT</p><p><br></p><p><strong>Penanggung Jawab </strong></p><p>Kembar : Dede</p><p>Katapang : Juli</p><p>Bekasi : Opik </p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-09-30 10:49:12', '2026-11-25 10:51:27'),
(396, 'Syarat', '<p>Syarat :</p><p></p><p>1. Karyawan</p><p></p><p>2. Sedang tidak ada kasbon di kantor</p><p></p><p>3. Nilai cicilan tidak boleh melebihi dari 1/3 gaji, klo lebih berarti harus pake DP</p><p></p><p>4. Maksimal nilai pengajuan Rp. 20.000.000, klo lebih berarti harus pake DP</p><p></p><p>5. Barang yg dibeli tidak boleh barang hiburan (misal : tv, ps, dan sejenisnya)</p><p></p><p>6. Komitmen untuk menyelesaikan cicilan sesuai dengan waktu yg sdh disepakati<br></p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-10-02 14:10:53', '2026-11-25 10:52:32'),
(397, 'Pilihan Cicilan', '<p> Pilihan cicilan :</p><p>1. 6 bulan : margin 5% dari harga barang (untuk nilai barang 3jt kebawah)</p><p></p><p>2. 1 tahun : margin 10% dari harga barang (untuk nilai barang 3jt - 7jt)</p><p></p><p>3. 2 tahun : margin 15% dari harga barang (untuk nilai barang 7jt keatas)</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2025-10-02 14:11:17', '2026-11-25 10:52:32'),
(402, 'CUTI', '<p>CUTI</p><p>Cuti regular</p><ul><li><p>Cuti diberikan kepada karyawan yang telah melewati masa percobaan kerja selama 3 bulan</p></li><li><p>Cuti regular diberikan pertahun sebanyak 12 kali.</p></li><li><p>Karyawan yang belum genap 1 tahun bekerja maka jumlah cuti yg didapatkan adalah : 1 x ( jumlah bulan bekerja - masa percobaan 3 bulan ).</p></li><li><p>Pengajuan cuti maksimal 1 hari sebelum hari cuti, dengan mengisi Form Pengajuan Cuti diaplikasi Web Sistemku</p></li><li><p>Cuti dadakan tidak diperkenankan, misal hari H tidak masuk kerja kemudian yang bersangkutan ingin dimasukkan cuti, itu tidak bisa dilakukan, akan dimasukkan kategori ijin biasa.</p></li><li><p>Pengajuan cuti harus diketahui, dan disetujui atasannya langsung.</p></li><li><p>Pengambilan cuti dalam 1 bulan hanya bisa maksimal 3 hari</p></li><li><p>Jika sampai akhir tahun masih ada jatah cuti yang tidak diambil maka ada penggantian dalam bentuk kompensasi uang.</p></li><li><p>Uang kompensasi sisa cuti, akan diberikan pada bulan pertama ditahun berikutnya</p></li></ul><p>Cuti khusus</p><p>Setiap karyawan berhak mendapatkan cuti khusus selain cuti regular diatas, yaitu :</p><ul><li><p>Cuti anggota keluarga meninggal (ayah/ibu, adik/kakak, istri/suami, anak) : 1 hari</p></li><li><p>Cuti istri melahirkan : 1 hari</p></li><li><p>Cuti hamil / melahirkan : jumlah cuti disesuaikan dengan keputusan manajemen perusahaan. Selama masa cuti tersebut, karyawan tetap mendapatkan gaji pokok.</p></li><li><p>Cuti Menikah : 1 hari</p></li></ul><p><br></p><p>Cuti Tambahan</p><ul><li><p>Karyawan dapat mengajukan cuti tambahan, bila saldo cutinya sudah habis ditahun berjalan. Dengan catatan,<em> cuti tambahan berlaku/ dapat diajukan bila kondisi sangat mendesak, dan tidak dapat ditangguhkan</em>.</p></li><li><p>Karyawan yang mengajukan cuti tambahan, harus disetujui oleh atasannya masing-masing. Dan dipastikan saat cuti, pekerjaan yang bersangkutan sudah ada yang backup untuk handle pekerjaannya.</p></li><li><p>Karyawan yang mengajukan cuti tambahan, maka akan mengurangi saldo cutinya ditahun berikutnya.</p></li><li><p>Karyawan yang mengajukan cuti tambahan, dapat melalui aplikasi Web Sisitemku. Silahkan masuk ke aplikasi Web Sistemku, klik menu IJIN/CUTI, isi kolom tipe pilih IJIN, lalu dikolom keterangan isi : (Cuti tambahan), kemudian sertakan alasannya.</p></li></ul>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2026-06-02 16:58:21', '2026-11-25 10:51:27'),
(413, 'IQOB TAHSIN', '<p>BIla terlambat menghadiri Tahsin, </p><p>untuk karyawan iqobnya menghafal ayat alquran 5 ayat ( surat ditentukan oleh PIC Rohani ), menghafal 1 hadist, dan sedekah Rp.20,000..</p><p>untuk Freelance iqobnya menghafal ayat alquran 5 ayat ( surat ditentukan oleh PIC Rohani ), menghafal 1 hadist, dan baca alquran 2 halaman.</p><p>setoran hafalan maksimal H-1 sebelum periode tahsin berikutnya.</p><p>Untuk karyawan &amp; Freelance, bila dilakukan berulang -ulang maka akan dievaluasi untuk diberikan sanksi lanjutan.</p>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2026-09-04 15:43:39', '2026-11-25 10:51:27'),
(418, 'IQOB ABSENSI FUTSAL / MINSOC', '<ul><li><p>Karyawan yang tidak bisa hadir harus memberitahukan sebelumnya kepada ketua timnya.</p></li><li><p>Jika karyawan tidak hadir tanpa pemberitahuan sebelumnya atau dengan alasan yang tidak sesuai maka kena teguran lisan, dan akan mempengaruhi penilaian diakhir tahun</p></li></ul>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2026-09-04 15:51:48', '2026-11-25 10:51:27'),
(419, 'ABSENSI FUTSAL / MINSOC', '<ul><li><p>Karyawan yang tidak bisa hadir harus memberitahukan sebelumnya kepada ketua timnya.</p></li><li><p>Jika karyawan tidak hadir tanpa pemberitahuan sebelumnya atau dengan alasan yang tidak sesuai maka kena teguran lisan, dan akan mempengaruhi penilaian diakhir tahun</p></li></ul>', (SELECT `id` FROM `sop_bagians` WHERE `slug` = 'peraturan' LIMIT 1), 0, '2026-09-04 15:52:00', '2026-11-25 10:51:27');
